CREATE OR REPLACE FUNCTION "public"."ab_audit_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO ab_audit_log (table_name, record_id, action, new_values, changed_by)
    VALUES (TG_TABLE_NAME, NEW.id, 'INSERT', to_jsonb(NEW), auth.uid());
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    INSERT INTO ab_audit_log (table_name, record_id, action, old_values, new_values, changed_by)
    VALUES (TG_TABLE_NAME, NEW.id, 'UPDATE', to_jsonb(OLD), to_jsonb(NEW), auth.uid());
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    INSERT INTO ab_audit_log (table_name, record_id, action, old_values, changed_by)
    VALUES (TG_TABLE_NAME, OLD.id, 'DELETE', to_jsonb(OLD), auth.uid());
    RETURN OLD;
  END IF;
END;
$$;


ALTER FUNCTION "public"."ab_audit_trigger"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accept_bid_atomic"("p_bid_id" "uuid", "p_job_id" "uuid", "p_contractor_id" "uuid", "p_homeowner_id" "uuid") RETURNS TABLE("success" boolean, "error_message" "text", "accepted_bid_id" "uuid", "job_status" character varying)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_bid_status VARCHAR(50);
  v_existing_accepted_bid_id UUID;
  v_job_status VARCHAR(50);
  v_job_homeowner_id UUID;
  v_accepted_bid_id UUID;
BEGIN
  SELECT homeowner_id, status
  INTO v_job_homeowner_id, v_job_status
  FROM public.jobs
  WHERE id = p_job_id
  FOR UPDATE;

  IF v_job_homeowner_id IS NULL THEN
    RETURN QUERY SELECT FALSE, 'Job not found'::TEXT, NULL::UUID, NULL::VARCHAR;
    RETURN;
  END IF;

  IF v_job_homeowner_id != p_homeowner_id THEN
    RETURN QUERY SELECT FALSE, 'Not authorized to accept bids for this job'::TEXT, NULL::UUID, NULL::VARCHAR;
    RETURN;
  END IF;

  IF v_job_status = 'assigned' OR v_job_status = 'in_progress' OR v_job_status = 'completed' THEN
    RETURN QUERY SELECT FALSE, 'Job is already assigned or in progress'::TEXT, NULL::UUID, v_job_status;
    RETURN;
  END IF;

  SELECT id
  INTO v_existing_accepted_bid_id
  FROM public.bids
  WHERE job_id = p_job_id
    AND status = 'accepted'
  FOR UPDATE;

  IF v_existing_accepted_bid_id IS NOT NULL THEN
    RETURN QUERY SELECT
      FALSE,
      'A bid has already been accepted for this job'::TEXT,
      v_existing_accepted_bid_id,
      v_job_status;
    RETURN;
  END IF;

  SELECT status
  INTO v_bid_status
  FROM public.bids
  WHERE id = p_bid_id
    AND job_id = p_job_id
    AND contractor_id = p_contractor_id
  FOR UPDATE;

  IF v_bid_status IS NULL THEN
    RETURN QUERY SELECT FALSE, 'Bid not found or does not belong to this job'::TEXT, NULL::UUID, NULL::VARCHAR;
    RETURN;
  END IF;

  IF v_bid_status = 'accepted' THEN
    RETURN QUERY SELECT FALSE, 'Bid has already been accepted'::TEXT, p_bid_id, v_job_status;
    RETURN;
  END IF;

  UPDATE public.bids
  SET
    status = 'accepted',
    updated_at = NOW()
  WHERE id = p_bid_id
  RETURNING id INTO v_accepted_bid_id;

  UPDATE public.bids
  SET
    status = 'rejected',
    updated_at = NOW()
  WHERE job_id = p_job_id
    AND id != p_bid_id
    AND status != 'rejected';

  UPDATE public.jobs
  SET
    status = 'assigned',
    contractor_id = p_contractor_id,
    assigned_at = COALESCE(assigned_at, NOW()),
    updated_at = NOW()
  WHERE id = p_job_id;

  RETURN QUERY SELECT TRUE, NULL::TEXT, v_accepted_bid_id, 'assigned'::VARCHAR;
END;
$$;


ALTER FUNCTION "public"."accept_bid_atomic"("p_bid_id" "uuid", "p_job_id" "uuid", "p_contractor_id" "uuid", "p_homeowner_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."accept_bid_atomic"("p_bid_id" "uuid", "p_job_id" "uuid", "p_contractor_id" "uuid", "p_homeowner_id" "uuid") IS 'Atomically accepts a bid with row-level locking to prevent race conditions. Accepts the target bid, rejects all other bids for the job, and updates job status to assigned. Returns success status and error message if operation fails.';



CREATE OR REPLACE FUNCTION "public"."activate_model"("p_model_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_model_type TEXT;
BEGIN
  -- Get the model type
  SELECT model_type INTO v_model_type
  FROM internal_model_registry
  WHERE id = p_model_id;

  IF v_model_type IS NULL THEN
    RAISE EXCEPTION 'Model not found: %', p_model_id;
  END IF;

  -- Deactivate all models of this type
  UPDATE internal_model_registry
  SET is_active = FALSE
  WHERE model_type = v_model_type;

  -- Activate the specified model
  UPDATE internal_model_registry
  SET is_active = TRUE, deployed_at = NOW()
  WHERE id = p_model_id;

  RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."activate_model"("p_model_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."activate_model"("p_model_id" "uuid") IS 'Activate a specific model (deactivates other models of the same type)';



CREATE OR REPLACE FUNCTION "public"."activate_yolo_model"("p_model_name" "text", "p_version" "text", "p_storage_path" "text", "p_storage_url" "text", "p_file_size" bigint, "p_checksum" "text", "p_metrics" "jsonb" DEFAULT NULL::"jsonb", "p_training_samples" integer DEFAULT NULL::integer) RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_model_id UUID;
BEGIN
  UPDATE yolo_models
  SET
    is_active = FALSE,
    status = 'deprecated',
    deprecated_at = NOW()
  WHERE
    model_name = p_model_name
    AND is_active = TRUE;

  INSERT INTO yolo_models (
    model_name,
    model_version,
    storage_path,
    storage_url,
    storage_bucket,
    file_size,
    checksum,
    performance_metrics,
    training_samples_count,
    is_active,
    status,
    model_type,
    deployed_at,
    storage_migration_status,
    storage_migrated_at,
    model_data
  ) VALUES (
    p_model_name,
    p_version,
    p_storage_path,
    p_storage_url,
    'yolo-models',
    p_file_size,
    p_checksum,
    p_metrics,
    p_training_samples,
    TRUE,
    'deployed',
    'onnx',
    NOW(),
    'completed',
    NOW(),
    NULL
  )
  RETURNING id INTO v_model_id;

  RETURN v_model_id;
END;
$$;


ALTER FUNCTION "public"."activate_yolo_model"("p_model_name" "text", "p_version" "text", "p_storage_path" "text", "p_storage_url" "text", "p_file_size" bigint, "p_checksum" "text", "p_metrics" "jsonb", "p_training_samples" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."activate_yolo_model"("p_model_name" "text", "p_version" "text", "p_storage_path" "text", "p_storage_url" "text", "p_file_size" bigint, "p_checksum" "text", "p_metrics" "jsonb", "p_training_samples" integer) IS 'Atomically activates a YOLO model version and deactivates previous versions';



CREATE OR REPLACE FUNCTION "public"."add_password_to_history"("history_user_id" "uuid", "new_password_hash" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO public.password_history (user_id, password_hash)
  VALUES (history_user_id, new_password_hash);
  DELETE FROM public.password_history
  WHERE user_id = history_user_id
    AND id NOT IN (
      SELECT id FROM public.password_history
      WHERE user_id = history_user_id
      ORDER BY created_at DESC
      LIMIT 5
    );
END;
$$;


ALTER FUNCTION "public"."add_password_to_history"("history_user_id" "uuid", "new_password_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analyze_user_notification_engagement"("p_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_total_count INTEGER;
  v_best_hour INTEGER;
  v_best_days INTEGER[];
  v_worst_hour INTEGER;
  v_preferred_channel VARCHAR(30);
  v_primary_device VARCHAR(20);
  v_avg_open_rate DECIMAL(5,2);
  v_avg_click_rate DECIMAL(5,2);
  v_avg_dismiss_rate DECIMAL(5,2);
  v_avg_action_rate DECIMAL(5,2);
  v_avg_delay INTEGER;
  v_channel_rates JSONB;
  v_device_rates JSONB;
  v_type_prefs JSONB;
  v_confidence DECIMAL(5,2);
BEGIN
  SELECT COUNT(*)
  INTO v_total_count
  FROM notification_engagement
  WHERE user_id = p_user_id;

  IF v_total_count < 10 THEN
    RETURN;
  END IF;

  SELECT time_of_day_sent
  INTO v_best_hour
  FROM notification_engagement
  WHERE user_id = p_user_id AND time_of_day_sent IS NOT NULL AND opened = TRUE
  GROUP BY time_of_day_sent
  ORDER BY COUNT(*) DESC
  LIMIT 1;

  SELECT ARRAY_AGG(day_of_week_sent ORDER BY engagement_count DESC)
  INTO v_best_days
  FROM (
    SELECT day_of_week_sent, COUNT(*) as engagement_count
    FROM notification_engagement
    WHERE user_id = p_user_id AND day_of_week_sent IS NOT NULL AND opened = TRUE
    GROUP BY day_of_week_sent
    ORDER BY engagement_count DESC
    LIMIT 3
  ) best_days;

  SELECT channel
  INTO v_preferred_channel
  FROM notification_engagement
  WHERE user_id = p_user_id AND channel IS NOT NULL AND opened = TRUE
  GROUP BY channel
  ORDER BY COUNT(*) DESC
  LIMIT 1;

  SELECT device_type
  INTO v_primary_device
  FROM notification_engagement
  WHERE user_id = p_user_id AND device_type IS NOT NULL
  GROUP BY device_type
  ORDER BY COUNT(*) DESC
  LIMIT 1;

  SELECT
    (SUM(CASE WHEN opened THEN 1 ELSE 0 END)::FLOAT / COUNT(*) * 100)::DECIMAL(5,2),
    (SUM(CASE WHEN clicked THEN 1 ELSE 0 END)::FLOAT / COUNT(*) * 100)::DECIMAL(5,2),
    (SUM(CASE WHEN dismissed THEN 1 ELSE 0 END)::FLOAT / COUNT(*) * 100)::DECIMAL(5,2),
    (SUM(CASE WHEN action_completed THEN 1 ELSE 0 END)::FLOAT / COUNT(*) * 100)::DECIMAL(5,2),
    AVG(engagement_delay_seconds)::INTEGER
  INTO v_avg_open_rate, v_avg_click_rate, v_avg_dismiss_rate, v_avg_action_rate, v_avg_delay
  FROM notification_engagement
  WHERE user_id = p_user_id;

  SELECT jsonb_object_agg(
    channel,
    ROUND((opened_count::FLOAT / total_count * 100)::NUMERIC, 2)
  )
  INTO v_channel_rates
  FROM (
    SELECT
      channel,
      COUNT(*) as total_count,
      SUM(CASE WHEN opened THEN 1 ELSE 0 END) as opened_count
    FROM notification_engagement
    WHERE user_id = p_user_id AND channel IS NOT NULL
    GROUP BY channel
  ) channel_stats;

  SELECT jsonb_object_agg(
    device_type,
    ROUND((opened_count::FLOAT / total_count * 100)::NUMERIC, 2)
  )
  INTO v_device_rates
  FROM (
    SELECT
      device_type,
      COUNT(*) as total_count,
      SUM(CASE WHEN opened THEN 1 ELSE 0 END) as opened_count
    FROM notification_engagement
    WHERE user_id = p_user_id AND device_type IS NOT NULL
    GROUP BY device_type
  ) device_stats;

  SELECT jsonb_object_agg(
    notification_type,
    jsonb_build_object(
      'open_rate', ROUND((opened_count::FLOAT / total_count * 100)::NUMERIC, 2),
      'click_rate', ROUND((clicked_count::FLOAT / total_count * 100)::NUMERIC, 2),
      'total_sent', total_count
    )
  )
  INTO v_type_prefs
  FROM (
    SELECT
      notification_type,
      COUNT(*) as total_count,
      SUM(CASE WHEN opened THEN 1 ELSE 0 END) as opened_count,
      SUM(CASE WHEN clicked THEN 1 ELSE 0 END) as clicked_count
    FROM notification_engagement
    WHERE user_id = p_user_id
    GROUP BY notification_type
  ) type_stats;

  v_confidence := LEAST(100, (v_total_count::FLOAT / 100 * 100)::DECIMAL(5,2));

  INSERT INTO user_notification_engagement_profile (
    user_id,
    best_send_hour,
    best_send_days,
    worst_send_hour,
    preferred_channel,
    channel_engagement_rates,
    primary_device,
    device_engagement_rates,
    avg_open_rate,
    avg_click_rate,
    avg_dismiss_rate,
    avg_action_completion_rate,
    avg_engagement_delay_seconds,
    type_preferences,
    total_notifications_analyzed,
    profile_confidence,
    last_analyzed_at,
    updated_at
  ) VALUES (
    p_user_id,
    v_best_hour,
    v_best_days,
    v_worst_hour,
    v_preferred_channel,
    v_channel_rates,
    v_primary_device,
    v_device_rates,
    v_avg_open_rate,
    v_avg_click_rate,
    v_avg_dismiss_rate,
    v_avg_action_rate,
    v_avg_delay,
    v_type_prefs,
    v_total_count,
    v_confidence,
    NOW(),
    NOW()
  )
  ON CONFLICT (user_id)
  DO UPDATE SET
    best_send_hour = EXCLUDED.best_send_hour,
    best_send_days = EXCLUDED.best_send_days,
    worst_send_hour = EXCLUDED.worst_send_hour,
    preferred_channel = EXCLUDED.preferred_channel,
    channel_engagement_rates = EXCLUDED.channel_engagement_rates,
    primary_device = EXCLUDED.primary_device,
    device_engagement_rates = EXCLUDED.device_engagement_rates,
    avg_open_rate = EXCLUDED.avg_open_rate,
    avg_click_rate = EXCLUDED.avg_click_rate,
    avg_dismiss_rate = EXCLUDED.avg_dismiss_rate,
    avg_action_completion_rate = EXCLUDED.avg_action_completion_rate,
    avg_engagement_delay_seconds = EXCLUDED.avg_engagement_delay_seconds,
    type_preferences = EXCLUDED.type_preferences,
    total_notifications_analyzed = EXCLUDED.total_notifications_analyzed,
    profile_confidence = EXCLUDED.profile_confidence,
    last_analyzed_at = NOW(),
    updated_at = NOW();
END;
$$;


ALTER FUNCTION "public"."analyze_user_notification_engagement"("p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."analyze_user_notification_engagement"("p_user_id" "uuid") IS 'Analyzes user notification engagement history and updates their engagement profile';



CREATE OR REPLACE FUNCTION "public"."anonymize_user_data"("p_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  -- Log the anonymization request
  PERFORM public.log_gdpr_activity(p_user_id, 'data_anonymization', 'users', p_user_id);
  
  -- Anonymize user profile
  UPDATE public.profiles
  SET 
    email = 'anonymized_' || id || '@deleted.local',
    first_name = 'Anonymized',
    last_name = 'User',
    phone = NULL,
    profile_image_url = NULL,
    bio = NULL,
    updated_at = NOW()
  WHERE id = p_user_id;
  
  -- Anonymize job descriptions (keep structure but remove personal info)
  UPDATE public.jobs
  SET 
    description = '[Content anonymized for privacy]',
    updated_at = NOW()
  WHERE homeowner_id = p_user_id;
  
  -- Anonymize bid descriptions
  UPDATE public.bids
  SET 
    description = '[Content anonymized for privacy]',
    updated_at = NOW()
  WHERE contractor_id = p_user_id;
  
  -- Anonymize messages
  UPDATE public.messages
  SET 
    content = '[Message content anonymized for privacy]',
    updated_at = NOW()
  WHERE sender_id = p_user_id OR receiver_id = p_user_id;
END;
$$;


ALTER FUNCTION "public"."anonymize_user_data"("p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."anonymize_user_data"("p_user_id" "uuid") IS 'Anonymizes user data while preserving structure';



CREATE OR REPLACE FUNCTION "public"."archive_old_messages"() RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  deleted_count integer;
BEGIN
  -- Archive messages older than 1 year to messages_archive table
  CREATE TABLE IF NOT EXISTS messages_archive (LIKE messages INCLUDING ALL);
  
  WITH moved_messages AS (
    DELETE FROM messages 
    WHERE created_at < CURRENT_DATE - INTERVAL '1 year'
    AND read = true
    RETURNING *
  )
  INSERT INTO messages_archive 
  SELECT * FROM moved_messages;
  
  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN deleted_count;
END;
$$;


ALTER FUNCTION "public"."archive_old_messages"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."archive_old_messages"() IS 'Archives read messages older than 1 year';



CREATE OR REPLACE FUNCTION "public"."audit_job_changes"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    -- Only log if there are actual changes
    IF TG_OP = 'UPDATE' AND OLD IS NOT DISTINCT FROM NEW THEN
        RETURN NEW;
    END IF;

    INSERT INTO public.job_audit_log (
        job_id,
        action,
        old_data,
        new_data,
        changed_by
    ) VALUES (
        COALESCE(NEW.id, OLD.id),
        TG_OP,
        CASE WHEN TG_OP != 'INSERT' THEN to_jsonb(OLD) ELSE NULL END,
        CASE WHEN TG_OP != 'DELETE' THEN to_jsonb(NEW) ELSE NULL END,
        auth.uid()
    );

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    ELSE
        RETURN NEW;
    END IF;
END;
$$;


ALTER FUNCTION "public"."audit_job_changes"() OWNER TO "postgres";


