CREATE OR REPLACE FUNCTION "public"."audit_trigger_function"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    INSERT INTO public.audit_log (
      table_name,
      operation,
      old_values,
      user_id,
      ip_address,
      user_agent
    ) VALUES (
      TG_TABLE_NAME,
      TG_OP,
      row_to_json(OLD),
      auth.uid(),
      inet_client_addr(),
      current_setting('request.headers', true)::json->>'user-agent'
    );
    RETURN OLD;
  ELSIF TG_OP = 'UPDATE' THEN
    INSERT INTO public.audit_log (
      table_name,
      operation,
      old_values,
      new_values,
      user_id,
      ip_address,
      user_agent
    ) VALUES (
      TG_TABLE_NAME,
      TG_OP,
      row_to_json(OLD),
      row_to_json(NEW),
      auth.uid(),
      inet_client_addr(),
      current_setting('request.headers', true)::json->>'user-agent'
    );
    RETURN NEW;
  ELSIF TG_OP = 'INSERT' THEN
    INSERT INTO public.audit_log (
      table_name,
      operation,
      new_values,
      user_id,
      ip_address,
      user_agent
    ) VALUES (
      TG_TABLE_NAME,
      TG_OP,
      row_to_json(NEW),
      auth.uid(),
      inet_client_addr(),
      current_setting('request.headers', true)::json->>'user-agent'
    );
    RETURN NEW;
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."audit_trigger_function"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auto_log_job_status_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    PERFORM log_job_status_transition(
      NEW.id,
      OLD.status,
      NEW.status,
      auth.uid(),
      NULL,
      'Automatic logging from jobs table update'
    );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."auto_log_job_status_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auto_populate_contractor_client"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  -- Only trigger when contractor_id is set (job assigned)
  IF NEW.contractor_id IS NOT NULL AND (OLD.contractor_id IS NULL OR OLD.contractor_id != NEW.contractor_id) THEN
    INSERT INTO public.contractor_clients (id, contractor_id, first_name, last_name, email, client_type, relationship_status, source, total_jobs, created_at, updated_at)
    SELECT
      gen_random_uuid(),
      NEW.contractor_id,
      p.first_name,
      p.last_name,
      p.email,
      'residential',  -- was 'homeowner' which violated the CHECK constraint
      'active',
      'job_platform',
      1,
      NOW(),
      NOW()
    FROM public.profiles p WHERE p.id = NEW.homeowner_id
    ON CONFLICT DO NOTHING;

    -- Update existing client's job count
    UPDATE public.contractor_clients
    SET total_jobs = total_jobs + 1,
        last_job_date = NOW(),
        relationship_status = 'active',
        updated_at = NOW()
    WHERE contractor_id = NEW.contractor_id
      AND email = (SELECT email FROM public.profiles WHERE id = NEW.homeowner_id);
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."auto_populate_contractor_client"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."backfill_assessment_job_ids"() RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  updated_count INTEGER := 0;
BEGIN
  UPDATE building_assessments ba
  SET job_id = j.id
  FROM (
    SELECT DISTINCT ON (ba2.id)
      ba2.id as assessment_id,
      j.id as job_id
    FROM building_assessments ba2
    INNER JOIN jobs j ON j.homeowner_id = ba2.user_id
    WHERE ba2.job_id IS NULL
      AND ABS(EXTRACT(EPOCH FROM (ba2.created_at - j.created_at))) < 300
    ORDER BY ba2.id, ABS(EXTRACT(EPOCH FROM (ba2.created_at - j.created_at)))
  ) j
  WHERE ba.id = j.assessment_id
    AND ba.job_id IS NULL;

  GET DIAGNOSTICS updated_count = ROW_COUNT;
  RETURN updated_count;
END;
$$;


ALTER FUNCTION "public"."backfill_assessment_job_ids"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."backfill_assessment_job_ids"() IS 'Attempts to link orphaned assessments to jobs based on timing and user';



