    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  IF NEW.property_id IS NOT NULL AND NEW.latitude IS NOT NULL THEN
    UPDATE public.properties
    SET latitude = NEW.latitude, longitude = NEW.longitude
    WHERE id = NEW.property_id AND latitude IS NULL;
  END IF;
  RETURN NEW;
END;
$$;


