CREATE OR REPLACE FUNCTION "public"."build_calibration_set"("p_set_name" character varying, "p_set_type" character varying DEFAULT 'full'::character varying, "p_stratum" character varying DEFAULT NULL::character varying, "p_min_samples" integer DEFAULT 500, "p_validation_split" numeric DEFAULT 0.2) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_calibration_set_id UUID;
  v_version INTEGER;
  v_sample_count INTEGER;
  v_record RECORD;
BEGIN
  -- Get next version number
  SELECT COALESCE(MAX(version), 0) + 1 INTO v_version
  FROM conformal_calibration_sets
  WHERE set_name = p_set_name;

  -- Count available samples
  SELECT COUNT(*) INTO v_sample_count
  FROM mv_validated_assessments
  WHERE (p_stratum IS NULL OR
         CONCAT(property_age_category::TEXT, '_', damage_type) = p_stratum);

  -- Check minimum samples
  IF v_sample_count < p_min_samples THEN
    RAISE EXCEPTION 'Insufficient samples: % < %', v_sample_count, p_min_samples;
  END IF;

  -- Create calibration set record
  INSERT INTO conformal_calibration_sets (
    version, set_name, set_type, stratum, sample_count,
    metadata
  ) VALUES (
    v_version, p_set_name, p_set_type, p_stratum,
    FLOOR(v_sample_count * (1 - p_validation_split)),
    jsonb_build_object(
      'total_available', v_sample_count,
      'validation_split', p_validation_split,
      'created_by', auth.uid()
    )
  ) RETURNING id INTO v_calibration_set_id;

  -- Insert calibration samples (using random split)
  FOR v_record IN
    SELECT
      assessment_id,
      jsonb_build_object(
        'damage_type', damage_type,
        'property_type', property_type,
        'confidence', predicted_confidence
      ) as features,
      property_age_category,
      damage_type as damage_category,
      predicted_severity,
      predicted_confidence,
      jsonb_build_object(
        'early',
        CASE WHEN predicted_severity = 'early' THEN predicted_confidence
             ELSE (1 - predicted_confidence) / 2 END,
        'midway',
        CASE WHEN predicted_severity = 'midway' THEN predicted_confidence
             ELSE (1 - predicted_confidence) / 2 END,
        'full',
        CASE WHEN predicted_severity = 'full' THEN predicted_confidence
             ELSE (1 - predicted_confidence) / 2 END
      ) as prediction_scores,
      true_severity,
      true_damage_type,
      validation_source
    FROM mv_validated_assessments
    WHERE (p_stratum IS NULL OR
           CONCAT(property_age_category::TEXT, '_', damage_type) = p_stratum)
    ORDER BY RANDOM()
    LIMIT FLOOR(v_sample_count * (1 - p_validation_split))
  LOOP
    INSERT INTO conformal_calibration_samples (
      calibration_set_id,
      assessment_id,
      features,
      property_age_category,
      damage_category,
      predicted_severity,
      predicted_confidence,
      prediction_scores,
      true_severity,
      true_damage_type,
      ground_truth_source,
      nonconformity_score
    ) VALUES (
      v_calibration_set_id,
      v_record.assessment_id,
      v_record.features,
      v_record.property_age_category,
      v_record.damage_category,
      v_record.predicted_severity,
      v_record.predicted_confidence,
      v_record.prediction_scores,
      v_record.true_severity,
      v_record.true_damage_type,
      v_record.validation_source,
      calculate_nonconformity_score(
        v_record.prediction_scores,
        v_record.true_severity,
        'hinge'
      )
    );
  END LOOP;

  -- Calculate statistics
  UPDATE conformal_calibration_sets
  SET
    min_confidence = (
      SELECT MIN(predicted_confidence)
      FROM conformal_calibration_samples
      WHERE calibration_set_id = v_calibration_set_id
    ),
    max_confidence = (
      SELECT MAX(predicted_confidence)
      FROM conformal_calibration_samples
      WHERE calibration_set_id = v_calibration_set_id
    ),
    mean_confidence = (
      SELECT AVG(predicted_confidence)
      FROM conformal_calibration_samples
      WHERE calibration_set_id = v_calibration_set_id
    ),
    std_confidence = (
      SELECT STDDEV(predicted_confidence)
      FROM conformal_calibration_samples
      WHERE calibration_set_id = v_calibration_set_id
    )
  WHERE id = v_calibration_set_id;

  -- Compute thresholds for standard confidence levels
  PERFORM compute_conformal_thresholds(v_calibration_set_id, 0.80);
  PERFORM compute_conformal_thresholds(v_calibration_set_id, 0.90);
  PERFORM compute_conformal_thresholds(v_calibration_set_id, 0.95);
  PERFORM compute_conformal_thresholds(v_calibration_set_id, 0.99);

  RETURN v_calibration_set_id;
END;
$$;


ALTER FUNCTION "public"."build_calibration_set"("p_set_name" character varying, "p_set_type" character varying, "p_stratum" character varying, "p_min_samples" integer, "p_validation_split" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."build_calibration_set"("p_set_name" character varying, "p_set_type" character varying, "p_stratum" character varying, "p_min_samples" integer, "p_validation_split" numeric) IS 'Builds a new calibration set from validated assessments';



CREATE OR REPLACE FUNCTION "public"."calculate_ab_test_significance"("control_mean" numeric, "control_std" numeric, "control_n" integer, "treatment_mean" numeric, "treatment_std" numeric, "treatment_n" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  z_score NUMERIC;
  p_value NUMERIC;
  effect_size NUMERIC;
  pooled_std NUMERIC;
  standard_error NUMERIC;
  confidence_interval JSONB;
BEGIN
  IF control_n < 2 OR treatment_n < 2 THEN
    RETURN jsonb_build_object(
      'z_score', 0,
      'p_value', 1,
      'effect_size', 0,
      'confidence_interval', jsonb_build_array(0, 0),
      'is_significant', false
    );
  END IF;

  standard_error := SQRT(
    (control_std * control_std / control_n) +
    (treatment_std * treatment_std / treatment_n)
  );

  IF standard_error > 0 THEN
    z_score := (treatment_mean - control_mean) / standard_error;
  ELSE
    z_score := 0;
  END IF;

  IF ABS(z_score) > 3.29 THEN
    p_value := 0.001;
  ELSIF ABS(z_score) > 2.58 THEN
    p_value := 0.01;
  ELSIF ABS(z_score) > 1.96 THEN
    p_value := 0.05;
  ELSIF ABS(z_score) > 1.64 THEN
    p_value := 0.10;
  ELSE
    p_value := 2 * (1 - 0.5 * (1 + ABS(z_score) / SQRT(2 * 3.14159)));
  END IF;

  pooled_std := SQRT(
    ((control_n - 1) * control_std * control_std +
     (treatment_n - 1) * treatment_std * treatment_std) /
    (control_n + treatment_n - 2)
  );

  IF pooled_std > 0 THEN
    effect_size := (treatment_mean - control_mean) / pooled_std;
  ELSE
    effect_size := 0;
  END IF;

  confidence_interval := jsonb_build_array(
    (treatment_mean - control_mean) - 1.96 * standard_error,
    (treatment_mean - control_mean) + 1.96 * standard_error
  );

  RETURN jsonb_build_object(
    'z_score', z_score,
    'p_value', p_value,
    'effect_size', effect_size,
    'confidence_interval', confidence_interval,
    'is_significant', p_value < 0.05
  );
END;
$$;


ALTER FUNCTION "public"."calculate_ab_test_significance"("control_mean" numeric, "control_std" numeric, "control_n" integer, "treatment_mean" numeric, "treatment_std" numeric, "treatment_n" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."calculate_ab_test_significance"("control_mean" numeric, "control_std" numeric, "control_n" integer, "treatment_mean" numeric, "treatment_std" numeric, "treatment_n" integer) IS 'Calculates statistical significance for A/B test results';



