CREATE OR REPLACE FUNCTION "public"."calculate_bid_quality_score"("p_bid_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_score INTEGER := 0;
  v_bid RECORD;
  v_materials_count INTEGER;
  v_labor_count INTEGER;
  v_other_count INTEGER;
BEGIN
  -- Get bid details
  SELECT * INTO v_bid FROM bids WHERE id = p_bid_id;

  IF NOT FOUND THEN
    RETURN 0;
  END IF;

  -- Base score: Has any itemization (20 points)
  IF v_bid.has_itemization THEN
    v_score := v_score + 20;
  END IF;

  -- Materials breakdown provided (25 points)
  IF v_bid.materials_breakdown IS NOT NULL THEN
    v_materials_count := jsonb_array_length(v_bid.materials_breakdown);
    IF v_materials_count > 0 THEN
      v_score := v_score + 25;
    END IF;
  END IF;

  -- Labor breakdown provided (25 points)
  IF v_bid.labor_breakdown IS NOT NULL THEN
    v_labor_count := jsonb_array_length(v_bid.labor_breakdown);
    IF v_labor_count > 0 THEN
      v_score := v_score + 25;
    END IF;
  END IF;

  -- Other costs breakdown (10 points)
  IF v_bid.other_costs_breakdown IS NOT NULL THEN
    v_other_count := jsonb_array_length(v_bid.other_costs_breakdown);
    IF v_other_count > 0 THEN
      v_score := v_score + 10;
    END IF;
  END IF;

  -- Detailed line items (5 points per item, max 20)
  IF v_materials_count >= 3 THEN
    v_score := v_score + LEAST(v_materials_count * 5, 20);
  END IF;

  -- Ensure score is between 0-100
  RETURN LEAST(v_score, 100);
END;
$$;


ALTER FUNCTION "public"."calculate_bid_quality_score"("p_bid_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_bid_to_budget_ratio"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_budget DECIMAL;
BEGIN
  -- Get job budget
  SELECT budget INTO v_budget FROM jobs WHERE id = NEW.job_id;

  IF v_budget IS NOT NULL AND v_budget > 0 AND NEW.amount IS NOT NULL THEN
    NEW.bid_to_budget_ratio := ROUND(NEW.amount / v_budget, 4);
  ELSE
    NEW.bid_to_budget_ratio := NULL;
  END IF;

  -- Check if within typical range
  IF NEW.amount IS NOT NULL THEN
    NEW.within_typical_range := check_bid_within_typical_range(NEW.job_id, NEW.amount);
  ELSE
    NEW.within_typical_range := NULL;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."calculate_bid_to_budget_ratio"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_conformal_effectiveness"("p_start_date" timestamp without time zone DEFAULT ("now"() - '7 days'::interval), "p_end_date" timestamp without time zone DEFAULT "now"()) RETURNS TABLE("metric_name" "text", "metric_value" numeric)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
    RETURN QUERY
    WITH stats AS (
        SELECT
            COUNT(*) FILTER (WHERE conformal_calibration_used = TRUE) as with_conformal,
            COUNT(*) FILTER (WHERE conformal_calibration_used = FALSE) as without_conformal,
            AVG(conformal_interval_size) FILTER (WHERE conformal_calibration_used = TRUE) as avg_interval,
            COUNT(DISTINCT conformal_stratum) FILTER (WHERE conformal_calibration_used = TRUE) as unique_strata,
            AVG(inference_time_ms) FILTER (WHERE conformal_calibration_used = TRUE) as avg_time_with,
            AVG(inference_time_ms) FILTER (WHERE conformal_calibration_used = FALSE) as avg_time_without
        FROM hybrid_routing_decisions
        WHERE created_at BETWEEN p_start_date AND p_end_date
    )
    SELECT 'total_with_conformal'::TEXT, with_conformal::NUMERIC FROM stats
    UNION ALL
    SELECT 'total_without_conformal'::TEXT, without_conformal::NUMERIC FROM stats
    UNION ALL
    SELECT 'calibration_coverage_pct'::TEXT,
           CASE
               WHEN (with_conformal + without_conformal) > 0
               THEN (with_conformal::NUMERIC / (with_conformal + without_conformal) * 100)
               ELSE 0
           END FROM stats
    UNION ALL
    SELECT 'avg_interval_size'::TEXT, COALESCE(avg_interval, 0)::NUMERIC FROM stats
    UNION ALL
    SELECT 'unique_strata_used'::TEXT, COALESCE(unique_strata, 0)::NUMERIC FROM stats
    UNION ALL
    SELECT 'avg_inference_time_with_conformal_ms'::TEXT, COALESCE(avg_time_with, 0)::NUMERIC FROM stats
    UNION ALL
    SELECT 'avg_inference_time_without_conformal_ms'::TEXT, COALESCE(avg_time_without, 0)::NUMERIC FROM stats;
END;
$$;


ALTER FUNCTION "public"."calculate_conformal_effectiveness"("p_start_date" timestamp without time zone, "p_end_date" timestamp without time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_contractor_payout"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  IF NEW.platform_fee IS NOT NULL THEN
    NEW.contractor_payout = NEW.amount - NEW.platform_fee;
  ELSE
    NEW.platform_fee = NEW.amount * 0.05;
    NEW.contractor_payout = NEW.amount - NEW.platform_fee;
  END IF;
  RETURN NEW;
END;
$$;


