CREATE OR REPLACE FUNCTION "public"."calculate_contractor_profile_boost"("p_contractor_id" "uuid") RETURNS TABLE("contractor_id" "uuid", "ranking_score" integer, "tier" character varying, "boosts" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_dbs_boost INTEGER := 0;
  v_personality_boost INTEGER := 0;
  v_admin_boost INTEGER := 0;
  v_phone_boost INTEGER := 0;
  v_email_boost INTEGER := 0;
  v_portfolio_boost INTEGER := 0;
  v_certs_boost INTEGER := 0;
  v_insurance_boost INTEGER := 0;
  v_base_trust DECIMAL(3,2) := 0.50;
BEGIN
  SELECT
    CASE
      WHEN dbs_type = 'enhanced' AND status = 'clear' THEN 25
      WHEN dbs_type = 'standard' AND status = 'clear' THEN 15
      WHEN dbs_type = 'basic' AND status = 'clear' THEN 10
      ELSE 0
    END
  INTO v_dbs_boost
  FROM contractor_dbs_checks
  WHERE contractor_dbs_checks.contractor_id = p_contractor_id
    AND status = 'clear'
    AND (expiry_date IS NULL OR expiry_date > CURRENT_DATE)
  ORDER BY created_at DESC
  LIMIT 1;

  SELECT
    CASE
      WHEN overall_score >= 70 THEN 15
      WHEN overall_score >= 50 THEN 10
      WHEN overall_score >= 30 THEN 5
      ELSE 0
    END
  INTO v_personality_boost
  FROM contractor_personality_assessments
  WHERE contractor_personality_assessments.contractor_id = p_contractor_id
    AND completed_at IS NOT NULL;

  SELECT CASE WHEN admin_verified = true THEN 15 ELSE 0 END INTO v_admin_boost FROM users WHERE id = p_contractor_id;
  SELECT CASE WHEN phone_verified_at IS NOT NULL THEN 5 ELSE 0 END INTO v_phone_boost FROM users WHERE id = p_contractor_id;
  SELECT CASE WHEN email_verified = true THEN 5 ELSE 0 END INTO v_email_boost FROM users WHERE id = p_contractor_id;

  SELECT
    CASE WHEN COUNT(*) >= 5 THEN 10
         WHEN COUNT(*) >= 3 THEN 7
         WHEN COUNT(*) >= 1 THEN 3
         ELSE 0
    END
  INTO v_portfolio_boost
  FROM contractor_posts
  WHERE contractor_posts.contractor_id = p_contractor_id AND is_public = true;

  SELECT
    CASE WHEN COUNT(*) >= 3 THEN 10
         WHEN COUNT(*) >= 1 THEN 5
         ELSE 0
    END
  INTO v_certs_boost
  FROM contractor_skills
  WHERE contractor_skills.contractor_id = p_contractor_id AND is_verified = true;

  SELECT COALESCE(trust_score, 0.50) INTO v_base_trust
  FROM contractor_trust_scores
  WHERE contractor_trust_scores.contractor_id = p_contractor_id;

  INSERT INTO contractor_profile_boosts (
    contractor_id, base_trust_score, dbs_check_boost, admin_verified_boost, phone_verified_boost,
    email_verified_boost, personality_assessment_boost, portfolio_completeness_boost,
    certifications_boost, insurance_verified_boost, last_calculated_at, calculation_details
  ) VALUES (
    p_contractor_id, v_base_trust, v_dbs_boost, v_admin_boost, v_phone_boost, v_email_boost,
    v_personality_boost, v_portfolio_boost, v_certs_boost, v_insurance_boost, NOW(),
    jsonb_build_object(
      'dbs_boost', v_dbs_boost, 'personality_boost', v_personality_boost, 'admin_boost', v_admin_boost,
      'phone_boost', v_phone_boost, 'email_boost', v_email_boost, 'portfolio_boost', v_portfolio_boost,
      'certs_boost', v_certs_boost, 'insurance_boost', v_insurance_boost, 'base_trust_score', v_base_trust
    )
  )
  ON CONFLICT (contractor_id)
  DO UPDATE SET
    base_trust_score = EXCLUDED.base_trust_score,
    dbs_check_boost = EXCLUDED.dbs_check_boost,
    admin_verified_boost = EXCLUDED.admin_verified_boost,
    phone_verified_boost = EXCLUDED.phone_verified_boost,
    email_verified_boost = EXCLUDED.email_verified_boost,
    personality_assessment_boost = EXCLUDED.personality_assessment_boost,
    portfolio_completeness_boost = EXCLUDED.portfolio_completeness_boost,
    certifications_boost = EXCLUDED.certifications_boost,
    insurance_verified_boost = EXCLUDED.insurance_verified_boost,
    last_calculated_at = NOW(),
    calculation_details = EXCLUDED.calculation_details;

  RETURN QUERY
  SELECT cpb.contractor_id, cpb.ranking_score, cpb.tier, cpb.calculation_details as boosts
  FROM contractor_profile_boosts cpb
  WHERE cpb.contractor_id = p_contractor_id;
END;
$$;


ALTER FUNCTION "public"."calculate_contractor_profile_boost"("p_contractor_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."calculate_contractor_profile_boost"("p_contractor_id" "uuid") IS 'Calculates and updates profile boost score for a contractor based on all verification factors';



CREATE OR REPLACE FUNCTION "public"."calculate_distance"("lat1" numeric, "lon1" numeric, "lat2" numeric, "lon2" numeric) RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
    RETURN 6371 * acos(
        cos(radians(lat1)) * cos(radians(lat2)) *
        cos(radians(lon2) - radians(lon1)) +
        sin(radians(lat1)) * sin(radians(lat2))
    );
END;
$$;


ALTER FUNCTION "public"."calculate_distance"("lat1" numeric, "lon1" numeric, "lat2" numeric, "lon2" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_distance_km"("lat1" numeric, "lng1" numeric, "lat2" numeric, "lng2" numeric) RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT (
    ST_Distance(
      ST_SetSRID(ST_MakePoint(lng1, lat1),4326)::geography,
      ST_SetSRID(ST_MakePoint(lng2, lat2),4326)::geography
    ) / 1000.0
  )::DECIMAL;
$$;


ALTER FUNCTION "public"."calculate_distance_km"("lat1" numeric, "lng1" numeric, "lat2" numeric, "lng2" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_frequency_compliance"("p_memory_state_id" "uuid", "p_lookback_days" integer DEFAULT 7) RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_expected_updates INTEGER;
  v_actual_updates INTEGER;
  v_compliance DECIMAL(5, 2);
BEGIN
  SELECT 
    COUNT(*) FILTER (WHERE step % chunk_size = 0),
    COUNT(*)
  INTO v_expected_updates, v_actual_updates
  FROM memory_update_history muh
  JOIN continuum_memory_states cms ON muh.memory_state_id = cms.id
  WHERE muh.memory_state_id = p_memory_state_id
    AND muh.created_at >= NOW() - (p_lookback_days || ' days')::INTERVAL;
  
  IF v_expected_updates = 0 THEN
    RETURN 100.0;
  END IF;
  
  v_compliance := (v_actual_updates::DECIMAL / v_expected_updates::DECIMAL) * 100.0;
  RETURN LEAST(100.0, GREATEST(0.0, v_compliance));
END;
$$;


ALTER FUNCTION "public"."calculate_frequency_compliance"("p_memory_state_id" "uuid", "p_lookback_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_job_duration"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  IF NEW.status IN ('completed', 'failed', 'cancelled') AND NEW.completed_at IS NOT NULL AND NEW.started_at IS NOT NULL THEN
    NEW.duration_seconds = EXTRACT(EPOCH FROM (NEW.completed_at - NEW.started_at))::INTEGER;
  END IF;
  RETURN NEW;
END;
$$;


