CREATE OR REPLACE FUNCTION "public"."calculate_maintenance_metrics"() RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  INSERT INTO maintenance_performance_metrics (
    date,
    total_assessments,
    successful_detections,
    no_detection_cases,
    average_confidence,
    average_latency_ms,
    contractor_satisfaction_rate,
    helpful_rate,
    local_inference_count,
    gpt4_fallback_count
  )
  SELECT
    CURRENT_DATE,
    COUNT(*),
    COUNT(CASE WHEN issue_type != 'unknown' THEN 1 END),
    COUNT(CASE WHEN issue_type = 'unknown' THEN 1 END),
    AVG(confidence),
    AVG((assessment_data->>'processing_time_ms')::float),
    AVG(CASE WHEN contractor_found_helpful = true THEN 1.0 ELSE 0.0 END),
    AVG(CASE WHEN contractor_found_helpful = true THEN 1.0 ELSE 0.0 END),
    COUNT(CASE WHEN model_type = 'maintenance_yolo' THEN 1 END),
    COUNT(CASE WHEN model_type = 'gpt4_fallback' THEN 1 END)
  FROM maintenance_assessments
  WHERE DATE(created_at) = CURRENT_DATE
  ON CONFLICT (date) DO UPDATE SET
    total_assessments = EXCLUDED.total_assessments,
    successful_detections = EXCLUDED.successful_detections,
    no_detection_cases = EXCLUDED.no_detection_cases,
    average_confidence = EXCLUDED.average_confidence,
    average_latency_ms = EXCLUDED.average_latency_ms,
    contractor_satisfaction_rate = EXCLUDED.contractor_satisfaction_rate,
    helpful_rate = EXCLUDED.helpful_rate,
    local_inference_count = EXCLUDED.local_inference_count,
    gpt4_fallback_count = EXCLUDED.gpt4_fallback_count,
    created_at = NOW();
END;
$$;


ALTER FUNCTION "public"."calculate_maintenance_metrics"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_memory_efficiency"("p_memory_state_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_compliance DECIMAL(5, 2);
  v_compression DECIMAL(10, 4);
  v_latency INTEGER;
  v_efficiency DECIMAL(5, 2);
BEGIN
  SELECT 
    update_frequency_compliance,
    compression_ratio,
    query_latency_ms
  INTO v_compliance, v_compression, v_latency
  FROM memory_performance_metrics
  WHERE memory_state_id = p_memory_state_id
  ORDER BY calculated_at DESC
  LIMIT 1;
  
  IF v_compliance IS NULL THEN
    RETURN 50.0;
  END IF;
  
  v_efficiency := 
    (v_compliance * 0.4) +
    (LEAST(v_compression, 10.0) / 10.0 * 100 * 0.3) +
    (GREATEST(0, 100 - v_latency / 10) * 0.3);
  
  RETURN LEAST(100.0, GREATEST(0.0, v_efficiency));
END;
$$;


ALTER FUNCTION "public"."calculate_memory_efficiency"("p_memory_state_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_mrr"() RETURNS TABLE("total_mrr" numeric, "active_subscriptions" integer, "mrr_by_plan" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_total_mrr DECIMAL(10, 2) := 0;
  v_active_count INTEGER := 0;
  v_mrr_by_plan JSONB := '{}'::jsonb;
BEGIN
  SELECT 
    COALESCE(SUM(amount), 0),
    COUNT(*)
  INTO 
    v_total_mrr,
    v_active_count
  FROM public.contractor_subscriptions
  WHERE status IN ('active', 'trial')
    AND (current_period_end IS NULL OR current_period_end > NOW());

  SELECT jsonb_object_agg(
    plan_type,
    jsonb_build_object(
      'mrr', plan_mrr,
      'count', plan_count
    )
  )
  INTO v_mrr_by_plan
  FROM (
    SELECT 
      plan_type,
      COALESCE(SUM(amount), 0)::DECIMAL(10, 2) as plan_mrr,
      COUNT(*)::INTEGER as plan_count
    FROM public.contractor_subscriptions
    WHERE status IN ('active', 'trial')
      AND (current_period_end IS NULL OR current_period_end > NOW())
    GROUP BY plan_type
  ) plan_stats;

  RETURN QUERY SELECT 
    v_total_mrr,
    v_active_count,
    COALESCE(v_mrr_by_plan, '{}'::jsonb);
END;
$$;


ALTER FUNCTION "public"."calculate_mrr"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."calculate_mrr"() IS 'Calculates Monthly Recurring Revenue from all active subscriptions';



CREATE OR REPLACE FUNCTION "public"."calculate_nonconformity_score"("predicted_scores" "jsonb", "true_class" character varying, "score_type" character varying DEFAULT 'hinge'::character varying) RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  true_score NUMERIC;
  max_other_score NUMERIC;
  nonconformity NUMERIC;
BEGIN
  -- Extract score for true class
  true_score := COALESCE((predicted_scores->>true_class)::NUMERIC, 0);

  IF score_type = 'hinge' THEN
    -- Hinge loss: 1 - (true_score - max_other_score)
    SELECT MAX((value)::NUMERIC) INTO max_other_score
    FROM jsonb_each_text(predicted_scores)
    WHERE key != true_class;

    nonconformity := 1.0 - (true_score - COALESCE(max_other_score, 0));

  ELSIF score_type = 'margin' THEN
    -- Margin: max_other_score - true_score
    SELECT MAX((value)::NUMERIC) INTO max_other_score
    FROM jsonb_each_text(predicted_scores)
    WHERE key != true_class;

    nonconformity := COALESCE(max_other_score, 0) - true_score;

  ELSIF score_type = 'inverse_probability' THEN
    -- 1 - P(true_class)
    nonconformity := 1.0 - true_score;

  ELSE
    RAISE EXCEPTION 'Unknown score type: %', score_type;
  END IF;

  RETURN GREATEST(0, nonconformity); -- Ensure non-negative
END;
$$;


ALTER FUNCTION "public"."calculate_nonconformity_score"("predicted_scores" "jsonb", "true_class" character varying, "score_type" character varying) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."calculate_nonconformity_score"("predicted_scores" "jsonb", "true_class" character varying, "score_type" character varying) IS 'Calculates nonconformity score for conformal prediction';



