CREATE OR REPLACE FUNCTION "public"."check_appointment_conflict"("contractor_uuid" "uuid", "appt_date" "date", "appt_start_time" time without time zone, "appt_end_time" time without time zone, "exclude_appointment_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    conflict_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO conflict_count
    FROM appointments
    WHERE contractor_id = contractor_uuid
        AND appointment_date = appt_date
        AND status NOT IN ('cancelled', 'no_show')
        AND (id IS DISTINCT FROM exclude_appointment_id)
        AND (
            (start_time, end_time) OVERLAPS (appt_start_time, appt_end_time)
        );

    RETURN conflict_count > 0;
END;
$$;


