CREATE OR REPLACE FUNCTION "public"."check_bid_within_typical_range"("p_job_id" "uuid", "p_bid_amount" numeric) RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_job RECORD;
  v_avg_bid DECIMAL;
  v_min_typical DECIMAL;
  v_max_typical DECIMAL;
BEGIN
  -- Get job details
  SELECT category, location INTO v_job FROM jobs WHERE id = p_job_id;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  -- Calculate average accepted bid for similar jobs (same category, last 6 months)
  SELECT AVG(b.amount) INTO v_avg_bid
  FROM bids b
  JOIN jobs j ON b.job_id = j.id
  WHERE j.category = v_job.category
    AND b.status = 'accepted'
    AND b.created_at > NOW() - INTERVAL '6 months';

  -- If no historical data, assume bid is valid
  IF v_avg_bid IS NULL THEN
    RETURN true;
  END IF;

  -- Typical range: 70% to 130% of average
  v_min_typical := v_avg_bid * 0.70;
  v_max_typical := v_avg_bid * 1.30;

  -- Check if bid falls within range
  RETURN p_bid_amount BETWEEN v_min_typical AND v_max_typical;
END;
$$;


ALTER FUNCTION "public"."check_bid_within_typical_range"("p_job_id" "uuid", "p_bid_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_database_health"() RETURNS TABLE("check_name" "text", "status" "text", "details" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    v_count INTEGER;
    v_tables JSONB;
BEGIN
    check_name := 'Tables without primary keys';
    WITH tables_without_pk AS (
        SELECT t.table_name
        FROM information_schema.tables t
        LEFT JOIN information_schema.table_constraints tc
            ON t.table_name = tc.table_name
            AND t.table_schema = tc.table_schema
            AND tc.constraint_type = 'PRIMARY KEY'
        WHERE t.table_schema = 'public'
            AND t.table_type = 'BASE TABLE'
            AND tc.constraint_name IS NULL
    )
    SELECT COUNT(*), jsonb_agg(table_name) INTO v_count, v_tables
    FROM tables_without_pk;
    status := CASE WHEN COALESCE(v_count, 0) = 0 THEN 'OK' ELSE 'WARNING' END;
    details := jsonb_build_object('count', COALESCE(v_count, 0), 'tables', COALESCE(v_tables, '[]'::jsonb));
    RETURN NEXT;

    check_name := 'Unused indexes';
    SELECT COUNT(*), jsonb_agg(indexrelname) INTO v_count, v_tables
    FROM pg_stat_user_indexes
    WHERE schemaname = 'public'
        AND idx_scan = 0
        AND indexrelname NOT LIKE '%_pkey';
    status := CASE 
        WHEN COALESCE(v_count, 0) = 0 THEN 'OK'
        WHEN COALESCE(v_count, 0) < 5 THEN 'INFO'
        ELSE 'WARNING'
    END;
    details := jsonb_build_object('count', COALESCE(v_count, 0), 'indexes', COALESCE(v_tables, '[]'::jsonb));
    RETURN NEXT;

    check_name := 'Cache hit ratio';
    SELECT INTO details
        jsonb_build_object(
            'ratio', round((sum(heap_blks_hit)::numeric / NULLIF(sum(heap_blks_hit) + sum(heap_blks_read), 0) * 100), 2)
        )
    FROM pg_statio_user_tables;
    SELECT INTO status
        CASE
            WHEN (details->>'ratio')::numeric > 99 THEN 'OK'
            WHEN (details->>'ratio')::numeric > 95 THEN 'INFO'
            ELSE 'WARNING'
        END;
    RETURN NEXT;

    check_name := 'Long-running queries';
    WITH long_queries AS (
        SELECT 
            pid,
            EXTRACT(EPOCH FROM (NOW() - query_start)) as duration,
            LEFT(query, 100) as query_preview
        FROM pg_stat_activity
        WHERE state = 'active'
            AND query_start < NOW() - INTERVAL '5 minutes'
            AND query NOT LIKE '%pg_stat_activity%'
    )
    SELECT COUNT(*), jsonb_agg(
        jsonb_build_object(
            'pid', pid,
            'duration', duration,
            'query', query_preview
        )
    ) INTO v_count, v_tables
    FROM long_queries;
    status := CASE WHEN COALESCE(v_count, 0) = 0 THEN 'OK' ELSE 'WARNING' END;
    details := jsonb_build_object('count', COALESCE(v_count, 0), 'queries', COALESCE(v_tables, '[]'::jsonb));
    RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."check_database_health"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_database_health"() IS 'Comprehensive database health check - returns status of various database metrics';



CREATE OR REPLACE FUNCTION "public"."check_mfa_rate_limit"("p_user_id" "uuid", "p_window_minutes" integer DEFAULT 15, "p_max_attempts" integer DEFAULT 5) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    v_recent_failed_attempts INTEGER;
BEGIN
    SELECT COUNT(*)
    INTO v_recent_failed_attempts
    FROM mfa_verification_attempts
    WHERE user_id = p_user_id
        AND success = FALSE
        AND attempted_at > NOW() - (p_window_minutes || ' minutes')::INTERVAL;
    RETURN v_recent_failed_attempts < p_max_attempts;
END;
$$;


