CREATE OR REPLACE FUNCTION "public"."check_password_strength"("password" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  IF LENGTH(password) < 8 THEN
    RETURN 'Password must be at least 8 characters long';
  END IF;
  
  IF NOT (password ~* '[A-Z]') THEN
    RETURN 'Password must contain at least one uppercase letter';
  END IF;
  
  IF NOT (password ~* '[a-z]') THEN
    RETURN 'Password must contain at least one lowercase letter';
  END IF;
  
  IF NOT (password ~* '[0-9]') THEN
    RETURN 'Password must contain at least one number';
  END IF;
  
  IF NOT (password ~* '[^A-Za-z0-9]') THEN
    RETURN 'Password must contain at least one special character';
  END IF;
  
  RETURN 'Password is strong';
END;
$$;


ALTER FUNCTION "public"."check_password_strength"("password" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_password_strength"("password" "text") IS 'Checks password strength requirements';



CREATE OR REPLACE FUNCTION "public"."check_production_performance"() RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    avg_response_time NUMERIC;
    error_rate NUMERIC;
    concurrent_users INTEGER;
BEGIN
    -- Monitor job creation rate
    SELECT COUNT(*) INTO concurrent_users
    FROM jobs 
    WHERE created_at >= NOW() - INTERVAL '5 minutes';
    
    IF concurrent_users > 100 THEN
        INSERT INTO production_metrics (metric_type, metric_value, threshold_critical, is_alert)
        VALUES ('job_creation_rate', concurrent_users, 100, true);
    END IF;
    
    -- Monitor failed transactions
    SELECT 
        (COUNT(CASE WHEN status = 'failed' THEN 1 END)::NUMERIC / NULLIF(COUNT(*), 0)) * 100
    INTO error_rate
    FROM escrow_transactions 
    WHERE created_at >= NOW() - INTERVAL '5 minutes';
    
    IF error_rate > 5 THEN
        INSERT INTO production_metrics (metric_type, metric_value, threshold_warning, is_alert)
        VALUES ('transaction_error_rate', error_rate, 5, true);
    END IF;
END;
$$;


ALTER FUNCTION "public"."check_production_performance"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_rate_limit"("p_user_integration_id" "uuid", "p_endpoint" character varying DEFAULT '*'::character varying) RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    rate_limit_record RECORD;
    current_time TIMESTAMP WITH TIME ZONE := NOW();
BEGIN
    SELECT * INTO rate_limit_record
    FROM api_rate_limits
    WHERE user_integration_id = p_user_integration_id
    AND endpoint = p_endpoint;
    
    IF rate_limit_record.id IS NULL THEN
        -- No rate limit configured, allow request
        RETURN true;
    END IF;
    
    -- Check if reset time has passed
    IF current_time >= rate_limit_record.reset_at THEN
        -- Reset counters
        UPDATE api_rate_limits
        SET current_usage = 0,
            burst_usage = 0,
            is_exceeded = false,
            exceeded_at = NULL,
            reset_at = current_time + (rate_limit_record.period_duration || ' seconds')::INTERVAL,
            updated_at = current_time
        WHERE id = rate_limit_record.id;
        
        rate_limit_record.current_usage := 0;
        rate_limit_record.is_exceeded := false;
    END IF;
    
    -- Check if within limits
    IF rate_limit_record.current_usage >= rate_limit_record.requests_limit THEN
        -- Update exceeded status
        UPDATE api_rate_limits
        SET is_exceeded = true,
            exceeded_at = COALESCE(exceeded_at, current_time)
        WHERE id = rate_limit_record.id;
        
        RETURN false;
    END IF;
    
    -- Increment usage
    UPDATE api_rate_limits
    SET current_usage = current_usage + 1,
        updated_at = current_time
    WHERE id = rate_limit_record.id;
    
    RETURN true;
END;
$$;


ALTER FUNCTION "public"."check_rate_limit"("p_user_integration_id" "uuid", "p_endpoint" character varying) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_rate_limit"("p_user_id" "uuid", "p_ip_address" "inet", "p_endpoint" "text", "p_limit" integer DEFAULT 100, "p_window_minutes" integer DEFAULT 60) RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  current_count INTEGER;
BEGIN
  -- Clean up old entries
  DELETE FROM public.rate_limits 
  WHERE window_start < NOW() - INTERVAL '1 hour';
  
  -- Get current count
  SELECT COALESCE(SUM(request_count), 0) INTO current_count
  FROM public.rate_limits
  WHERE 
    (p_user_id IS NOT NULL AND user_id = p_user_id OR user_id IS NULL)
    AND ip_address = p_ip_address
    AND endpoint = p_endpoint
    AND window_start >= NOW() - INTERVAL '1 hour';
  
  -- Check if limit exceeded
  IF current_count >= p_limit THEN
    RETURN FALSE;
  END IF;
  
  -- Increment counter
  INSERT INTO public.rate_limits (user_id, ip_address, endpoint, request_count)
  VALUES (p_user_id, p_ip_address, p_endpoint, 1)
  ON CONFLICT (user_id, ip_address, endpoint, window_start)
  DO UPDATE SET request_count = rate_limits.request_count + 1;
  
  RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."check_rate_limit"("p_user_id" "uuid", "p_ip_address" "inet", "p_endpoint" "text", "p_limit" integer, "p_window_minutes" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_rate_limit"("p_user_id" "uuid", "p_ip_address" "inet", "p_endpoint" "text", "p_limit" integer, "p_window_minutes" integer) IS 'Checks and enforces rate limits';



