CREATE OR REPLACE FUNCTION "public"."check_token_family_breach"("p_token_hash" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_family_id uuid;
  v_token_revoked_at timestamptz;
  v_has_revoked_siblings boolean;
BEGIN
  SELECT family_id, revoked_at
  INTO v_family_id, v_token_revoked_at
  FROM public.refresh_tokens
  WHERE token_hash = p_token_hash;

  IF v_family_id IS NULL THEN
    RETURN false;
  END IF;

  IF v_token_revoked_at IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.refresh_tokens
      WHERE family_id = v_family_id
        AND revoked_at IS NOT NULL
        AND revoked_reason = 'rotated'
        AND token_hash != p_token_hash
    ) INTO v_has_revoked_siblings;

    IF v_has_revoked_siblings THEN
      UPDATE public.refresh_tokens
      SET
        revoked_at = NOW(),
        revoked_reason = 'breach_detected',
        updated_at = NOW()
      WHERE family_id = v_family_id
        AND revoked_at IS NULL;

      RETURN true;
    END IF;
  END IF;

  RETURN false;
END;
$$;


ALTER FUNCTION "public"."check_token_family_breach"("p_token_hash" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."check_token_family_breach"("p_token_hash" "text") IS 'Detects token family breaches by checking if an old token from the same family was reused';



CREATE OR REPLACE FUNCTION "public"."check_trial_status"("p_contractor_id" "uuid") RETURNS TABLE("days_remaining" integer, "is_trial_active" boolean, "trial_started_at" timestamp with time zone, "trial_ends_at" timestamp with time zone, "requires_subscription" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_trial_ends_at TIMESTAMP WITH TIME ZONE;
  v_trial_started_at TIMESTAMP WITH TIME ZONE;
  v_subscription_status TEXT;
  v_days_remaining INTEGER;
BEGIN
  SELECT 
    u.trial_ends_at,
    u.trial_started_at,
    u.subscription_status
  INTO 
    v_trial_ends_at,
    v_trial_started_at,
    v_subscription_status
  FROM public.profiles u
  WHERE u.id = p_contractor_id
    AND u.role = 'contractor';

  IF v_trial_ends_at IS NULL THEN
    RETURN QUERY SELECT 
      NULL::INTEGER,
      FALSE::BOOLEAN,
      NULL::TIMESTAMP WITH TIME ZONE,
      NULL::TIMESTAMP WITH TIME ZONE,
      TRUE::BOOLEAN;
    RETURN;
  END IF;

  IF v_trial_ends_at > NOW() THEN
    v_days_remaining := EXTRACT(EPOCH FROM (v_trial_ends_at - NOW())) / 86400;
    v_days_remaining := GREATEST(0, v_days_remaining::INTEGER);
  ELSE
    v_days_remaining := 0;
  END IF;

  RETURN QUERY SELECT 
    v_days_remaining,
    (v_trial_ends_at > NOW() AND v_subscription_status = 'trial')::BOOLEAN,
    v_trial_started_at,
    v_trial_ends_at,
    (v_trial_ends_at <= NOW() OR v_subscription_status != 'trial')::BOOLEAN;
END;
$$;


