CREATE OR REPLACE FUNCTION "public"."cleanup_orphaned_records"() RETURNS TABLE("table_name" "text", "records_deleted" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    deleted_count INTEGER;
BEGIN
    DELETE FROM job_attachments ja
    WHERE NOT EXISTS (
        SELECT 1 FROM jobs j WHERE j.id = ja.job_id
    );
    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    table_name := 'job_attachments';
    records_deleted := deleted_count;
    RETURN NEXT;

    DELETE FROM messages m
    WHERE m.job_id IS NOT NULL
    AND NOT EXISTS (
        SELECT 1 FROM jobs j WHERE j.id = m.job_id
    );
    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    table_name := 'messages';
    records_deleted := deleted_count;
    RETURN NEXT;

    DELETE FROM notifications n
    WHERE NOT EXISTS (
        SELECT 1 FROM users u WHERE u.id = n.user_id
    );
    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    table_name := 'notifications';
    records_deleted := deleted_count;
    RETURN NEXT;

    DELETE FROM bids b
    WHERE NOT EXISTS (
        SELECT 1 FROM jobs j WHERE j.id = b.job_id
    );
    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    table_name := 'bids';
    records_deleted := deleted_count;
    RETURN NEXT;
END;
$$;


