CREATE OR REPLACE FUNCTION "public"."complete_idempotency_claim"("p_idempotency_key" "text", "p_operation" "text", "p_result" "jsonb", "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_metadata" "jsonb" DEFAULT NULL::"jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_updated INT;
BEGIN
  UPDATE public.idempotency_keys
     SET status     = 'completed',
         result     = p_result,
         user_id    = COALESCE(p_user_id, user_id),
         metadata   = COALESCE(p_metadata, metadata)
   WHERE idempotency_key = p_idempotency_key
     AND operation       = p_operation
     AND status          = 'pending';
  GET DIAGNOSTICS v_updated = ROW_COUNT;
  RETURN v_updated > 0;
END;
$$;


