    INSERT INTO public.meeting_updates (
      meeting_id,
      update_type,
      message,
      updated_by,
      old_value,
      new_value
    ) VALUES (
      NEW.id,
      'status_change',
      format('Meeting status changed from %s to %s', OLD.status, NEW.status),
      auth.uid(),
      jsonb_build_object('status', OLD.status),
      jsonb_build_object('status', NEW.status)
    );
  END IF;
  RETURN NEW;
END;
$$;


