CREATE OR REPLACE FUNCTION "public"."create_sync_job"("p_user_integration_id" "uuid", "p_job_type" character varying, "p_sync_direction" "public"."sync_direction", "p_entity_type" character varying, "p_filters" "jsonb" DEFAULT '{}'::"jsonb", "p_batch_size" integer DEFAULT 100, "p_triggered_by" "uuid" DEFAULT NULL::"uuid", "p_trigger_reason" character varying DEFAULT NULL::character varying) RETURNS "uuid"
