CREATE OR REPLACE FUNCTION "public"."delete_user_data"("p_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_role TEXT;
  rec RECORD;
  v_owner_tables TEXT[] := ARRAY[
    'contracts',
    'contractor_payout_transfers',
    'job_tips',
    'leases',
    'maintenance_tickets',
    'organizations',
    'ticket_updates',
    'property_team_members',
    'property_tenants'
  ];
BEGIN
  SELECT role INTO v_role FROM public.profiles WHERE id = p_user_id;

  BEGIN
    PERFORM public.log_gdpr_activity(p_user_id, 'data_deletion', 'profiles', p_user_id);
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  DELETE FROM public.messages
    WHERE sender_id = p_user_id OR receiver_id = p_user_id;
  DELETE FROM public.refresh_tokens WHERE user_id = p_user_id;
  DELETE FROM public.dsr_requests WHERE user_id = p_user_id;

  IF v_role = 'contractor' THEN
    DELETE FROM public.bids WHERE contractor_id = p_user_id;
    UPDATE public.jobs
       SET contractor_id = NULL,
           status = CASE
             WHEN status IN ('assigned', 'in_progress') THEN 'posted'
             ELSE status
           END,
           assigned_at = CASE
             WHEN status IN ('assigned', 'in_progress') THEN NULL
             ELSE assigned_at
           END,
           started_at = CASE
             WHEN status IN ('assigned', 'in_progress') THEN NULL
             ELSE started_at
           END,
           updated_at = NOW()
     WHERE contractor_id = p_user_id;
    DELETE FROM public.contractor_payout_transfers WHERE contractor_id = p_user_id;
    DELETE FROM public.contracts WHERE contractor_id = p_user_id;
  ELSE
    DELETE FROM public.contracts
      WHERE job_id IN (SELECT id FROM public.jobs WHERE homeowner_id = p_user_id);
    DELETE FROM public.refunds
      WHERE job_id IN (SELECT id FROM public.jobs WHERE homeowner_id = p_user_id);
    DELETE FROM public.bids
      WHERE job_id IN (SELECT id FROM public.jobs WHERE homeowner_id = p_user_id);
    DELETE FROM public.jobs WHERE homeowner_id = p_user_id;
    DELETE FROM public.properties WHERE owner_id = p_user_id;

    DELETE FROM public.contracts WHERE homeowner_id = p_user_id;
    DELETE FROM public.leases WHERE tenant_user_id = p_user_id;
    DELETE FROM public.maintenance_tickets WHERE reported_by = p_user_id;
    DELETE FROM public.ticket_updates WHERE author_id = p_user_id;
    DELETE FROM public.organizations WHERE created_by = p_user_id;
    DELETE FROM public.property_team_members WHERE user_id = p_user_id;
    DELETE FROM public.property_tenants WHERE user_id = p_user_id;
    DELETE FROM public.job_tips WHERE payer_id = p_user_id OR payee_id = p_user_id;
  END IF;

  FOR rec IN
    SELECT
      n.nspname || '.' || c.relname AS qualified_table,
      c.relname AS table_name,
      a.attname AS column_name
    FROM pg_constraint con
    JOIN pg_class c     ON c.oid = con.conrelid
    JOIN pg_namespace n ON n.oid = c.relnamespace
    JOIN pg_class refc  ON refc.oid = con.confrelid
    JOIN pg_namespace refn ON refn.oid = refc.relnamespace
    JOIN pg_attribute a ON a.attrelid = con.conrelid AND a.attnum = con.conkey[1]
    WHERE con.contype = 'f'
      AND refn.nspname = 'public'
      AND refc.relname = 'profiles'
      AND n.nspname = 'public'
      AND con.confdeltype IN ('a', 'r')
      AND a.attnotnull = false
      AND NOT (c.relname = ANY (v_owner_tables))
  LOOP
    EXECUTE format(
      'UPDATE %s SET %I = NULL WHERE %I = $1',
      rec.qualified_table, rec.column_name, rec.column_name
    ) USING p_user_id;
  END LOOP;

  DELETE FROM public.profiles WHERE id = p_user_id;
END;
$_$;


ALTER FUNCTION "public"."delete_user_data"("p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."delete_user_data"("p_user_id" "uuid") IS 'GDPR right-to-erasure. Role-aware. v7 (audit-76 self-review): contractor branch resets jobs.assigned_at + jobs.started_at ONLY when the job is being recycled from assigned/in_progress back to ''posted''. Completed jobs keep their historical timestamps — they''re job-facts, not personal data; the personal-data pointer (contractor_id) is nulled regardless. auth.users removal is the caller''s responsibility.';



CREATE OR REPLACE FUNCTION "public"."deliver_webhook"("p_user_integration_id" "uuid", "p_event_type" "public"."webhook_event_type", "p_event_id" "uuid", "p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    webhook_id UUID;
    integration_record RECORD;
BEGIN
    -- Get webhook configuration
    SELECT webhook_url, webhook_secret_encrypted, webhook_events
    INTO integration_record
    FROM user_integrations
    WHERE id = p_user_integration_id
    AND status = 'active'
    AND webhook_url IS NOT NULL
    AND p_event_type = ANY(webhook_events);
    
    IF integration_record.webhook_url IS NULL THEN
        RETURN NULL; -- No webhook configured for this event
    END IF;
    
    -- Create webhook delivery record
    INSERT INTO webhook_deliveries (
        user_integration_id,
        event_type,
        event_id,
        webhook_url,
        payload
    ) VALUES (
        p_user_integration_id,
        p_event_type,
        p_event_id,
        integration_record.webhook_url,
        p_payload
    ) RETURNING id INTO webhook_id;
    
    RETURN webhook_id;
END;
$$;


ALTER FUNCTION "public"."deliver_webhook"("p_user_integration_id" "uuid", "p_event_type" "public"."webhook_event_type", "p_event_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."detect_payment_anomaly"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  recent_count INTEGER;
  avg_amount DECIMAL;
  deviation_multiplier DECIMAL;
BEGIN
  SELECT COUNT(*) INTO recent_count
  FROM escrow_transactions
  WHERE user_id = NEW.user_id
    AND created_at > NOW() - INTERVAL '1 hour';

  IF recent_count > 5 THEN
    INSERT INTO payment_security_events (
      user_id, event_type, risk_score, transaction_type, amount, reasons, metadata
    ) VALUES (
      NEW.user_id, 'velocity_limit_exceeded', 70, 'payment', NEW.amount,
      ARRAY['More than 5 transactions in 1 hour'],
      jsonb_build_object('transaction_count', recent_count)
    );
  END IF;

  SELECT AVG(amount) INTO avg_amount
  FROM escrow_transactions
  WHERE user_id = NEW.user_id
    AND status = 'completed'
    AND created_at > NOW() - INTERVAL '30 days'
  LIMIT 20;

  IF avg_amount IS NOT NULL AND avg_amount > 0 THEN
    deviation_multiplier := NEW.amount / avg_amount;
    IF deviation_multiplier >= 5 THEN
      INSERT INTO payment_security_events (
        user_id, event_type, risk_score, transaction_type, amount, reasons, metadata
      ) VALUES (
        NEW.user_id, 'anomaly_detected', 80, 'payment', NEW.amount,
        ARRAY[format('Amount is %.1fx higher than average', deviation_multiplier)],
        jsonb_build_object('average_amount', avg_amount, 'deviation_multiplier', deviation_multiplier)
      );
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."detect_payment_anomaly"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."detect_suspicious_activity"("p_user_id" "uuid", "p_ip_address" "inet", "p_endpoint" "text") RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  recent_events INTEGER;
  different_ips INTEGER;
BEGIN
  -- Check for multiple failed login attempts
  SELECT COUNT(*) INTO recent_events
  FROM public.security_events
  WHERE 
    user_id = p_user_id
    AND event_type = 'auth_failure'
    AND created_at >= NOW() - INTERVAL '15 minutes';
  
  IF recent_events >= 5 THEN
    PERFORM log_security_event(
      'suspicious_activity',
      'high',
      p_user_id,
      p_ip_address,
      p_endpoint,
      'POST',
      'Multiple failed login attempts detected'
    );
    RETURN TRUE;
  END IF;
  
  -- Check for requests from multiple IPs
  SELECT COUNT(DISTINCT ip_address) INTO different_ips
  FROM public.security_events
  WHERE 
    user_id = p_user_id
    AND created_at >= NOW() - INTERVAL '1 hour';
  
  IF different_ips >= 3 THEN
    PERFORM log_security_event(
      'suspicious_activity',
      'medium',
      p_user_id,
      p_ip_address,
      p_endpoint,
      'GET',
      'Requests from multiple IP addresses detected'
    );
    RETURN TRUE;
  END IF;
  
  RETURN FALSE;
END;
$$;


ALTER FUNCTION "public"."detect_suspicious_activity"("p_user_id" "uuid", "p_ip_address" "inet", "p_endpoint" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."detect_suspicious_activity"("p_user_id" "uuid", "p_ip_address" "inet", "p_endpoint" "text") IS 'Detects suspicious user activity';



