CREATE OR REPLACE FUNCTION "public"."find_nearby_assessments"("p_lat" double precision, "p_lng" double precision, "p_radius_meters" integer DEFAULT 1000, "p_limit" integer DEFAULT 20) RETURNS TABLE("id" "uuid", "damage_type_canonical" "text", "severity" "text", "confidence" integer, "distance_meters" double precision, "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT
    ba.id,
    ba.damage_type_canonical,
    ba.severity,
    ba.confidence,
    ST_Distance(
      ba.location,
      ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::GEOGRAPHY
    ) AS distance_meters,
    ba.created_at
  FROM building_assessments ba
  WHERE ba.location IS NOT NULL
    AND ST_DWithin(
      ba.location,
      ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::GEOGRAPHY,
      p_radius_meters
    )
  ORDER BY distance_meters ASC
  LIMIT p_limit;
$$;


