CREATE OR REPLACE FUNCTION "public"."find_similar_contractors"("contractor_id" "uuid", "match_limit" integer DEFAULT 10, "similarity_threshold" double precision DEFAULT 0.7) RETURNS TABLE("id" "uuid", "first_name" "text", "last_name" "text", "bio" "text", "rating" numeric, "similarity" double precision)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  source_embedding vector(1536);
BEGIN
  SELECT embedding INTO source_embedding
  FROM users
  WHERE users.id = contractor_id AND users.role = 'contractor';

  IF source_embedding IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    u.id,
    u.first_name,
    u.last_name,
    u.bio,
    u.rating,
    1 - (u.embedding <=> source_embedding) AS similarity
  FROM users u
  WHERE
    u.id != contractor_id
    AND u.role = 'contractor'
    AND u.embedding IS NOT NULL
    AND (1 - (u.embedding <=> source_embedding)) >= similarity_threshold
  ORDER BY u.embedding <=> source_embedding
  LIMIT match_limit;
END;
$$;


