CREATE OR REPLACE FUNCTION "public"."get_conformal_prediction_interval"("p_prediction_scores" "jsonb", "p_property_age_category" "public"."property_age_category", "p_damage_type" character varying, "p_confidence_level" numeric DEFAULT 0.95) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_threshold NUMERIC;
  v_calibration_set_id UUID;
  v_stratum VARCHAR;
  v_prediction_set JSONB;
  v_class VARCHAR;
  v_score NUMERIC;
  v_nonconformity NUMERIC;
BEGIN
  -- Build stratum identifier
  v_stratum := CONCAT(p_property_age_category::TEXT, '_', p_damage_type);

  -- Get active calibration set and threshold
  SELECT
    cs.id,
    ct.threshold_value
  INTO
    v_calibration_set_id,
    v_threshold
  FROM conformal_calibration_sets cs
  JOIN conformal_thresholds ct ON cs.id = ct.calibration_set_id
  WHERE cs.is_active = TRUE
    AND (cs.stratum = v_stratum OR cs.stratum IS NULL)
    AND ct.confidence_level = p_confidence_level
    AND (ct.stratum = v_stratum OR ct.stratum IS NULL)
  ORDER BY
    cs.stratum IS NOT NULL DESC, -- Prefer stratified
    cs.created_at DESC
  LIMIT 1;

  IF v_threshold IS NULL THEN
    -- Fall back to default threshold if no calibration available
    v_threshold := 0.5;
  END IF;

  -- Build prediction set (classes included in confidence region)
  v_prediction_set := '[]'::JSONB;

  FOR v_class, v_score IN
    SELECT key, (value)::NUMERIC
    FROM jsonb_each_text(p_prediction_scores)
    ORDER BY (value)::NUMERIC DESC
  LOOP
    -- Calculate nonconformity for this class
    v_nonconformity := calculate_nonconformity_score(
      p_prediction_scores,
      v_class,
      'hinge'
    );

    -- Include class if within threshold
    IF v_nonconformity <= v_threshold THEN
      v_prediction_set := v_prediction_set || jsonb_build_array(v_class);
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'confidence_level', p_confidence_level,
    'prediction_set', v_prediction_set,
    'threshold_used', v_threshold,
    'calibration_set_id', v_calibration_set_id,
    'stratum', v_stratum,
    'interval_size', jsonb_array_length(v_prediction_set)
  );
END;
$$;


ALTER FUNCTION "public"."get_conformal_prediction_interval"("p_prediction_scores" "jsonb", "p_property_age_category" "public"."property_age_category", "p_damage_type" character varying, "p_confidence_level" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_conformal_prediction_interval"("p_prediction_scores" "jsonb", "p_property_age_category" "public"."property_age_category", "p_damage_type" character varying, "p_confidence_level" numeric) IS 'Returns conformal prediction set with guaranteed coverage';



CREATE OR REPLACE FUNCTION "public"."get_contractor_recommendations"("p_job_id" "uuid", "p_limit" integer DEFAULT 10) RETURNS TABLE("contractor_id" "uuid", "contractor_name" "text", "rating" numeric, "total_jobs" integer, "distance_km" numeric, "hourly_rate" numeric, "availability_score" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  job_record RECORD;
BEGIN
  -- Get job details
  SELECT * INTO job_record FROM public.jobs WHERE id = p_job_id;

  RETURN QUERY
  SELECT
    u.id as contractor_id,
    CONCAT(u.first_name, ' ', u.last_name) as contractor_name,
    u.rating,
    u.total_jobs_completed as total_jobs,
    CASE
      WHEN job_record.latitude IS NOT NULL AND job_record.longitude IS NOT NULL THEN
        (ST_Distance(
          ST_Point(u.longitude, u.latitude)::geography,
          ST_Point(job_record.longitude, job_record.latitude)::geography
        ) / 1000)::numeric
      ELSE NULL::numeric
    END as distance_km,
    u.hourly_rate,
    CASE
      WHEN u.is_available THEN 100
      ELSE 0
    END as availability_score
  FROM public.profiles u
  WHERE
    u.role = 'contractor'
    AND u.is_available = TRUE
    AND u.rating >= 3.0
    AND (
      job_record.latitude IS NULL OR job_record.longitude IS NULL OR
      ST_DWithin(
        ST_Point(u.longitude, u.latitude)::geography,
        ST_Point(job_record.longitude, job_record.latitude)::geography,
        50 * 1000 -- 50km radius
      )
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.bids b
      WHERE b.job_id = p_job_id AND b.contractor_id = u.id
    )
  ORDER BY
    u.rating DESC,
    u.total_jobs_completed DESC,
    distance_km ASC
  LIMIT p_limit;
END;
$$;


