CREATE OR REPLACE FUNCTION "public"."get_contractor_stats"("contractor_uuid" "uuid") RETURNS TABLE("total_contributions" integer, "quality_score" double precision, "credits_earned" numeric, "level" character varying, "next_level_requirements" "text")
