CREATE OR REPLACE FUNCTION "public"."get_jobs_paginated"("p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0, "p_status" "text" DEFAULT NULL::"text", "p_category" "text" DEFAULT NULL::"text", "p_min_budget" numeric DEFAULT NULL::numeric, "p_max_budget" numeric DEFAULT NULL::numeric, "p_latitude" numeric DEFAULT NULL::numeric, "p_longitude" numeric DEFAULT NULL::numeric, "p_radius_km" integer DEFAULT 25) RETURNS TABLE("id" "uuid", "title" "text", "description" "text", "location" "text", "budget" numeric, "status" "text", "category" "text", "created_at" timestamp with time zone, "homeowner_name" "text", "distance_km" numeric)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    j.id,
    j.title,
    j.description,
    j.location,
    j.budget,
    j.status,
    j.category,
    j.created_at,
    CONCAT(u.first_name, ' ', u.last_name) as homeowner_name,
    CASE 
      WHEN p_latitude IS NOT NULL AND p_longitude IS NOT NULL THEN
        ST_Distance(
          ST_Point(j.longitude, j.latitude)::geography,
          ST_Point(p_longitude, p_latitude)::geography
        ) / 1000
      ELSE NULL
    END as distance_km
  FROM public.jobs j
  JOIN public.profiles u ON j.homeowner_id = u.id
  WHERE 
    (p_status IS NULL OR j.status = p_status)
    AND (p_category IS NULL OR j.category = p_category)
    AND (p_min_budget IS NULL OR j.budget >= p_min_budget)
    AND (p_max_budget IS NULL OR j.budget <= p_max_budget)
    AND (
      p_latitude IS NULL OR p_longitude IS NULL OR p_radius_km IS NULL OR
      ST_DWithin(
        ST_Point(j.longitude, j.latitude)::geography,
        ST_Point(p_longitude, p_latitude)::geography,
        p_radius_km * 1000
      )
    )
  ORDER BY j.created_at DESC
  LIMIT p_limit OFFSET p_offset;
END;
$$;


