CREATE OR REPLACE FUNCTION "public"."get_security_dashboard_metrics"("p_timeframe" "text" DEFAULT '24h'::"text") RETURNS TABLE("total_events" bigint, "critical_events" bigint, "high_severity_events" bigint, "unique_ips" bigint, "top_event_types" "jsonb", "recent_critical_events" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  timeframe_interval INTERVAL;
BEGIN
  -- Convert timeframe to interval
  CASE p_timeframe
    WHEN '1h' THEN timeframe_interval := '1 hour';
    WHEN '24h' THEN timeframe_interval := '24 hours';
    WHEN '7d' THEN timeframe_interval := '7 days';
    WHEN '30d' THEN timeframe_interval := '30 days';
    ELSE timeframe_interval := '24 hours';
  END CASE;

  RETURN QUERY
  WITH event_stats AS (
    SELECT 
      COUNT(*) as total,
      COUNT(*) FILTER (WHERE severity = 'critical') as critical,
      COUNT(*) FILTER (WHERE severity = 'high') as high,
      COUNT(DISTINCT ip_address) as unique_ips
    FROM public.security_events
    WHERE created_at >= NOW() - timeframe_interval
  ),
  event_types AS (
    SELECT jsonb_object_agg(event_type, count) as types
    FROM (
      SELECT event_type, COUNT(*) as count
      FROM public.security_events
      WHERE created_at >= NOW() - timeframe_interval
      GROUP BY event_type
      ORDER BY count DESC
      LIMIT 10
    ) t
  ),
  recent_critical AS (
    SELECT jsonb_agg(
      jsonb_build_object(
        'id', id,
        'event_type', event_type,
        'details', details,
        'ip_address', ip_address,
        'created_at', created_at
      )
    ) as events
    FROM (
      SELECT id, event_type, details, ip_address, created_at
      FROM public.security_events
      WHERE severity = 'critical' 
        AND created_at >= NOW() - timeframe_interval
      ORDER BY created_at DESC
      LIMIT 5
    ) t
  )
  SELECT 
    es.total,
    es.critical,
    es.high,
    es.unique_ips,
    COALESCE(et.types, '{}'::jsonb),
    COALESCE(rc.events, '[]'::jsonb)
  FROM event_stats es
  CROSS JOIN event_types et
  CROSS JOIN recent_critical rc;
END;
$$;


ALTER FUNCTION "public"."get_security_dashboard_metrics"("p_timeframe" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_security_dashboard_metrics"("p_timeframe" "text") IS 'Returns security dashboard metrics for specified timeframe';



CREATE OR REPLACE FUNCTION "public"."get_slow_queries"() RETURNS TABLE("query" "text", "calls" bigint, "total_time" double precision, "mean_time" double precision, "rows" bigint)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    pg_stat_statements.query,
    pg_stat_statements.calls,
    pg_stat_statements.total_time,
    pg_stat_statements.mean_time,
    pg_stat_statements.rows
  FROM pg_stat_statements
  WHERE pg_stat_statements.mean_time > 100 -- Queries taking more than 100ms
  ORDER BY pg_stat_statements.mean_time DESC
  LIMIT 20;
END;
$$;


