CREATE OR REPLACE FUNCTION "public"."get_subscription_features"("p_contractor_id" "uuid") RETURNS TABLE("plan_type" "text", "max_jobs" integer, "max_active_jobs" integer, "priority_support" boolean, "advanced_analytics" boolean, "custom_branding" boolean, "api_access" boolean, "additional_features" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_subscription_status TEXT;
  v_plan_type TEXT;
BEGIN
  SELECT 
    u.subscription_status,
    cs.plan_type
  INTO 
    v_subscription_status,
    v_plan_type
  FROM public.profiles u
  LEFT JOIN public.contractor_subscriptions cs 
    ON cs.contractor_id = u.id 
    AND cs.status IN ('active', 'trial')
  WHERE u.id = p_contractor_id
    AND u.role = 'contractor';

  IF v_subscription_status IS NULL 
     OR (v_subscription_status != 'trial' AND v_subscription_status != 'active')
     OR v_plan_type IS NULL THEN
    RETURN QUERY
    SELECT 
      sf.plan_type,
      sf.max_jobs,
      sf.max_active_jobs,
      sf.priority_support,
      sf.advanced_analytics,
      sf.custom_branding,
      sf.api_access,
      sf.additional_features
    FROM public.subscription_features sf
    WHERE sf.plan_type = 'basic'
    LIMIT 1;
    RETURN;
  END IF;

  RETURN QUERY
  SELECT 
    sf.plan_type,
    sf.max_jobs,
    sf.max_active_jobs,
    sf.priority_support,
    sf.advanced_analytics,
    sf.custom_branding,
    sf.api_access,
    sf.additional_features
  FROM public.subscription_features sf
  WHERE sf.plan_type = v_plan_type
  LIMIT 1;
END;
$$;


