CREATE OR REPLACE FUNCTION "public"."get_upcoming_appointments"("contractor_uuid" "uuid", "days_ahead" integer DEFAULT 7) RETURNS TABLE("appointment_id" "uuid", "title" character varying, "client_name" character varying, "appointment_date" "date", "start_time" time without time zone, "end_time" time without time zone, "location_type" character varying, "status" character varying, "job_title" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        a.id,
        a.title,
        COALESCE(u.first_name || ' ' || u.last_name, a.client_name),
        a.appointment_date,
        a.start_time,
        a.end_time,
        a.location_type,
        a.status,
        j.title
    FROM appointments a
    LEFT JOIN users u ON a.client_id = u.id
    LEFT JOIN jobs j ON a.job_id = j.id
    WHERE a.contractor_id = contractor_uuid
        AND a.appointment_date >= CURRENT_DATE
        AND a.appointment_date <= CURRENT_DATE + days_ahead
        AND a.status IN ('scheduled', 'confirmed')
    ORDER BY a.appointment_date, a.start_time;
END;
$$;


