CREATE OR REPLACE FUNCTION "public"."get_user_integration_secret"("p_id" "uuid", "p_kind" "text", "p_key" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v TEXT;
BEGIN
  IF p_kind = 'api_key' THEN
    SELECT pgp_sym_decrypt(api_key_encrypted::bytea, p_key) INTO v
    FROM public.user_integrations WHERE id = p_id AND user_id = auth.uid();
  ELSIF p_kind = 'access_token' THEN
    SELECT pgp_sym_decrypt(oauth_access_token_encrypted::bytea, p_key) INTO v
    FROM public.user_integrations WHERE id = p_id AND user_id = auth.uid();
  ELSIF p_kind = 'refresh_token' THEN
    SELECT pgp_sym_decrypt(oauth_refresh_token_encrypted::bytea, p_key) INTO v
    FROM public.user_integrations WHERE id = p_id AND user_id = auth.uid();
  ELSE
    RAISE EXCEPTION 'Unknown secret kind %', p_kind;
  END IF;
  RETURN v;
END $$;


ALTER FUNCTION "public"."get_user_integration_secret"("p_id" "uuid", "p_kind" "text", "p_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_video_assessment_stats"("p_user_id" "uuid") RETURNS TABLE("total_assessments" bigint, "completed_assessments" bigint, "failed_assessments" bigint, "total_damages_detected" bigint, "avg_processing_time" numeric, "most_common_damage_type" character varying)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  RETURN QUERY
  WITH stats AS (
    SELECT
      COUNT(*) AS total_assessments,
      COUNT(*) FILTER (WHERE processing_status = 'completed') AS completed_assessments,
      COUNT(*) FILTER (WHERE processing_status = 'failed') AS failed_assessments,
      SUM(total_unique_damages) AS total_damages_detected,
      AVG(processing_time_seconds) AS avg_processing_time
    FROM video_assessments
    WHERE user_id = p_user_id
  ),
  damage_counts AS (
    SELECT damage_type, COUNT(*) as count
    FROM video_damage_summary vds
    JOIN video_assessments va ON va.id = vds.video_assessment_id
    WHERE va.user_id = p_user_id
    GROUP BY damage_type
    ORDER BY count DESC
    LIMIT 1
  )
  SELECT
    s.total_assessments,
    s.completed_assessments,
    s.failed_assessments,
    COALESCE(s.total_damages_detected, 0) AS total_damages_detected,
    s.avg_processing_time,
    dc.damage_type AS most_common_damage_type
  FROM stats s
  LEFT JOIN damage_counts dc ON true;
END;
$$;


ALTER FUNCTION "public"."get_user_video_assessment_stats"("p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_user_video_assessment_stats"("p_user_id" "uuid") IS 'Get video assessment statistics for a user';



CREATE OR REPLACE FUNCTION "public"."get_yolo_savings_metrics"("start_date" timestamp without time zone DEFAULT (CURRENT_DATE - '7 days'::interval), "end_date" timestamp without time zone DEFAULT CURRENT_TIMESTAMP) RETURNS TABLE("total_assessments" bigint, "yolo_skipped" bigint, "skip_rate" numeric, "estimated_time_saved_ms" bigint, "estimated_compute_saved" bigint, "avg_presence_score" numeric, "most_common_damage_types" "text"[])
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        COUNT(*)::BIGINT as total_assessments,
        COUNT(*) FILTER (WHERE yolo_skipped = true)::BIGINT as yolo_skipped,
        ROUND(
            COUNT(*) FILTER (WHERE yolo_skipped = true)::numeric /
            NULLIF(COUNT(*), 0) * 100,
            2
        ) as skip_rate,
        (COUNT(*) FILTER (WHERE yolo_skipped = true) * 2000)::BIGINT as estimated_time_saved_ms,
        COUNT(*) FILTER (WHERE yolo_skipped = true)::BIGINT as estimated_compute_saved,
        ROUND(
            AVG((presence_detection->>'averagePresenceScore')::numeric)
            FILTER (WHERE presence_detection IS NOT NULL),
            3
        ) as avg_presence_score,
        ARRAY(
            SELECT unnest(string_to_array(damage_type, ','))
            FROM (
                SELECT presence_detection->>'damageTypes' as damage_type
                FROM hybrid_routing_decisions
                WHERE created_at BETWEEN start_date AND end_date
                AND presence_detection->>'damageDetected' = 'true'
                AND presence_detection->>'damageTypes' IS NOT NULL
            ) t
            GROUP BY unnest
            ORDER BY COUNT(*) DESC
            LIMIT 5
        ) as most_common_damage_types
    FROM hybrid_routing_decisions
    WHERE created_at BETWEEN start_date AND end_date;
END;
$$;


ALTER FUNCTION "public"."get_yolo_savings_metrics"("start_date" timestamp without time zone, "end_date" timestamp without time zone) OWNER TO "postgres";


