CREATE OR REPLACE FUNCTION "public"."has_assessment_been_learned_from"("p_assessment_id" "uuid", "p_outcome_type" character varying DEFAULT NULL::character varying) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_count INTEGER;
BEGIN
  IF p_outcome_type IS NULL THEN
    SELECT COUNT(*) INTO v_count
    FROM building_assessment_outcomes
    WHERE assessment_id = p_assessment_id
      AND learning_successful = TRUE;
  ELSE
    SELECT COUNT(*) INTO v_count
    FROM building_assessment_outcomes
    WHERE assessment_id = p_assessment_id
      AND outcome_type = p_outcome_type
      AND learning_successful = TRUE;
  END IF;
  
  RETURN v_count > 0;
END;
$$;


