CREATE OR REPLACE FUNCTION "public"."increment_feature_usage"("p_user_id" "uuid", "p_feature_id" "text", "p_increment" integer DEFAULT 1) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_limit TEXT;
  v_used INTEGER;
  v_reset_date TIMESTAMP WITH TIME ZONE;
  v_subscription_tier TEXT;
BEGIN
  SELECT COALESCE(cs.plan_type, 'trial')
  INTO v_subscription_tier
  FROM public.profiles u
  LEFT JOIN public.contractor_subscriptions cs
    ON cs.contractor_id = u.id
    AND cs.status IN ('trial', 'active')
  WHERE u.id = p_user_id
  LIMIT 1;

  v_reset_date := DATE_TRUNC('month', NOW() + INTERVAL '1 month');

  INSERT INTO public.feature_usage (
    user_id, feature_id, used_count, limit_count, reset_date
  )
  VALUES (p_user_id, p_feature_id, 0, '0', v_reset_date)
  ON CONFLICT (user_id, feature_id, reset_date) DO NOTHING;

  SELECT used_count, limit_count INTO v_used, v_limit
  FROM public.feature_usage
  WHERE user_id = p_user_id
    AND feature_id = p_feature_id
    AND reset_date >= NOW();

  IF v_limit = 'unlimited' THEN
    UPDATE public.feature_usage
    SET used_count = used_count + p_increment, updated_at = NOW()
    WHERE user_id = p_user_id AND feature_id = p_feature_id AND reset_date >= NOW();
    RETURN TRUE;
  END IF;

  IF v_used + p_increment <= v_limit::INTEGER THEN
    UPDATE public.feature_usage
    SET used_count = used_count + p_increment, updated_at = NOW()
    WHERE user_id = p_user_id AND feature_id = p_feature_id AND reset_date >= NOW();
    RETURN TRUE;
  END IF;

  RETURN FALSE;
END;
$$;


ALTER FUNCTION "public"."increment_feature_usage"("p_user_id" "uuid", "p_feature_id" "text", "p_increment" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."increment_feature_usage"("p_user_id" "uuid", "p_feature_id" "text", "p_increment" integer) IS 'Increments feature usage count and checks against limit';



