CREATE OR REPLACE FUNCTION "public"."log_ab_outcome"("p_decision_id" "uuid", "p_assessment_id" "uuid", "p_experiment_id" "uuid", "p_assignment_id" "uuid", "p_arm_id" "uuid", "p_reward" numeric, "p_sfn" boolean, "p_true_class" "text", "p_predicted_class" "text", "p_validated_by" "uuid", "p_validated_at" timestamp with time zone DEFAULT "now"()) RETURNS TABLE("id" "uuid", "decision_id" "uuid", "assessment_id" "uuid", "experiment_id" "uuid", "assignment_id" "uuid", "arm_id" "uuid", "reward" numeric, "sfn" boolean, "true_class" "text", "predicted_class" "text", "validated_by" "uuid", "validated_at" timestamp with time zone, "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  upserted RECORD;
BEGIN
  -- Check if ab_outcomes table exists
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'ab_outcomes') THEN
    INSERT INTO public.ab_outcomes (
      decision_id,
      assessment_id,
      experiment_id,
      assignment_id,
      arm_id,
      reward,
      sfn,
      true_class,
      predicted_class,
      validated_by,
      validated_at
    )
    VALUES (
      p_decision_id,
      p_assessment_id,
      p_experiment_id,
      p_assignment_id,
      p_arm_id,
      p_reward,
      p_sfn,
      p_true_class,
      p_predicted_class,
      p_validated_by,
      COALESCE(p_validated_at, now())
    )
    ON CONFLICT (decision_id) DO UPDATE SET
      assessment_id = EXCLUDED.assessment_id,
      experiment_id = EXCLUDED.experiment_id,
      assignment_id = EXCLUDED.assignment_id,
      arm_id = EXCLUDED.arm_id,
      reward = EXCLUDED.reward,
      sfn = EXCLUDED.sfn,
      true_class = EXCLUDED.true_class,
      predicted_class = EXCLUDED.predicted_class,
      validated_by = EXCLUDED.validated_by,
      validated_at = EXCLUDED.validated_at
    RETURNING * INTO upserted;

    RETURN QUERY SELECT
      upserted.id,
      upserted.decision_id,
      upserted.assessment_id,
      upserted.experiment_id,
      upserted.assignment_id,
      upserted.arm_id,
      upserted.reward,
      upserted.sfn,
      upserted.true_class,
      upserted.predicted_class,
      upserted.validated_by,
      upserted.validated_at,
      upserted.created_at;
  ELSE
    -- Return empty result if table doesn't exist
    RETURN;
  END IF;
END;
$$;


ALTER FUNCTION "public"."log_ab_outcome"("p_decision_id" "uuid", "p_assessment_id" "uuid", "p_experiment_id" "uuid", "p_assignment_id" "uuid", "p_arm_id" "uuid", "p_reward" numeric, "p_sfn" boolean, "p_true_class" "text", "p_predicted_class" "text", "p_validated_by" "uuid", "p_validated_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."log_ab_outcome"("p_decision_id" "uuid", "p_assessment_id" "uuid", "p_experiment_id" "uuid", "p_assignment_id" "uuid", "p_arm_id" "uuid", "p_reward" numeric, "p_sfn" boolean, "p_true_class" "text", "p_predicted_class" "text", "p_validated_by" "uuid", "p_validated_at" timestamp with time zone) IS 'Atomically logs or updates ab_outcomes rows for Safe-LUCB feedback ingestion.';



CREATE OR REPLACE FUNCTION "public"."log_completion_confirmation_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  -- Only log when confirmation status actually changes
  IF OLD.completion_confirmed_by_homeowner != NEW.completion_confirmed_by_homeowner THEN
    -- Only insert if job_status_transitions table exists
    IF EXISTS (
      SELECT 1 FROM information_schema.tables
      WHERE table_schema = 'public'
      AND table_name = 'job_status_transitions'
    ) THEN
      INSERT INTO job_status_transitions (
        job_id,
        from_status,
        to_status,
        transition_type,
        triggered_by_user_id,
        trigger_reason,
        is_valid_transition,
        metadata
      ) VALUES (
        NEW.id,
        OLD.status,
        NEW.status,
        'manual',
        auth.uid(),
        CASE
          WHEN NEW.completion_confirmed_by_homeowner = true THEN 'Homeowner confirmed job completion'
          ELSE 'Completion confirmation status changed'
        END,
        true,
        jsonb_build_object(
          'completion_confirmed', NEW.completion_confirmed_by_homeowner,
          'confirmed_at', NOW(),
          'previous_confirmed', OLD.completion_confirmed_by_homeowner
        )
      );
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."log_completion_confirmation_change"() OWNER TO "postgres";


