CREATE OR REPLACE FUNCTION "public"."log_integration_event"("p_user_integration_id" "uuid", "p_log_level" character varying, "p_event_type" character varying, "p_message" "text", "p_operation" character varying DEFAULT NULL::character varying, "p_entity_type" character varying DEFAULT NULL::character varying, "p_entity_id" character varying DEFAULT NULL::character varying, "p_request_data" "jsonb" DEFAULT NULL::"jsonb", "p_response_data" "jsonb" DEFAULT NULL::"jsonb", "p_processing_time_ms" integer DEFAULT NULL::integer) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    log_id UUID;
    user_id_val UUID;
BEGIN
    -- Get user_id from user_integration
    SELECT ui.user_id INTO user_id_val
    FROM user_integrations ui
    WHERE ui.id = p_user_integration_id;
    
    INSERT INTO integration_logs (
        user_integration_id,
        log_level,
        event_type,
        message,
        operation,
        entity_type,
        entity_id,
        request_data,
        response_data,
        processing_time_ms,
        user_id
    ) VALUES (
        p_user_integration_id,
        p_log_level,
        p_event_type,
        p_message,
        p_operation,
        p_entity_type,
        p_entity_id,
        p_request_data,
        p_response_data,
        p_processing_time_ms,
        user_id_val
    ) RETURNING id INTO log_id;
    
    RETURN log_id;
END;
$$;


ALTER FUNCTION "public"."log_integration_event"("p_user_integration_id" "uuid", "p_log_level" character varying, "p_event_type" character varying, "p_message" "text", "p_operation" character varying, "p_entity_type" character varying, "p_entity_id" character varying, "p_request_data" "jsonb", "p_response_data" "jsonb", "p_processing_time_ms" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_job_status_transition"("p_job_id" "uuid", "p_from_status" "text", "p_to_status" "text", "p_triggered_by_user_id" "uuid" DEFAULT NULL::"uuid", "p_triggered_by_agent" character varying DEFAULT NULL::character varying, "p_trigger_reason" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_transition_id UUID;
  v_is_valid BOOLEAN;
BEGIN
  SELECT EXISTS (
    SELECT 1 FROM job_state_machine_rules
    WHERE from_status = p_from_status
    AND to_status = p_to_status
    AND is_active = TRUE
  ) INTO v_is_valid;

  INSERT INTO job_status_transitions (
    job_id,
    from_status,
    to_status,
    transition_type,
    triggered_by_user_id,
    triggered_by_agent,
    trigger_reason,
    is_valid_transition,
    metadata
  ) VALUES (
    p_job_id,
    p_from_status,
    p_to_status,
    CASE WHEN p_triggered_by_agent IS NOT NULL THEN 'automated' ELSE 'manual' END,
    p_triggered_by_user_id,
    p_triggered_by_agent,
    p_trigger_reason,
    v_is_valid,
    p_metadata
  )
  RETURNING id INTO v_transition_id;

  RETURN v_transition_id;
END;
$$;


