CREATE OR REPLACE FUNCTION "public"."log_message_access_violation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  -- Log if someone tries to access messages on a job they're not assigned to
  IF NOT (
    auth.uid() = NEW.sender_id
    OR auth.uid() = NEW.receiver_id
    OR public.is_admin()
    OR EXISTS (
      SELECT 1 FROM public.jobs
      WHERE id = NEW.job_id
        AND (homeowner_id = auth.uid() OR contractor_id = auth.uid())
        AND contractor_id IS NOT NULL
    )
  ) THEN
    INSERT INTO public.security_events (
      event_type,
      severity,
      user_id,
      ip_address,
      endpoint,
      method,
      details,
      metadata
    ) VALUES (
      'suspicious_activity',
      'medium',
      auth.uid(),
      inet_client_addr(),
      '/messages',
      'SELECT',
      'Attempted to access messages on job without assignment',
      jsonb_build_object('job_id', NEW.job_id, 'message_id', NEW.id)
    );
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."log_message_access_violation"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."log_message_access_violation"() IS 'Logs suspicious attempts to access messages outside of assigned jobs. Used for security monitoring.';



CREATE OR REPLACE FUNCTION "public"."log_search_and_update_suggestions"("p_search_query" "text", "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_search_type" character varying DEFAULT 'general'::character varying, "p_filters" "jsonb" DEFAULT '{}'::"jsonb", "p_session_id" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_search_id UUID;
BEGIN
  INSERT INTO search_analytics (
    user_id,
    search_query,
    search_type,
    filters,
    session_id
  ) VALUES (
    p_user_id,
    p_search_query,
    p_search_type,
    p_filters,
    p_session_id
  )
  RETURNING id INTO v_search_id;

  INSERT INTO search_suggestions (
    suggestion_text,
    suggestion_type,
    usage_count,
    is_auto_generated,
    last_used_at
  ) VALUES (
    p_search_query,
    p_search_type,
    1,
    TRUE,
    NOW()
  )
  ON CONFLICT (suggestion_text, suggestion_type)
  DO UPDATE SET
    usage_count = search_suggestions.usage_count + 1,
    last_used_at = NOW(),
    updated_at = NOW();

  RETURN v_search_id;
END;
$$;


