CREATE OR REPLACE FUNCTION "public"."notify_comment_added"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  post_author_id UUID;
  commenter_name TEXT;
  post_title TEXT;
  parent_comment_author_id UUID;
BEGIN
  -- Get post author
  SELECT contractor_id, title INTO post_author_id, post_title
  FROM public.contractor_posts
  WHERE id = NEW.post_id;

  -- Get commenter's name
  SELECT CONCAT(first_name, ' ', last_name) INTO commenter_name
  FROM public.profiles
  WHERE id = NEW.contractor_id;

  -- Don't notify if user commented on their own post
  IF post_author_id != NEW.contractor_id THEN
    INSERT INTO public.notifications (user_id, title, message, type, action_url)
    VALUES (
      post_author_id,
      'New Comment',
      COALESCE(commenter_name, 'Someone') || ' commented on your post: ' || COALESCE(post_title, ''),
      'comment_added',
      '/contractor/social/post/' || NEW.post_id
    );
  END IF;

  -- If this is a reply, notify parent comment author
  IF NEW.parent_comment_id IS NOT NULL THEN
    SELECT contractor_id INTO parent_comment_author_id
    FROM public.contractor_post_comments
    WHERE id = NEW.parent_comment_id;

    -- Don't notify if replying to own comment
    IF parent_comment_author_id IS NOT NULL AND parent_comment_author_id != NEW.contractor_id THEN
      INSERT INTO public.notifications (user_id, title, message, type, action_url)
      VALUES (
        parent_comment_author_id,
        'Reply to Comment',
        COALESCE(commenter_name, 'Someone') || ' replied to your comment',
        'comment_replied',
        '/contractor/social/post/' || NEW.post_id
      );
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notify_comment_added"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_homeowner_of_interaction"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    v_homeowner_id UUID;
    v_contractor_name TEXT;
    v_job_title TEXT;
    v_message TEXT;
BEGIN
    -- Get homeowner_id and job title
    SELECT homeowner_id, title INTO v_homeowner_id, v_job_title
    FROM jobs WHERE id = NEW.job_id;

    -- Get contractor name
    SELECT COALESCE(first_name || ' ' || last_name, company_name, email) INTO v_contractor_name
    FROM users WHERE id = NEW.contractor_id;

    -- Create appropriate message based on trigger source
    IF TG_TABLE_NAME = 'job_views' THEN
        v_message := v_contractor_name || ' viewed your job: ' || v_job_title;

        -- Only create notification for first view
        IF COALESCE(NEW.view_count, 1) = 1 THEN
            INSERT INTO job_interaction_notifications (
                job_id, homeowner_id, contractor_id, interaction_type, message
            ) VALUES (
                NEW.job_id, v_homeowner_id, NEW.contractor_id, 'viewed', v_message
            );
        END IF;

    ELSIF TG_TABLE_NAME = 'saved_jobs' THEN
        v_message := v_contractor_name || ' saved your job: ' || v_job_title;

        INSERT INTO job_interaction_notifications (
            job_id, homeowner_id, contractor_id, interaction_type, message
        ) VALUES (
            NEW.job_id, v_homeowner_id, NEW.contractor_id, 'saved', v_message
        );

    ELSIF TG_TABLE_NAME = 'bids' THEN
        IF TG_OP = 'INSERT' THEN
            v_message := v_contractor_name || ' placed a bid on: ' || v_job_title;
            INSERT INTO job_interaction_notifications (
                job_id, homeowner_id, contractor_id, interaction_type, message
            ) VALUES (
                NEW.job_id, v_homeowner_id, NEW.contractor_id, 'bid_placed', v_message
            );
        ELSIF TG_OP = 'UPDATE' AND OLD.amount != NEW.amount THEN
            v_message := v_contractor_name || ' updated their bid on: ' || v_job_title;
            INSERT INTO job_interaction_notifications (
                job_id, homeowner_id, contractor_id, interaction_type, message
            ) VALUES (
                NEW.job_id, v_homeowner_id, NEW.contractor_id, 'bid_updated', v_message
            );
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notify_homeowner_of_interaction"() OWNER TO "postgres";


