CREATE OR REPLACE FUNCTION "public"."predict_next_job_status"("p_job_id" "uuid") RETURNS TABLE("predicted_status" "text", "confidence" numeric, "predicted_date" timestamp with time zone, "factors" "jsonb")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_current_status TEXT;
  v_job_age_days INTEGER;
  v_has_bids BOOLEAN;
  v_has_contractor BOOLEAN;
BEGIN
  SELECT
    j.status,
    EXTRACT(DAY FROM NOW() - j.created_at)::INTEGER,
    EXISTS(SELECT 1 FROM bids WHERE job_id = j.id),
    j.contractor_id IS NOT NULL
  INTO
    v_current_status,
    v_job_age_days,
    v_has_bids,
    v_has_contractor
  FROM jobs j
  WHERE j.id = p_job_id;

  IF v_current_status = 'posted' THEN
    IF v_has_bids AND v_job_age_days < 7 THEN
      RETURN QUERY SELECT
        'assigned'::TEXT,
        0.75::DECIMAL(5,4),
        NOW() + INTERVAL '3 days',
        jsonb_build_object('reason', 'job_has_active_bids', 'age_days', v_job_age_days);
    ELSIF v_job_age_days >= 7 AND NOT v_has_bids THEN
      RETURN QUERY SELECT
        'cancelled'::TEXT,
        0.85::DECIMAL(5,4),
        NOW() + INTERVAL '1 day',
        jsonb_build_object('reason', 'no_bids_after_7_days', 'age_days', v_job_age_days);
    END IF;
  ELSIF v_current_status = 'assigned' THEN
    RETURN QUERY SELECT
      'in_progress'::TEXT,
      0.70::DECIMAL(5,4),
      NOW() + INTERVAL '2 days',
      jsonb_build_object('reason', 'assigned_jobs_usually_start_soon');
  ELSIF v_current_status = 'in_progress' THEN
    RETURN QUERY SELECT
      'completed'::TEXT,
      0.65::DECIMAL(5,4),
      NOW() + INTERVAL '7 days',
      jsonb_build_object('reason', 'average_job_completion_time');
  END IF;
END;
$$;


ALTER FUNCTION "public"."predict_next_job_status"("p_job_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."predict_next_job_status"("p_job_id" "uuid") IS 'Predicts the next status for a job based on current state and patterns';



CREATE OR REPLACE FUNCTION "public"."prevent_completion_confirmation_reversal"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  -- Once confirmed, cannot be unconfirmed
  IF OLD.completion_confirmed_by_homeowner = true AND NEW.completion_confirmed_by_homeowner = false THEN
    RAISE EXCEPTION 'Cannot unconfirm job completion once confirmed';
  END IF;

  -- Only homeowners can set completion_confirmed_by_homeowner to true
  IF NEW.completion_confirmed_by_homeowner = true AND OLD.completion_confirmed_by_homeowner = false THEN
    IF NEW.homeowner_id != auth.uid() THEN
      RAISE EXCEPTION 'Only the homeowner can confirm job completion';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."prevent_completion_confirmation_reversal"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."production_maintenance"() RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
    -- Clean old performance metrics (keep 90 days)
    DELETE FROM production_metrics WHERE recorded_at < NOW() - INTERVAL '90 days';
    
    -- Clean old messages (keep 1 year)
    DELETE FROM messages WHERE created_at < NOW() - INTERVAL '1 year' AND read = true;
    
    -- Update table statistics for query optimizer
    ANALYZE users, jobs, reviews, escrow_transactions, messages, notifications;
    
    -- Refresh critical materialized views
    REFRESH MATERIALIZED VIEW CONCURRENTLY dashboard_stats;
    REFRESH MATERIALIZED VIEW CONCURRENTLY mv_user_performance_analytics;
END;
$$;


ALTER FUNCTION "public"."production_maintenance"() OWNER TO "postgres";


