CREATE OR REPLACE FUNCTION "public"."queue_contractor_embedding"("p_contractor_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_content TEXT;
  v_queue_id UUID;
  v_skills TEXT;
BEGIN
  SELECT STRING_AGG(skill_name, ', ')
  INTO v_skills
  FROM contractor_skills
  WHERE contractor_id = p_contractor_id;

  SELECT
    CONCAT_WS(' | ',
      first_name,
      last_name,
      COALESCE(bio, ''),
      COALESCE(location, ''),
      COALESCE(v_skills, '')
    )
  INTO v_content
  FROM users
  WHERE id = p_contractor_id AND role = 'contractor';

  IF v_content IS NULL THEN
    RAISE EXCEPTION 'Contractor not found: %', p_contractor_id;
  END IF;

  INSERT INTO embedding_generation_queue (
    entity_type,
    entity_id,
    content_text,
    priority
  ) VALUES (
    'contractor',
    p_contractor_id,
    v_content,
    1
  )
  ON CONFLICT (entity_type, entity_id) WHERE status != 'completed'
  DO UPDATE SET
    content_text = EXCLUDED.content_text,
    status = 'pending',
    retry_count = 0,
    updated_at = NOW()
  RETURNING id INTO v_queue_id;

  RETURN v_queue_id;
END;
$$;


ALTER FUNCTION "public"."queue_contractor_embedding"("p_contractor_id" "uuid") OWNER TO "postgres";


