CREATE OR REPLACE FUNCTION "public"."release_escrow_funds"("p_escrow_id" "uuid", "p_reason" "text" DEFAULT 'Job completed successfully'::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_current_status TEXT;
BEGIN
  SELECT status INTO v_current_status
  FROM escrow_payments
  WHERE id = p_escrow_id;

  IF v_current_status IS NULL THEN
    RAISE EXCEPTION 'Escrow payment not found';
  END IF;

  IF v_current_status NOT IN ('held', 'pending') THEN
    RAISE EXCEPTION 'Cannot release escrow in status: %', v_current_status;
  END IF;

  UPDATE escrow_payments
  SET
    status = 'released',
    metadata = jsonb_set(
      COALESCE(metadata, '{}'::jsonb),
      '{release_reason}',
      to_jsonb(p_reason)
    )
  WHERE id = p_escrow_id;

  RETURN TRUE;
END;
$$;


