CREATE OR REPLACE FUNCTION "public"."release_idempotency_claim"("p_idempotency_key" "text", "p_operation" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_deleted INT;
BEGIN
  DELETE FROM public.idempotency_keys
   WHERE idempotency_key = p_idempotency_key
     AND operation       = p_operation
     AND status          = 'pending';
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted > 0;
END;
$$;


