CREATE OR REPLACE FUNCTION "public"."revoke_token_family"("p_family_id" "uuid", "p_reason" "text" DEFAULT 'Token reuse detected - possible breach'::"text") RETURNS TABLE("revoked_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_revoked_count BIGINT;
BEGIN
  UPDATE public.refresh_tokens SET revoked_at = NOW(), revoked_reason = p_reason WHERE family_id = p_family_id AND revoked_at IS NULL AND expires_at > NOW();
  GET DIAGNOSTICS v_revoked_count = ROW_COUNT;
  RETURN QUERY SELECT v_revoked_count;
END;
$$;


