CREATE OR REPLACE FUNCTION "public"."rotate_refresh_token"("p_user_id" "uuid", "p_token_hash" "text") RETURNS TABLE("user_email" "text", "user_role" "text", "family_id" "uuid", "next_generation" integer, "session_started_at" timestamp with time zone, "last_activity_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_old_token RECORD;
  v_next_gen INTEGER;
BEGIN
  -- Get old token details with row-level lock (prevents concurrent rotations)
  -- Fixed: JOIN profiles instead of dropped users table
  SELECT rt.*, p.email, p.role
  INTO v_old_token
  FROM refresh_tokens rt
  JOIN profiles p ON p.id = rt.user_id
  WHERE rt.token_hash = p_token_hash
    AND rt.user_id = p_user_id
    AND rt.revoked_at IS NULL
    AND rt.expires_at > NOW()
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  -- Check for token reuse (breach detection)
  IF v_old_token.consumed_at IS NOT NULL THEN
    UPDATE refresh_tokens
    SET revoked_at = NOW()
    WHERE family_id = v_old_token.family_id
      AND revoked_at IS NULL;

    RAISE EXCEPTION 'Token reuse detected - security breach';
  END IF;

  -- Mark old token as consumed
  UPDATE refresh_tokens
  SET consumed_at = NOW()
  WHERE token_hash = p_token_hash;

  v_next_gen := COALESCE(v_old_token.generation, 0) + 1;

  user_email := v_old_token.email;
  user_role := v_old_token.role;
  family_id := v_old_token.family_id;
  next_generation := v_next_gen;
  session_started_at := v_old_token.session_started_at;
  last_activity_at := v_old_token.last_activity_at;

  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."rotate_refresh_token"("p_user_id" "uuid", "p_token_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sanitize_text"("input" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  IF input IS NULL THEN
    RETURN NULL;
  END IF;
  
  -- Remove potentially dangerous characters
  RETURN regexp_replace(
    regexp_replace(
      regexp_replace(input, '<[^>]*>', '', 'g'), -- Remove HTML tags
      '[<>''"`]', '', 'g'), -- Remove dangerous characters
    '\s+', ' ', 'g' -- Normalize whitespace
  );
END;
$$;


ALTER FUNCTION "public"."sanitize_text"("input" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sanitize_text"("input" "text") IS 'Sanitizes text input to prevent XSS';



CREATE OR REPLACE FUNCTION "public"."search_contractor_posts"("search_text" "text", "post_type_filter" "text" DEFAULT NULL::"text", "is_active_filter" boolean DEFAULT true, "is_flagged_filter" boolean DEFAULT false, "limit_count" integer DEFAULT 50, "offset_count" integer DEFAULT 0, "sort_by" "text" DEFAULT 'newest'::"text") RETURNS TABLE("id" "uuid", "contractor_id" "uuid", "title" character varying, "content" "text", "post_type" character varying, "images" "text"[], "job_id" "uuid", "skills_used" "text"[], "materials_used" "text"[], "project_duration" integer, "project_cost" numeric, "latitude" numeric, "longitude" numeric, "location_radius" integer, "likes_count" integer, "comments_count" integer, "shares_count" integer, "views_count" integer, "is_active" boolean, "is_flagged" boolean, "is_public" boolean, "is_featured" boolean, "is_verified" boolean, "verified_by" "uuid", "verified_at" timestamp with time zone, "tags" "text"[], "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "rank" real)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  query_tsquery tsquery;
BEGIN
  -- Validate and sanitize inputs
  search_text := TRIM(COALESCE(search_text, ''));
  limit_count := LEAST(GREATEST(limit_count, 1), 100); -- Max 100 results
  offset_count := GREATEST(offset_count, 0);

  -- If search text is empty, return all posts (filtered)
  IF search_text = '' THEN
    RETURN QUERY
    SELECT
      cp.id,
      cp.contractor_id,
      cp.title,
      cp.content,
      cp.post_type,
      cp.images,
      cp.job_id,
      cp.skills_used,
      cp.materials_used,
      cp.project_duration,
      cp.project_cost,
      cp.latitude,
      cp.longitude,
      cp.location_radius,
      cp.likes_count,
      cp.comments_count,
      cp.shares_count,
      cp.views_count,
      cp.is_active,
      cp.is_flagged,
      cp.is_public,
      cp.is_featured,
      cp.is_verified,
      cp.verified_by,
      cp.verified_at,
      cp.tags,
      cp.created_at,
      cp.updated_at,
      0::REAL as rank
    FROM public.contractor_posts cp
    WHERE cp.is_active = is_active_filter
      AND cp.is_flagged = is_flagged_filter
      AND (post_type_filter IS NULL OR cp.post_type = post_type_filter)
    ORDER BY
      CASE
        WHEN sort_by = 'popular' THEN cp.likes_count
        WHEN sort_by = 'most_commented' THEN cp.comments_count
        ELSE 0
      END DESC,
      CASE
        WHEN sort_by = 'newest' THEN cp.created_at
        ELSE NULL
      END DESC NULLS LAST
    LIMIT limit_count
    OFFSET offset_count;
    RETURN;
  END IF;

  -- Convert search text to tsquery (handle multiple words and phrases)
  -- Using plainto_tsquery for simple, safe query parsing
  query_tsquery := plainto_tsquery('english', search_text);

  -- Return query with full-text search ranking
  RETURN QUERY
  SELECT
    cp.id,
    cp.contractor_id,
    cp.title,
    cp.content,
    cp.post_type,
    cp.images,
    cp.job_id,
    cp.skills_used,
    cp.materials_used,
    cp.project_duration,
    cp.project_cost,
    cp.latitude,
    cp.longitude,
    cp.location_radius,
    cp.likes_count,
    cp.comments_count,
    cp.shares_count,
    cp.views_count,
    cp.is_active,
    cp.is_flagged,
    cp.is_public,
    cp.is_featured,
    cp.is_verified,
    cp.verified_by,
    cp.verified_at,
    cp.tags,
    cp.created_at,
    cp.updated_at,
    ts_rank(cp.search_vector, query_tsquery) as rank
  FROM public.contractor_posts cp
  WHERE cp.search_vector @@ query_tsquery
    AND cp.is_active = is_active_filter
    AND cp.is_flagged = is_flagged_filter
    AND (post_type_filter IS NULL OR cp.post_type = post_type_filter)
  ORDER BY
    CASE
      WHEN sort_by = 'relevance' THEN ts_rank(cp.search_vector, query_tsquery)
      WHEN sort_by = 'popular' THEN cp.likes_count::REAL / 100.0
      WHEN sort_by = 'most_commented' THEN cp.comments_count::REAL / 100.0
      ELSE 0
    END DESC,
    CASE
      WHEN sort_by = 'newest' THEN cp.created_at
      ELSE NULL
    END DESC NULLS LAST
  LIMIT limit_count
  OFFSET offset_count;

  RETURN;
END;
$$;


ALTER FUNCTION "public"."search_contractor_posts"("search_text" "text", "post_type_filter" "text", "is_active_filter" boolean, "is_flagged_filter" boolean, "limit_count" integer, "offset_count" integer, "sort_by" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."search_contractor_posts"("search_text" "text", "post_type_filter" "text", "is_active_filter" boolean, "is_flagged_filter" boolean, "limit_count" integer, "offset_count" integer, "sort_by" "text") IS 'Secure full-text search for contractor posts using tsvector.
Safe from SQL injection. Supports ranking by relevance, popularity, comments, or date.
Use this for semantic/keyword search with better performance.';



CREATE OR REPLACE FUNCTION "public"."search_contractor_posts_ilike"("search_text" "text", "post_type_filter" "text" DEFAULT NULL::"text", "is_active_filter" boolean DEFAULT true, "is_flagged_filter" boolean DEFAULT false, "limit_count" integer DEFAULT 50, "offset_count" integer DEFAULT 0, "sort_by" "text" DEFAULT 'newest'::"text") RETURNS TABLE("id" "uuid", "contractor_id" "uuid", "title" character varying, "content" "text", "post_type" character varying, "images" "text"[], "job_id" "uuid", "skills_used" "text"[], "materials_used" "text"[], "project_duration" integer, "project_cost" numeric, "latitude" numeric, "longitude" numeric, "location_radius" integer, "likes_count" integer, "comments_count" integer, "shares_count" integer, "views_count" integer, "is_active" boolean, "is_flagged" boolean, "is_public" boolean, "is_featured" boolean, "is_verified" boolean, "verified_by" "uuid", "verified_at" timestamp with time zone, "tags" "text"[], "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  search_pattern TEXT;
BEGIN
  -- Validate and sanitize inputs
  search_text := TRIM(COALESCE(search_text, ''));
  limit_count := LEAST(GREATEST(limit_count, 1), 100); -- Max 100 results
  offset_count := GREATEST(offset_count, 0);

  -- If search text is empty, return all posts (filtered)
  IF search_text = '' THEN
    RETURN QUERY
    SELECT
      cp.id,
      cp.contractor_id,
      cp.title,
      cp.content,
      cp.post_type,
      cp.images,
      cp.job_id,
      cp.skills_used,
      cp.materials_used,
      cp.project_duration,
      cp.project_cost,
      cp.latitude,
      cp.longitude,
      cp.location_radius,
      cp.likes_count,
      cp.comments_count,
      cp.shares_count,
      cp.views_count,
      cp.is_active,
      cp.is_flagged,
      cp.is_public,
      cp.is_featured,
      cp.is_verified,
      cp.verified_by,
      cp.verified_at,
      cp.tags,
      cp.created_at,
      cp.updated_at
    FROM public.contractor_posts cp
    WHERE cp.is_active = is_active_filter
      AND cp.is_flagged = is_flagged_filter
      AND (post_type_filter IS NULL OR cp.post_type = post_type_filter)
    ORDER BY
      CASE
        WHEN sort_by = 'popular' THEN cp.likes_count
        WHEN sort_by = 'most_commented' THEN cp.comments_count
        ELSE 0
      END DESC,
      CASE
        WHEN sort_by = 'newest' THEN cp.created_at
        ELSE NULL
      END DESC NULLS LAST
    LIMIT limit_count
    OFFSET offset_count;
    RETURN;
  END IF;

  -- Create pattern for ILIKE (safe because it's parameterized in the query)
  search_pattern := '%' || search_text || '%';

  -- Return query with ILIKE search (safe from SQL injection via parameterization)
  RETURN QUERY
  SELECT
    cp.id,
    cp.contractor_id,
    cp.title,
    cp.content,
    cp.post_type,
    cp.images,
    cp.job_id,
    cp.skills_used,
    cp.materials_used,
    cp.project_duration,
    cp.project_cost,
    cp.latitude,
    cp.longitude,
    cp.location_radius,
    cp.likes_count,
    cp.comments_count,
    cp.shares_count,
    cp.views_count,
    cp.is_active,
    cp.is_flagged,
    cp.is_public,
    cp.is_featured,
    cp.is_verified,
    cp.verified_by,
    cp.verified_at,
    cp.tags,
    cp.created_at,
    cp.updated_at
  FROM public.contractor_posts cp
  WHERE (cp.title ILIKE search_pattern OR cp.content ILIKE search_pattern)
    AND cp.is_active = is_active_filter
    AND cp.is_flagged = is_flagged_filter
    AND (post_type_filter IS NULL OR cp.post_type = post_type_filter)
  ORDER BY
    CASE
      WHEN sort_by = 'popular' THEN cp.likes_count
      WHEN sort_by = 'most_commented' THEN cp.comments_count
      ELSE 0
    END DESC,
    CASE
      WHEN sort_by = 'newest' THEN cp.created_at
      ELSE NULL
    END DESC NULLS LAST
  LIMIT limit_count
  OFFSET offset_count;

  RETURN;
END;
$$;


ALTER FUNCTION "public"."search_contractor_posts_ilike"("search_text" "text", "post_type_filter" "text", "is_active_filter" boolean, "is_flagged_filter" boolean, "limit_count" integer, "offset_count" integer, "sort_by" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."search_contractor_posts_ilike"("search_text" "text", "post_type_filter" "text", "is_active_filter" boolean, "is_flagged_filter" boolean, "limit_count" integer, "offset_count" integer, "sort_by" "text") IS 'Secure ILIKE-based search for contractor posts with parameterized queries.
Safe from SQL injection. Use this for partial/fuzzy matching when full-text search is too strict.
Note: ILIKE is slower than full-text search on large datasets.';



CREATE OR REPLACE FUNCTION "public"."search_contractors_semantic"("query_embedding" "public"."vector", "skills_filter" "text"[] DEFAULT NULL::"text"[], "location_filter" "text" DEFAULT NULL::"text", "min_rating" numeric DEFAULT NULL::numeric, "verification_required" boolean DEFAULT false, "match_limit" integer DEFAULT 20, "similarity_threshold" double precision DEFAULT 0.7) RETURNS TABLE("id" "uuid", "first_name" "text", "last_name" "text", "email" "text", "bio" "text", "location" "text", "rating" numeric, "total_jobs" integer, "is_verified" boolean, "similarity" double precision)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    u.id,
    u.first_name,
    u.last_name,
    u.email,
    u.bio,
    u.location,
    u.rating,
    u.total_jobs,
    u.is_verified,
    1 - (u.embedding <=> query_embedding) AS similarity
  FROM users u
  WHERE
    u.role = 'contractor'
    AND u.embedding IS NOT NULL
    AND (location_filter IS NULL OR u.location ILIKE '%' || location_filter || '%')
    AND (min_rating IS NULL OR u.rating >= min_rating)
    AND (verification_required = FALSE OR u.is_verified = TRUE)
    AND (skills_filter IS NULL OR EXISTS (
      SELECT 1 FROM contractor_skills cs
      WHERE cs.contractor_id = u.id
      AND cs.skill_name = ANY(skills_filter)
    ))
    AND (1 - (u.embedding <=> query_embedding)) >= similarity_threshold
  ORDER BY u.embedding <=> query_embedding
  LIMIT match_limit;
END;
$$;


ALTER FUNCTION "public"."search_contractors_semantic"("query_embedding" "public"."vector", "skills_filter" "text"[], "location_filter" "text", "min_rating" numeric, "verification_required" boolean, "match_limit" integer, "similarity_threshold" double precision) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."search_contractors_semantic"("query_embedding" "public"."vector", "skills_filter" "text"[], "location_filter" "text", "min_rating" numeric, "verification_required" boolean, "match_limit" integer, "similarity_threshold" double precision) IS 'Semantic search for contractors using vector similarity. Returns contractors ordered by cosine similarity to query embedding.';



CREATE OR REPLACE FUNCTION "public"."search_jobs_semantic"("query_embedding" "public"."vector", "category_filter" "text" DEFAULT NULL::"text", "location_filter" "text" DEFAULT NULL::"text", "price_min" numeric DEFAULT NULL::numeric, "price_max" numeric DEFAULT NULL::numeric, "status_filter" "text" DEFAULT 'posted'::"text", "match_limit" integer DEFAULT 20, "similarity_threshold" double precision DEFAULT 0.7) RETURNS TABLE("id" "uuid", "title" "text", "description" "text", "category" "text", "location" "text", "budget" numeric, "status" "text", "homeowner_id" "uuid", "similarity" double precision, "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    j.id,
    j.title,
    j.description,
    j.category,
    j.location,
    j.budget,
    j.status,
    j.homeowner_id,
    1 - (j.embedding <=> query_embedding) AS similarity,
    j.created_at
  FROM jobs j
  WHERE
    j.embedding IS NOT NULL
    AND (category_filter IS NULL OR j.category = category_filter)
    AND (location_filter IS NULL OR j.location ILIKE '%' || location_filter || '%')
    AND (price_min IS NULL OR j.budget >= price_min)
    AND (price_max IS NULL OR j.budget <= price_max)
    AND (status_filter IS NULL OR j.status = status_filter)
    AND (1 - (j.embedding <=> query_embedding)) >= similarity_threshold
  ORDER BY j.embedding <=> query_embedding
  LIMIT match_limit;
END;
$$;


ALTER FUNCTION "public"."search_jobs_semantic"("query_embedding" "public"."vector", "category_filter" "text", "location_filter" "text", "price_min" numeric, "price_max" numeric, "status_filter" "text", "match_limit" integer, "similarity_threshold" double precision) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."search_jobs_semantic"("query_embedding" "public"."vector", "category_filter" "text", "location_filter" "text", "price_min" numeric, "price_max" numeric, "status_filter" "text", "match_limit" integer, "similarity_threshold" double precision) IS 'Semantic search for jobs using vector similarity. Returns jobs ordered by cosine similarity to query embedding.';



CREATE OR REPLACE FUNCTION "public"."search_pathology_semantic"("query_embedding" "public"."vector", "match_threshold" double precision DEFAULT 0.70, "match_count" integer DEFAULT 5) RETURNS TABLE("id" "uuid", "defect_slug" "text", "category" "text", "name" "text", "aka" "text"[], "description" "text", "why_it_happens" "text", "visual_indicators" "text"[], "photo_detection_cues" "text"[], "common_misdiagnosis" "text"[], "differential_diagnosis" "text", "rics_condition_rating" smallint, "urgency" "text", "remediation_summary" "text", "remediation_steps" "text"[], "cost_range_gbp_min" integer, "cost_range_gbp_max" integer, "regulatory_reference" "text"[], "property_age_risk" "text"[], "construction_type_risk" "text"[], "specialist_required" boolean, "further_investigation" "text", "source_authority" "text", "similarity" double precision)
    LANGUAGE "sql" STABLE PARALLEL SAFE
    SET "search_path" TO ''
    AS $$
  SELECT
    id, defect_slug, category, name, aka,
    description, why_it_happens, visual_indicators,
    photo_detection_cues, common_misdiagnosis, differential_diagnosis,
    rics_condition_rating, urgency, remediation_summary, remediation_steps,
    cost_range_gbp_min, cost_range_gbp_max, regulatory_reference,
    property_age_risk, construction_type_risk, specialist_required,
    further_investigation, source_authority,
    1 - (embedding <=> query_embedding) AS similarity
  FROM building_pathology_knowledge
  WHERE embedding IS NOT NULL
    AND 1 - (embedding <=> query_embedding) > match_threshold
  ORDER BY embedding <=> query_embedding
  LIMIT match_count;
$$;


