CREATE OR REPLACE FUNCTION "public"."set_user_integration_secret"("p_id" "uuid", "p_kind" "text", "p_value" "text", "p_key" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.role() <> 'service_role' THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.user_integrations
      WHERE id = p_id AND user_id = auth.uid()
    ) THEN
      RAISE EXCEPTION 'Unauthorized integration access';
    END IF;
  END IF;

  IF p_kind = 'api_key' THEN
    UPDATE public.user_integrations
      SET api_key_encrypted = pgp_sym_encrypt(p_value, p_key)
      WHERE id = p_id
        AND (auth.role() = 'service_role' OR user_id = auth.uid());
  ELSIF p_kind = 'access_token' THEN
    UPDATE public.user_integrations
      SET oauth_access_token_encrypted = pgp_sym_encrypt(p_value, p_key)
      WHERE id = p_id
        AND (auth.role() = 'service_role' OR user_id = auth.uid());
  ELSIF p_kind = 'refresh_token' THEN
    UPDATE public.user_integrations
      SET oauth_refresh_token_encrypted = pgp_sym_encrypt(p_value, p_key)
      WHERE id = p_id
        AND (auth.role() = 'service_role' OR user_id = auth.uid());
  ELSE
    RAISE EXCEPTION 'Unknown secret kind %', p_kind;
  END IF;
END $$;


ALTER FUNCTION "public"."set_user_integration_secret"("p_id" "uuid", "p_kind" "text", "p_value" "text", "p_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."stamp_contractor_activation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF (TG_OP = 'INSERT' AND NEW.status IN ('accepted', 'won'))
     OR (TG_OP = 'UPDATE'
         AND NEW.status IN ('accepted', 'won')
         AND (OLD.status IS DISTINCT FROM NEW.status))
  THEN
    UPDATE public.profiles
    SET activated_at = COALESCE(NEW.updated_at, NEW.created_at, NOW())
    WHERE id = NEW.contractor_id
      AND activated_at IS NULL;
  END IF;
  RETURN NEW;
END;
$$;


