CREATE OR REPLACE FUNCTION "public"."track_automation_action"("p_user_id" "uuid", "p_success" boolean) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  UPDATE user_agent_settings
  SET
    total_automated_actions = COALESCE(total_automated_actions, 0) + 1,
    successful_automations = CASE WHEN p_success THEN COALESCE(successful_automations, 0) + 1 ELSE successful_automations END,
    failed_automations = CASE WHEN NOT p_success THEN COALESCE(failed_automations, 0) + 1 ELSE failed_automations END,
