CREATE OR REPLACE FUNCTION "public"."try_claim_idempotency_key"("p_idempotency_key" "text", "p_operation" "text", "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_metadata" "jsonb" DEFAULT NULL::"jsonb", "p_stale_after_seconds" integer DEFAULT 60) RETURNS TABLE("claimed" boolean, "is_duplicate" boolean, "is_pending" boolean, "cached_result" "jsonb", "cached_created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_new_id   UUID;
  v_existing public.idempotency_keys%ROWTYPE;
  v_stale_cutoff TIMESTAMPTZ;
BEGIN
  INSERT INTO public.idempotency_keys (
    idempotency_key, operation, result, user_id, metadata, status, claimed_at
  )
  VALUES (
    p_idempotency_key, p_operation, '{}'::jsonb, p_user_id, p_metadata, 'pending', NOW()
  )
  ON CONFLICT (idempotency_key, operation) DO NOTHING
  RETURNING id INTO v_new_id;

  IF v_new_id IS NOT NULL THEN
    RETURN QUERY SELECT TRUE, FALSE, FALSE, NULL::jsonb, NULL::timestamptz;
    RETURN;
  END IF;

  SELECT * INTO v_existing
  FROM public.idempotency_keys
  WHERE idempotency_key = p_idempotency_key AND operation = p_operation;

  IF v_existing.status = 'completed' THEN
    RETURN QUERY SELECT FALSE, TRUE, FALSE, v_existing.result, v_existing.created_at;
    RETURN;
  END IF;

  v_stale_cutoff := NOW() - make_interval(secs => p_stale_after_seconds);

  IF v_existing.claimed_at IS NULL OR v_existing.claimed_at < v_stale_cutoff THEN
    UPDATE public.idempotency_keys
       SET claimed_at = NOW(),
           result     = '{}'::jsonb,
           metadata   = COALESCE(p_metadata, metadata),
           user_id    = COALESCE(p_user_id, user_id)
     WHERE id = v_existing.id
       AND (claimed_at IS NULL OR claimed_at < v_stale_cutoff);
    IF FOUND THEN
      RETURN QUERY SELECT TRUE, FALSE, FALSE, NULL::jsonb, NULL::timestamptz;
      RETURN;
    END IF;
  END IF;

  RETURN QUERY SELECT FALSE, FALSE, TRUE, NULL::jsonb, v_existing.created_at;
END;
$$;


ALTER FUNCTION "public"."try_claim_idempotency_key"("p_idempotency_key" "text", "p_operation" "text", "p_user_id" "uuid", "p_metadata" "jsonb", "p_stale_after_seconds" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."try_claim_idempotency_key"("p_idempotency_key" "text", "p_operation" "text", "p_user_id" "uuid", "p_metadata" "jsonb", "p_stale_after_seconds" integer) IS 'service_role-only. anon revoked 2026-05-27 (audit-P2-10); authenticated revoked 2026-05-28 — accepts arbitrary p_user_id and the sole caller (web idempotency.ts) uses the service-role client, so authenticated EXECUTE was an unused cross-tenant cache-poisoning vector.';



CREATE OR REPLACE FUNCTION "public"."try_claim_idempotency_key"("p_idempotency_key" "text", "p_operation" "text", "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_metadata" "jsonb" DEFAULT NULL::"jsonb", "p_stale_after_seconds" integer DEFAULT 60, "p_ttl_seconds" integer DEFAULT 86400) RETURNS TABLE("claimed" boolean, "is_duplicate" boolean, "is_pending" boolean, "cached_result" "jsonb", "cached_created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_new_id       UUID;
  v_existing     public.idempotency_keys%ROWTYPE;
  v_stale_cutoff TIMESTAMPTZ;
  v_ttl_cutoff   TIMESTAMPTZ;
BEGIN
  v_ttl_cutoff := NOW() - make_interval(secs => p_ttl_seconds);
  DELETE FROM public.idempotency_keys
   WHERE idempotency_key = p_idempotency_key
     AND operation       = p_operation
     AND status          = 'completed'
     AND created_at      < v_ttl_cutoff;

  INSERT INTO public.idempotency_keys (
    idempotency_key, operation, result, user_id, metadata, status, claimed_at
  )
  VALUES (
    p_idempotency_key, p_operation, '{}'::jsonb, p_user_id, p_metadata, 'pending', NOW()
  )
  ON CONFLICT (idempotency_key, operation) DO NOTHING
  RETURNING id INTO v_new_id;

  IF v_new_id IS NOT NULL THEN
    RETURN QUERY SELECT TRUE, FALSE, FALSE, NULL::jsonb, NULL::timestamptz;
    RETURN;
  END IF;

  SELECT * INTO v_existing
  FROM public.idempotency_keys
  WHERE idempotency_key = p_idempotency_key AND operation = p_operation;

  IF v_existing.status = 'completed' THEN
    RETURN QUERY SELECT FALSE, TRUE, FALSE, v_existing.result, v_existing.created_at;
    RETURN;
  END IF;

  v_stale_cutoff := NOW() - make_interval(secs => p_stale_after_seconds);

  IF v_existing.claimed_at IS NULL OR v_existing.claimed_at < v_stale_cutoff THEN
    UPDATE public.idempotency_keys
       SET claimed_at = NOW(),
           result     = '{}'::jsonb,
           metadata   = COALESCE(p_metadata, metadata),
           user_id    = COALESCE(p_user_id, user_id)
     WHERE id = v_existing.id
       AND (claimed_at IS NULL OR claimed_at < v_stale_cutoff);
    IF FOUND THEN
      RETURN QUERY SELECT TRUE, FALSE, FALSE, NULL::jsonb, NULL::timestamptz;
      RETURN;
    END IF;
  END IF;

  RETURN QUERY SELECT FALSE, FALSE, TRUE, NULL::jsonb, v_existing.created_at;
END;
$$;


