CREATE OR REPLACE FUNCTION "public"."update_contractor_rating"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_reviewee_id UUID;
  v_new_rating NUMERIC;
BEGIN
  -- Pick whichever side of the row is available. INSERT/UPDATE have
  -- NEW; DELETE has OLD; an UPDATE that flipped reviewee_id needs both.
  v_reviewee_id := COALESCE(NEW.reviewee_id, OLD.reviewee_id);

  SELECT ROUND(AVG(rating)::numeric, 2)
    INTO v_new_rating
  FROM public.reviews
  WHERE reviewee_id = v_reviewee_id;

  -- Nulls cleanly when no reviews remain (instead of holding the
  -- stale pre-delete value).
  UPDATE public.profiles
     SET rating = v_new_rating
   WHERE id = v_reviewee_id;

  -- If an UPDATE moved a review from one contractor to another, the
  -- old contractor's rating also needs to be recomputed.
  IF TG_OP = 'UPDATE'
     AND OLD.reviewee_id IS NOT NULL
     AND OLD.reviewee_id <> NEW.reviewee_id THEN
    SELECT ROUND(AVG(rating)::numeric, 2)
      INTO v_new_rating
    FROM public.reviews
    WHERE reviewee_id = OLD.reviewee_id;
    UPDATE public.profiles
       SET rating = v_new_rating
     WHERE id = OLD.reviewee_id;
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;


