CREATE OR REPLACE FUNCTION "public"."update_fnr_statistics"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  p NUMERIC;
  z NUMERIC := 1.96;
  n NUMERIC;
  denominator NUMERIC;
  center NUMERIC;
  margin NUMERIC;
BEGIN
  IF NEW.total_automated > 0 THEN
    p := NEW.false_negatives::NUMERIC / NEW.total_automated::NUMERIC;
    n := NEW.total_automated::NUMERIC;
    denominator := 1 + (z * z) / n;
    center := (p + (z * z) / (2 * n)) / denominator;
    margin := z * sqrt(p * (1 - p) / n + (z * z) / (4 * n * n)) / denominator;
    NEW.fnr_upper_bound := LEAST(1.0, center + margin);
    NEW.fnr := p;
  ELSE
    NEW.fnr := 0;
    NEW.fnr_upper_bound := 1.0;
  END IF;
  NEW.confidence_level := 0.95;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_fnr_statistics"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_fnr_statistics"() IS 'Automatically compute FNR and Wilson score upper bound on insert/update';



