CREATE OR REPLACE FUNCTION "public"."update_sync_job_progress"("p_job_id" "uuid", "p_status" "public"."sync_status", "p_total_records" integer DEFAULT NULL::integer, "p_processed_records" integer DEFAULT NULL::integer, "p_successful_records" integer DEFAULT NULL::integer, "p_failed_records" integer DEFAULT NULL::integer, "p_error_details" "jsonb" DEFAULT NULL::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
    UPDATE data_sync_jobs
    SET status = p_status,
        total_records = COALESCE(p_total_records, total_records),
        processed_records = COALESCE(p_processed_records, processed_records),
        successful_records = COALESCE(p_successful_records, successful_records),
        failed_records = COALESCE(p_failed_records, failed_records),
        error_details = COALESCE(p_error_details, error_details),
        completed_at = CASE WHEN p_status IN ('completed', 'failed') THEN NOW() ELSE completed_at END,
        started_at = CASE WHEN p_status = 'in_progress' AND started_at IS NULL THEN NOW() ELSE started_at END
    WHERE id = p_job_id;
END;
$$;


ALTER FUNCTION "public"."update_sync_job_progress"("p_job_id" "uuid", "p_status" "public"."sync_status", "p_total_records" integer, "p_processed_records" integer, "p_successful_records" integer, "p_failed_records" integer, "p_error_details" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_table_statistics"() RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  table_record record;
BEGIN
  FOR table_record IN 
    SELECT table_name 
    FROM information_schema.tables 
    WHERE table_schema = 'public' AND table_type = 'BASE TABLE'
  LOOP
    EXECUTE 'ANALYZE public.' || quote_ident(table_record.table_name);
  END LOOP;
END;
$$;


