CREATE OR REPLACE FUNCTION "public"."validate_job_status_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  -- Only validate when status actually changes
  IF OLD.status = NEW.status THEN
    RETURN NEW;
  END IF;

  -- Define valid transitions
  CASE OLD.status
    WHEN 'draft' THEN
      IF NEW.status NOT IN ('posted', 'cancelled') THEN
        RAISE EXCEPTION 'Invalid job status transition: % -> %', OLD.status, NEW.status;
      END IF;
    WHEN 'open' THEN
      IF NEW.status NOT IN ('posted', 'assigned', 'cancelled') THEN
        RAISE EXCEPTION 'Invalid job status transition: % -> %', OLD.status, NEW.status;
      END IF;
    WHEN 'posted' THEN
      IF NEW.status NOT IN ('assigned', 'cancelled') THEN
        RAISE EXCEPTION 'Invalid job status transition: % -> %', OLD.status, NEW.status;
      END IF;
    WHEN 'assigned' THEN
      IF NEW.status NOT IN ('in_progress', 'cancelled', 'posted') THEN
        RAISE EXCEPTION 'Invalid job status transition: % -> %', OLD.status, NEW.status;
      END IF;
    WHEN 'in_progress' THEN
      IF NEW.status NOT IN ('completed', 'cancelled') THEN
        RAISE EXCEPTION 'Invalid job status transition: % -> %', OLD.status, NEW.status;
      END IF;
    WHEN 'completed' THEN
      -- Completed is a terminal state (except admin override)
      RAISE EXCEPTION 'Cannot transition from completed status';
    WHEN 'cancelled' THEN
      -- Cancelled is a terminal state
      RAISE EXCEPTION 'Cannot transition from cancelled status';
    ELSE
      -- Unknown status — allow (for backward compatibility)
      NULL;
  END CASE;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_job_status_transition"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_job_status_transition"("p_from_status" "text", "p_to_status" "text", "p_user_role" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
DECLARE
  v_is_valid BOOLEAN;
BEGIN
  SELECT EXISTS (
    SELECT 1 FROM job_state_machine_rules
    WHERE from_status = p_from_status
    AND to_status = p_to_status
    AND is_active = TRUE
    AND (required_role IS NULL OR required_role = p_user_role OR p_user_role = 'admin')
  ) INTO v_is_valid;

  RETURN v_is_valid;
END;
$$;


ALTER FUNCTION "public"."validate_job_status_transition"("p_from_status" "text", "p_to_status" "text", "p_user_role" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."validate_job_status_transition"("p_from_status" "text", "p_to_status" "text", "p_user_role" "text") IS 'Validates if a status transition is allowed based on state machine rules';



