CREATE OR REPLACE FUNCTION "public"."validate_refresh_token"("p_token_hash" "text") RETURNS TABLE("is_valid" boolean, "user_id" "uuid", "family_id" "uuid", "generation" integer, "reason" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_token RECORD;
BEGIN
  SELECT rt.user_id, rt.family_id, rt.generation, rt.consumed_at, rt.revoked_at, rt.revoked_reason, rt.expires_at INTO v_token
  FROM public.refresh_tokens rt WHERE rt.token_hash = p_token_hash;
  IF NOT FOUND THEN RETURN QUERY SELECT false, NULL::UUID, NULL::UUID, NULL::INTEGER, 'Token not found'::TEXT; RETURN; END IF;
  IF v_token.consumed_at IS NOT NULL THEN
    PERFORM public.revoke_token_family(v_token.family_id, 'Consumed token reused - breach detected');
    RETURN QUERY SELECT false, v_token.user_id, v_token.family_id, v_token.generation, 'Token already consumed - family revoked'::TEXT; RETURN;
  END IF;
  IF v_token.revoked_at IS NOT NULL THEN
    RETURN QUERY SELECT false, v_token.user_id, v_token.family_id, v_token.generation, ('Token revoked: ' || COALESCE(v_token.revoked_reason, 'No reason'))::TEXT; RETURN;
  END IF;
  IF v_token.expires_at < NOW() THEN
    RETURN QUERY SELECT false, v_token.user_id, v_token.family_id, v_token.generation, 'Token expired'::TEXT; RETURN;
  END IF;
  RETURN QUERY SELECT true, v_token.user_id, v_token.family_id, v_token.generation, 'Token valid'::TEXT;
END;
$$;


ALTER FUNCTION "public"."validate_refresh_token"("p_token_hash" "text") OWNER TO "postgres";


