CREATE OR REPLACE FUNCTION "public"."wilson_score_ci"("successes" integer, "trials" integer, "confidence_level" numeric DEFAULT 0.95) RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  z DECIMAL;
  p DECIMAL;
  denominator DECIMAL;
  center DECIMAL;
  margin DECIMAL;
  upper_bound DECIMAL;
BEGIN
  IF trials = 0 THEN
    RETURN 1.0;
  END IF;
  
  z := CASE 
    WHEN confidence_level = 0.95 THEN 1.96
    WHEN confidence_level = 0.99 THEN 2.576
    ELSE 1.96
  END;
  
  p := successes::DECIMAL / trials;
  denominator := 1 + (z * z) / trials;
  center := (p + (z * z) / (2 * trials)) / denominator;
  margin := z * SQRT((p * (1 - p) / trials + (z * z) / (4 * trials * trials))) / denominator;
  
  upper_bound := LEAST(1.0, center + margin);
  
  RETURN upper_bound;
END;
$$;


ALTER FUNCTION "public"."wilson_score_ci"("successes" integer, "trials" integer, "confidence_level" numeric) OWNER TO "postgres";

