    CONSTRAINT "ab_outcomes_csat_score_check" CHECK ((("csat_score" >= 1) AND ("csat_score" <= 5))),
    CONSTRAINT "ab_outcomes_sfn_severity_check" CHECK (("sfn_severity" = ANY (ARRAY['low'::"text", 'medium'::"text", 'high'::"text", 'critical'::"text"])))
);


