CREATE OR REPLACE VIEW "public"."ab_arm_comparison" WITH ("security_invoker"='on') AS
 SELECT "e"."id" AS "experiment_id",
    "arm"."name" AS "arm_name",
    "count"(DISTINCT "d"."id") AS "decision_count",
    "count"(DISTINCT
        CASE
            WHEN ("d"."decision" = 'automate'::"text") THEN "d"."id"
            ELSE NULL::"uuid"
        END) AS "automated_count",
    "round"(((("count"(DISTINCT
        CASE
            WHEN ("d"."decision" = 'automate'::"text") THEN "d"."id"
            ELSE NULL::"uuid"
        END))::numeric / (NULLIF("count"(DISTINCT "d"."id"), 0))::numeric) * (100)::numeric), 2) AS "automation_rate_percent",
    "count"(DISTINCT "o"."id") AS "outcome_count",
    "count"(DISTINCT
        CASE
            WHEN ("o"."sfn" = true) THEN "o"."id"
            ELSE NULL::"uuid"
        END) AS "sfn_count",
    "round"(((("count"(DISTINCT
        CASE
            WHEN ("o"."sfn" = true) THEN "o"."id"
            ELSE NULL::"uuid"
        END))::numeric / (NULLIF("count"(DISTINCT "o"."id"), 0))::numeric) * (100)::numeric), 4) AS "sfn_rate_percent",
    "avg"("o"."decision_time_seconds") AS "avg_decision_time",
    "avg"("o"."csat_score") AS "avg_csat_score"
   FROM (((("public"."ab_experiments" "e"
     JOIN "public"."ab_arms" "arm" ON (("arm"."experiment_id" = "e"."id")))
     LEFT JOIN "public"."ab_assignments" "a" ON (("a"."arm_id" = "arm"."id")))
     LEFT JOIN "public"."ab_decisions" "d" ON (("d"."assignment_id" = "a"."id")))
     LEFT JOIN "public"."ab_outcomes" "o" ON (("o"."decision_id" = "d"."id")))
  WHERE ("e"."status" = 'active'::"text")
  GROUP BY "e"."id", "arm"."name", "arm"."id";


ALTER VIEW "public"."ab_arm_comparison" OWNER TO "postgres";


