CREATE TABLE IF NOT EXISTS "public"."ab_critic_fnr_tracking" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "stratum" "text" NOT NULL,
    "total_automated" integer DEFAULT 0,
    "false_negatives" integer DEFAULT 0,
    "fnr" numeric(5,4) GENERATED ALWAYS AS (
CASE
    WHEN ("total_automated" > 0) THEN (("false_negatives")::numeric / ("total_automated")::numeric)
    ELSE (0)::numeric
END) STORED,
    "last_updated" timestamp with time zone DEFAULT "now"() NOT NULL,
    "fnr_upper_bound" numeric,
    "confidence_level" numeric DEFAULT 0.95,
    "last_escalation_at" timestamp with time zone,
    "escalation_count" integer DEFAULT 0,
    "updated_at" timestamp with time zone DEFAULT "now"()
);


ALTER TABLE "public"."ab_critic_fnr_tracking" OWNER TO "postgres";


COMMENT ON TABLE "public"."ab_critic_fnr_tracking" IS 'Tracks False Negative Rate (FNR) per stratum for Safe-LUCB critic safety constraint enforcement';



COMMENT ON COLUMN "public"."ab_critic_fnr_tracking"."stratum" IS 'Mondrian stratum identifier (e.g., residential_modern_london_water_damage)';



COMMENT ON COLUMN "public"."ab_critic_fnr_tracking"."total_automated" IS 'Total number of automated decisions for this stratum';



COMMENT ON COLUMN "public"."ab_critic_fnr_tracking"."false_negatives" IS 'Number of false negatives (missed critical hazards) for this stratum';



COMMENT ON COLUMN "public"."ab_critic_fnr_tracking"."fnr" IS 'Computed FNR: false_negatives / total_automated (stored as generated column)';



COMMENT ON COLUMN "public"."ab_critic_fnr_tracking"."fnr_upper_bound" IS 'Wilson score upper bound for FNR at confidence_level';



COMMENT ON COLUMN "public"."ab_critic_fnr_tracking"."confidence_level" IS 'Confidence level for Wilson score interval (typically 0.95)';



COMMENT ON COLUMN "public"."ab_critic_fnr_tracking"."last_escalation_at" IS 'Timestamp of last escalation due to FNR threshold violation';



COMMENT ON COLUMN "public"."ab_critic_fnr_tracking"."escalation_count" IS 'Total number of escalations due to FNR threshold violations';



