CREATE OR REPLACE VIEW "public"."ab_experiment_status" WITH ("security_invoker"='on') AS
 SELECT "e"."id",
    "e"."name",
    "e"."status",
    "e"."start_date",
    "e"."end_date",
    "count"(DISTINCT "a"."id") AS "total_assignments",
    "count"(DISTINCT "d"."id") AS "total_decisions",
    "count"(DISTINCT
        CASE
            WHEN ("d"."decision" = 'automate'::"text") THEN "d"."id"
            ELSE NULL::"uuid"
        END) AS "automated_count",
    "count"(DISTINCT
        CASE
            WHEN ("d"."decision" = 'escalate'::"text") THEN "d"."id"
            ELSE NULL::"uuid"
        END) AS "escalated_count",
    "count"(DISTINCT "o"."id") AS "total_outcomes",
    "count"(DISTINCT
        CASE
            WHEN ("o"."sfn" = true) THEN "o"."id"
            ELSE NULL::"uuid"
        END) AS "sfn_count",
    "round"(((("count"(DISTINCT
        CASE
            WHEN ("o"."sfn" = true) THEN "o"."id"
            ELSE NULL::"uuid"
        END))::numeric / (NULLIF("count"(DISTINCT "o"."id"), 0))::numeric) * (100)::numeric), 4) AS "sfn_rate_percent"
   FROM ((("public"."ab_experiments" "e"
     LEFT JOIN "public"."ab_assignments" "a" ON (("a"."experiment_id" = "e"."id")))
     LEFT JOIN "public"."ab_decisions" "d" ON (("d"."assignment_id" = "a"."id")))
     LEFT JOIN "public"."ab_outcomes" "o" ON (("o"."decision_id" = "d"."id")))
  GROUP BY "e"."id", "e"."name", "e"."status", "e"."start_date", "e"."end_date";


