CREATE TABLE IF NOT EXISTS "public"."bids" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "job_id" "uuid" NOT NULL,
    "contractor_id" "uuid" NOT NULL,
    "amount" numeric(10,2) NOT NULL,
    "description" "text" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "quote_id" "uuid",
    "suggested_price_range" "jsonb",
    "competitiveness_score" integer,
    "pricing_recommendation_id" "uuid",
    "was_price_recommended" boolean DEFAULT false,
    "line_items" "jsonb" DEFAULT '[]'::"jsonb",
    "tax_rate" numeric(5,2) DEFAULT 0,
    "terms" "text",
    "has_itemization" boolean DEFAULT false,
    "itemization_quality_score" integer,
    "materials_breakdown" "jsonb",
    "labor_breakdown" "jsonb",
    "other_costs_breakdown" "jsonb",
    "bid_to_budget_ratio" numeric(5,4),
    "within_typical_range" boolean,
    "expires_at" timestamp with time zone,
    "message" "text",
    "estimated_duration_days" integer,
    "materials_included" boolean DEFAULT true,
    "warranty_months" integer DEFAULT 12,
    "proposed_start_date" "date",
    "rejection_reason" "text",
    CONSTRAINT "bids_amount_positive" CHECK (("amount" > (0)::numeric)),
    CONSTRAINT "bids_amount_positive_check" CHECK (("amount" > (0)::numeric)),
    CONSTRAINT "bids_description_length" CHECK ((("length"("description") >= 10) AND ("length"("description") <= 2000))),
    CONSTRAINT "bids_description_length_check" CHECK ((("length"("description") >= 10) AND ("length"("description") <= 2000))),
    CONSTRAINT "bids_itemization_quality_score_check" CHECK ((("itemization_quality_score" >= 0) AND ("itemization_quality_score" <= 100))),
    CONSTRAINT "bids_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'accepted'::"text", 'rejected'::"text", 'withdrawn'::"text"]))),
    CONSTRAINT "check_quality_score_range" CHECK ((("itemization_quality_score" IS NULL) OR (("itemization_quality_score" >= 0) AND ("itemization_quality_score" <= 100)))),
    CONSTRAINT "valid_tax_rate" CHECK ((("tax_rate" >= (0)::numeric) AND ("tax_rate" <= (100)::numeric)))
);


