    "deleted_at" timestamp with time zone,
    "scheduled_start_date" timestamp with time zone,
    "scheduled_end_date" timestamp with time zone,
    "scheduled_duration_hours" integer,
    "required_skills" "text"[],
    "image_analysis_metadata" "jsonb",
    "serious_buyer_score" integer DEFAULT 0,
    "embedding" "public"."vector"(1536),
    "embedding_updated_at" timestamp with time zone,
    "embedding_model" character varying(50) DEFAULT 'text-embedding-3-small'::character varying,
    "property_id" "uuid",
    "city" character varying(100),
    "postcode" character varying(20),
    "budget_min" numeric(10,2),
    "budget_max" numeric(10,2),
    "requirements" "jsonb" DEFAULT '[]'::"jsonb",
