    "assigned_at" timestamp with time zone,
    "started_at" timestamp with time zone,
    "archived_at" timestamp with time zone,
    CONSTRAINT "check_budget_range" CHECK (((("budget_min" IS NULL) OR ("budget_max" IS NULL) OR ("budget_min" <= "budget_max")) AND (("budget" IS NULL) OR ("budget_min" IS NULL) OR ("budget" >= "budget_min")) AND (("budget" IS NULL) OR ("budget_max" IS NULL) OR ("budget" <= "budget_max")))),
    CONSTRAINT "jobs_budget_positive" CHECK (("budget" > (0)::numeric)),
    CONSTRAINT "jobs_budget_positive_check" CHECK (("budget" > (0)::numeric)),
    CONSTRAINT "jobs_budget_range_check" CHECK ((("budget_min" IS NULL) OR ("budget_max" IS NULL) OR ("budget_min" <= "budget_max"))),
    CONSTRAINT "jobs_description_length" CHECK ((("length"("description") >= 10) AND ("length"("description") <= 5000))),
    CONSTRAINT "jobs_description_length_check" CHECK ((("length"("description") >= 10) AND ("length"("description") <= 5000))),
    CONSTRAINT "jobs_payment_status_check" CHECK (("payment_status" = ANY (ARRAY['pending'::"text", 'paid'::"text", 'refunded'::"text", 'failed'::"text", 'canceled'::"text"]))),
    CONSTRAINT "jobs_priority_check" CHECK (("priority" = ANY (ARRAY['low'::"text", 'medium'::"text", 'high'::"text"]))),
    CONSTRAINT "jobs_serious_buyer_score_check" CHECK ((("serious_buyer_score" >= 0) AND ("serious_buyer_score" <= 100))),
    CONSTRAINT "jobs_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'open'::"text", 'posted'::"text", 'assigned'::"text", 'in_progress'::"text", 'completed'::"text", 'disputed'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "jobs_title_length" CHECK ((("length"("title") >= 5) AND ("length"("title") <= 200))),
    CONSTRAINT "jobs_title_length_check" CHECK ((("length"("title") >= 5) AND ("length"("title") <= 200))),
    CONSTRAINT "jobs_urgency_check" CHECK ((("urgency")::"text" = ANY ((ARRAY['low'::character varying, 'medium'::character varying, 'high'::character varying, 'emergency'::character varying])::"text"[])))
)
WITH ("autovacuum_vacuum_scale_factor"='0.1', "autovacuum_analyze_scale_factor"='0.05');


ALTER TABLE "public"."jobs" OWNER TO "postgres";


COMMENT ON TABLE "public"."jobs" IS 'Lifecycle table. authenticated has DELETE/INSERT at table level + UPDATE on 14 editorial columns (20260523000006). anon read-only (20260523000008). State-machine columns (status, contractor_id, payment_status, completion_confirmed_by_homeowner, completed_at) write-gated to service_role only.';



COMMENT ON COLUMN "public"."jobs"."payment_status" IS 'Payment status for the job: pending, paid, refunded, failed, canceled';



COMMENT ON COLUMN "public"."jobs"."scheduled_start_date" IS 'Scheduled start date/time for the job - appears on both contractor and homeowner calendars';



COMMENT ON COLUMN "public"."jobs"."scheduled_end_date" IS 'Scheduled end date/time for the job';



COMMENT ON COLUMN "public"."jobs"."scheduled_duration_hours" IS 'Estimated duration of the job in hours';



COMMENT ON COLUMN "public"."jobs"."required_skills" IS 'Array of required contractor skills for this job. Used for matching jobs to contractors with matching skills.';



COMMENT ON COLUMN "public"."jobs"."image_analysis_metadata" IS 'Stores Google Vision API analysis results including labels, objects, detected features, property type, condition, complexity, and suggested categories. Used for caching analysis results to reduce API calls and improve recommendations.';



COMMENT ON COLUMN "public"."jobs"."serious_buyer_score" IS 'Score from 0-100 indicating how serious the buyer is (phone verified, previous jobs, budget, etc.)';



COMMENT ON COLUMN "public"."jobs"."embedding" IS 'Vector embedding of job title + description + category for semantic search using OpenAI text-embedding-3-small (1536 dimensions)';



COMMENT ON COLUMN "public"."jobs"."embedding_updated_at" IS 'Timestamp when embedding was last generated';



COMMENT ON COLUMN "public"."jobs"."embedding_model" IS 'OpenAI model used to generate the embedding';



COMMENT ON COLUMN "public"."jobs"."property_id" IS 'Foreign key linking job to a specific property';



COMMENT ON COLUMN "public"."jobs"."budget_min" IS 'Minimum budget shown to contractors (creates range)';



COMMENT ON COLUMN "public"."jobs"."budget_max" IS 'Maximum budget shown to contractors (creates range)';



COMMENT ON COLUMN "public"."jobs"."completion_confirmed_by_homeowner" IS 'Boolean flag indicating homeowner has inspected and confirmed job completion.
   Protected by RLS policy - only homeowner can set to true.
   Once true, cannot be reverted to false (one-way transition).';



COMMENT ON COLUMN "public"."jobs"."show_budget_to_contractors" IS 'Whether to show exact budget to contractors (default: false for blind bidding)';



COMMENT ON COLUMN "public"."jobs"."require_itemized_bids" IS 'Whether contractors must provide itemized cost breakdown (default: true for jobs > £500)';



COMMENT ON COLUMN "public"."jobs"."completion_confirmed_at" IS 'Timestamp when the homeowner approved the contractor-completed work. Paired with completion_confirmed_by_homeowner=true. Distinct from completed_at, which records the contractor declaration.';



COMMENT ON COLUMN "public"."jobs"."assigned_at" IS 'Stamped by accept_bid_atomic when the winning bid is accepted. Drives time-to-assign analytics and the contractor SLA window. Nullable to remain backwards compatible with pre-2026-05-27 rows.';



COMMENT ON COLUMN "public"."jobs"."started_at" IS 'Stamped by POST /api/jobs/:id/start when before-photos are confirmed and the contractor begins work. Drives time-to-completion and on-site-duration analytics. Nullable for legacy rows.';



COMMENT ON COLUMN "public"."jobs"."archived_at" IS 'When the homeowner archived this job from their list views. NULL = not archived. Orthogonal to status — archiving does not change the job lifecycle.';



CREATE OR REPLACE VIEW "public"."budget_anchoring_analytics" WITH ("security_invoker"='on') AS
 SELECT "j"."category",
    "j"."show_budget_to_contractors",
    "count"("b"."id") AS "total_bids",
    "avg"("b"."bid_to_budget_ratio") AS "avg_bid_to_budget_ratio",
    "percentile_cont"((0.5)::double precision) WITHIN GROUP (ORDER BY (("b"."bid_to_budget_ratio")::double precision)) AS "median_bid_to_budget_ratio",
    "count"(
        CASE
            WHEN ("b"."bid_to_budget_ratio" > 0.95) THEN 1
            ELSE NULL::integer
        END) AS "bids_near_budget_count",
    "count"(
        CASE
            WHEN "b"."has_itemization" THEN 1
            ELSE NULL::integer
        END) AS "itemized_bids_count",
    "avg"(
        CASE
            WHEN "b"."has_itemization" THEN "b"."itemization_quality_score"
            ELSE NULL::integer
        END) AS "avg_itemization_quality"
   FROM ("public"."jobs" "j"
     LEFT JOIN "public"."bids" "b" ON (("j"."id" = "b"."job_id")))
  WHERE ("j"."created_at" > ("now"() - '6 mons'::interval))
  GROUP BY "j"."category", "j"."show_budget_to_contractors";


ALTER VIEW "public"."budget_anchoring_analytics" OWNER TO "postgres";


COMMENT ON VIEW "public"."budget_anchoring_analytics" IS 'Analytics view for A/B testing budget visibility impact';



