    CONSTRAINT "building_assessment_outcomes_outcome_type_check" CHECK ((("outcome_type")::"text" = ANY ((ARRAY['validation'::character varying, 'repair'::character varying, 'progression'::character varying, 'contractor_feedback'::character varying])::"text"[])))
);


