CREATE TABLE IF NOT EXISTS "public"."building_assessments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid",
    "cache_key" character varying(64),
    "damage_type" character varying(100) NOT NULL,
    "severity" character varying(20) NOT NULL,
    "confidence" integer NOT NULL,
    "safety_score" integer NOT NULL,
    "compliance_score" integer NOT NULL,
    "insurance_risk_score" integer NOT NULL,
    "urgency" character varying(20) NOT NULL,
    "assessment_data" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "validation_status" character varying(20) DEFAULT 'pending'::character varying NOT NULL,
    "validated_by" "uuid",
    "validated_at" timestamp with time zone,
    "validation_notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "auto_validated" boolean DEFAULT false NOT NULL,
    "auto_validated_at" timestamp with time zone,
    "auto_validation_reason" "text",
    "auto_validation_confidence" integer,
    "auto_validation_review_status" character varying(20) DEFAULT 'not_applicable'::character varying NOT NULL,
    "shadow_mode" boolean DEFAULT false NOT NULL,
    "predicted_class" character varying(100),
    "predicted_severity" character varying(20),
    "raw_probability" numeric(5,4),
    "fusion_variance" numeric(5,4),
    "context_features" "jsonb",
    "sam3_evidence" "jsonb",
    "gpt4_assessment" "jsonb",
    "scene_graph_features" "jsonb",
    "true_class" character varying(100),
    "critical_hazard" boolean,
    "job_id" "uuid",
    "damage_taxonomy_id" "uuid",
    "domain" "text" DEFAULT 'building'::"text",
    "material" "text",
    "property_id" "uuid",
    "damage_type_canonical" "text",
    "recommended_trades" "text"[],
    "location" "public"."geography"(Point,4326),
    "room_metadata" "jsonb",
    "latitude" double precision,
    "longitude" double precision,
    "video_url" "text",
    "room_id" "uuid",
    CONSTRAINT "building_assessments_auto_validation_confidence_check" CHECK ((("auto_validation_confidence" IS NULL) OR (("auto_validation_confidence" >= 0) AND ("auto_validation_confidence" <= 100)))),
    CONSTRAINT "building_assessments_auto_validation_review_status_check" CHECK ((("auto_validation_review_status")::"text" = ANY ((ARRAY['not_applicable'::character varying, 'pending_review'::character varying, 'confirmed'::character varying, 'overturned'::character varying])::"text"[]))),
    CONSTRAINT "building_assessments_compliance_score_check" CHECK ((("compliance_score" >= 0) AND ("compliance_score" <= 100))),
    CONSTRAINT "building_assessments_confidence_check" CHECK ((("confidence" >= 0) AND ("confidence" <= 100))),
    CONSTRAINT "building_assessments_damage_type_canonical_check" CHECK ((("damage_type_canonical" IS NULL) OR ("damage_type_canonical" = ANY (ARRAY['pipe_leak'::"text", 'water_damage'::"text", 'wall_crack'::"text", 'roof_damage'::"text", 'electrical_fault'::"text", 'mold_damp'::"text", 'fire_damage'::"text", 'window_broken'::"text", 'door_damaged'::"text", 'floor_damage'::"text", 'ceiling_damage'::"text", 'foundation_crack'::"text", 'hvac_issue'::"text", 'gutter_blocked'::"text", 'general_damage'::"text", 'none'::"text"])))),
    CONSTRAINT "building_assessments_insurance_risk_score_check" CHECK ((("insurance_risk_score" >= 0) AND ("insurance_risk_score" <= 100))),
    CONSTRAINT "building_assessments_safety_score_check" CHECK ((("safety_score" >= 0) AND ("safety_score" <= 100))),
    CONSTRAINT "building_assessments_severity_check" CHECK ((("severity")::"text" = ANY ((ARRAY['early'::character varying, 'developing'::character varying, 'significant'::character varying, 'dangerous'::character varying])::"text"[]))),
    CONSTRAINT "building_assessments_urgency_check" CHECK ((("urgency")::"text" = ANY (ARRAY['immediate'::"text", 'urgent'::"text", 'soon'::"text", 'planned'::"text", 'monitor'::"text", 'needs_attention'::"text", 'emergency'::"text"]))),
    CONSTRAINT "building_assessments_validation_status_check" CHECK ((("validation_status")::"text" = ANY (ARRAY['pending'::"text", 'validated'::"text", 'rejected'::"text", 'needs_review'::"text", 'processing'::"text", 'completed'::"text", 'failed'::"text", 'ai_analysis_failed'::"text", 'ai_analysis_skipped_no_auth'::"text"]))),
    CONSTRAINT "check_user_id_when_not_shadow_mode" CHECK (((("shadow_mode" = true) AND ("user_id" IS NULL)) OR (("shadow_mode" = false) AND ("user_id" IS NOT NULL))))
);


ALTER TABLE "public"."building_assessments" OWNER TO "postgres";


COMMENT ON TABLE "public"."building_assessments" IS 'Stores AI building damage assessments from GPT-4 Vision';



COMMENT ON COLUMN "public"."building_assessments"."cache_key" IS 'SHA256 hash of image URLs for caching duplicate assessments';



COMMENT ON COLUMN "public"."building_assessments"."severity" IS 'Damage severity: early (cosmetic/minor), developing (progressing, needs attention), significant (serious, risk of spread), dangerous (structural/safety risk, urgent repair)';



COMMENT ON COLUMN "public"."building_assessments"."assessment_data" IS 'Complete Phase1BuildingAssessment JSON structure';



COMMENT ON COLUMN "public"."building_assessments"."validation_status" IS 'Status in human validation workflow for training data';



COMMENT ON COLUMN "public"."building_assessments"."auto_validated" IS 'Indicates whether the assessment was auto-validated by the system';



COMMENT ON COLUMN "public"."building_assessments"."auto_validated_at" IS 'Timestamp when auto-validation was applied';



COMMENT ON COLUMN "public"."building_assessments"."auto_validation_reason" IS 'Reason captured when auto-validation was approved';



COMMENT ON COLUMN "public"."building_assessments"."auto_validation_confidence" IS 'Assessment confidence at the time of auto-validation (0-100)';



COMMENT ON COLUMN "public"."building_assessments"."auto_validation_review_status" IS 'Lifecycle state of auto-validation review (pending_review, confirmed, overturned)';



COMMENT ON COLUMN "public"."building_assessments"."shadow_mode" IS 'Indicates this assessment was run in shadow mode for training (predictions stored but not used for automation)';



COMMENT ON COLUMN "public"."building_assessments"."predicted_class" IS 'AI predicted damage class (from shadow mode execution)';



COMMENT ON COLUMN "public"."building_assessments"."raw_probability" IS 'Fusion mean from Bayesian Fusion (raw probability score)';



COMMENT ON COLUMN "public"."building_assessments"."fusion_variance" IS 'Fusion variance from Bayesian Fusion (uncertainty measure)';



COMMENT ON COLUMN "public"."building_assessments"."context_features" IS '12-dimensional context vector used by Safe-LUCB Critic';



COMMENT ON COLUMN "public"."building_assessments"."sam3_evidence" IS 'SAM 3 segmentation evidence stored for training';



COMMENT ON COLUMN "public"."building_assessments"."gpt4_assessment" IS 'GPT-4 assessment data stored for training';



COMMENT ON COLUMN "public"."building_assessments"."scene_graph_features" IS 'Scene graph features stored for training';



COMMENT ON COLUMN "public"."building_assessments"."true_class" IS 'Ground truth class label (from building_surveyor_feedback)';



COMMENT ON COLUMN "public"."building_assessments"."critical_hazard" IS 'Ground truth critical hazard flag (from building_surveyor_feedback)';



COMMENT ON COLUMN "public"."building_assessments"."job_id" IS 'Links assessment to specific job (nullable for cache-only assessments)';



COMMENT ON COLUMN "public"."building_assessments"."property_id" IS 'Links assessment to property for past-assessments RAG (Phase 5)';



COMMENT ON COLUMN "public"."building_assessments"."damage_type_canonical" IS 'Normalized damage type from 15 canonical categories. See damage-type-mapping.ts';



COMMENT ON COLUMN "public"."building_assessments"."recommended_trades" IS 'Recommended contractor trades for this damage type (plumber, electrician, roofer, etc.)';



COMMENT ON COLUMN "public"."building_assessments"."location" IS 'GPS point (EPSG:4326) for spatial queries';



COMMENT ON COLUMN "public"."building_assessments"."room_metadata" IS 'Room context: { room, floor, dimensions, orientation }';



COMMENT ON COLUMN "public"."building_assessments"."latitude" IS 'Denormalized latitude for easy export';



COMMENT ON COLUMN "public"."building_assessments"."longitude" IS 'Denormalized longitude for easy export';



COMMENT ON COLUMN "public"."building_assessments"."video_url" IS 'Signed Job-storage URL of the assessment walkthrough video. Written by POST /api/assessments/videos/upload.';



COMMENT ON CONSTRAINT "check_user_id_when_not_shadow_mode" ON "public"."building_assessments" IS 'Ensures user_id is NULL for shadow mode assessments and NOT NULL for regular assessments';



CREATE TABLE IF NOT EXISTS "public"."building_pathology_knowledge" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "defect_slug" "text" NOT NULL,
    "category" "text" NOT NULL,
    "name" "text" NOT NULL,
    "aka" "text"[] DEFAULT '{}'::"text"[],
    "description" "text" NOT NULL,
    "why_it_happens" "text" NOT NULL,
    "visual_indicators" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "photo_detection_cues" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "common_misdiagnosis" "text"[] DEFAULT '{}'::"text"[],
    "differential_diagnosis" "text",
    "rics_condition_rating" smallint,
    "urgency" "text" NOT NULL,
    "remediation_summary" "text" NOT NULL,
    "remediation_steps" "text"[] DEFAULT '{}'::"text"[],
    "cost_range_gbp_min" integer,
    "cost_range_gbp_max" integer,
    "regulatory_reference" "text"[],
    "property_age_risk" "text"[],
    "construction_type_risk" "text"[],
    "specialist_required" boolean DEFAULT false,
    "further_investigation" "text",
    "source_authority" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "fts" "tsvector" GENERATED ALWAYS AS ("to_tsvector"('"english"'::"regconfig", ((((((((COALESCE("name", ''::"text") || ' '::"text") || COALESCE("description", ''::"text")) || ' '::"text") || COALESCE("why_it_happens", ''::"text")) || ' '::"text") || COALESCE("public"."immutable_array_to_text"("visual_indicators", ' '::"text"), ''::"text")) || ' '::"text") || COALESCE("public"."immutable_array_to_text"("photo_detection_cues", ' '::"text"), ''::"text")))) STORED,
    "embedding" "public"."vector"(1536),
    "embedding_updated_at" timestamp with time zone,
    CONSTRAINT "building_pathology_knowledge_rics_condition_rating_check" CHECK (("rics_condition_rating" = ANY (ARRAY[1, 2, 3]))),
    CONSTRAINT "building_pathology_knowledge_urgency_check" CHECK (("urgency" = ANY (ARRAY['routine'::"text", 'soon'::"text", 'urgent'::"text", 'immediate'::"text"])))
);


