CREATE TABLE IF NOT EXISTS "public"."compliance_certificates" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "property_id" "uuid",
    "owner_id" "uuid",
    "cert_type" "text" NOT NULL,
    "certificate_number" "text",
    "issued_date" "date",
    "expiry_date" "date",
    "issuer_name" "text",
    "issuer_registration" "text",
    "document_url" "text",
    "document_storage_path" "text",
    "status" "text" DEFAULT 'valid'::"text" NOT NULL,
    "reminder_90d_sent" boolean DEFAULT false NOT NULL,
    "reminder_30d_sent" boolean DEFAULT false NOT NULL,
    "reminder_7d_sent" boolean DEFAULT false NOT NULL,
    "renewal_job_id" "uuid",
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_reminder_sent_at" timestamp with time zone,
    "last_reminder_days" integer,
    "property_room_id" "uuid",
    CONSTRAINT "compliance_certificates_cert_type_check" CHECK (("cert_type" = ANY (ARRAY['gas_safety'::"text", 'eicr'::"text", 'epc'::"text", 'smoke_alarm'::"text", 'co_detector'::"text", 'legionella'::"text", 'fire_safety'::"text", 'asbestos'::"text", 'pat_testing'::"text"]))),
    CONSTRAINT "compliance_certificates_status_check" CHECK (("status" = ANY (ARRAY['valid'::"text", 'expiring'::"text", 'expired'::"text", 'missing'::"text"])))
);


ALTER TABLE "public"."compliance_certificates" OWNER TO "postgres";


COMMENT ON COLUMN "public"."compliance_certificates"."owner_id" IS 'Homeowner / landlord who commissioned the certificate. Goes NULL when the user deletes their account so the certificate itself survives the GDPR-mandated 2yr (gas) / 5yr (EICR) retention window. Application code requires this on INSERT.';



COMMENT ON COLUMN "public"."compliance_certificates"."last_reminder_sent_at" IS 'When the last expiry reminder was sent';



COMMENT ON COLUMN "public"."compliance_certificates"."last_reminder_days" IS 'The threshold (90/30/7) of the last reminder sent, to avoid duplicates';



COMMENT ON COLUMN "public"."compliance_certificates"."property_room_id" IS 'Optional FK to property_rooms. When set, the certificate covers just that specific room (e.g. EICR for kitchen sub-circuit, gas safety for the utility room boiler). NULL means whole-property scope. ON DELETE SET NULL so room deletion preserves the cert.';



