CREATE OR REPLACE VIEW "public"."contractor_feedback_summary" WITH ("security_invoker"='on') AS
 SELECT "issue_type",
    "count"(*) AS "total_cases",
    "count"(
        CASE
            WHEN ("contractor_found_helpful" = true) THEN 1
            ELSE NULL::integer
        END) AS "helpful_cases",
    "round"(("avg"(
        CASE
            WHEN ("contractor_found_helpful" = true) THEN 1
            ELSE 0
        END) * (100)::numeric), 2) AS "helpful_rate",
    "avg"("actual_time_hours") AS "avg_actual_hours",
    "array_agg"(DISTINCT "actual_issue") FILTER (WHERE (("actual_issue")::"text" <> ("issue_type")::"text")) AS "misclassifications",
    "count"("contractor_notes") AS "notes_count"
   FROM "public"."maintenance_assessments" "ma"
  WHERE ("contractor_found_helpful" IS NOT NULL)
  GROUP BY "issue_type"
  ORDER BY ("count"(*)) DESC;


