CREATE OR REPLACE VIEW "public"."contractor_job_interactions" WITH ("security_invoker"='on') AS
 SELECT "j"."id" AS "job_id",
    "j"."title",
    "j"."description",
    "j"."budget",
    "j"."status",
    "j"."homeowner_id",
    "j"."location",
    "j"."category",
    "j"."priority",
    "j"."created_at" AS "job_created_at",
    "jv"."viewer_id" AS "contractor_id",
    "jv"."viewed_at" AS "first_viewed_at",
    COALESCE("jv"."last_viewed_at", "jv"."viewed_at") AS "last_viewed_at",
    COALESCE("jv"."view_count", 1) AS "view_count",
    "sj"."saved_at",
    "b"."id" AS "bid_id",
    "b"."amount" AS "bid_amount",
    "b"."status" AS "bid_status",
    "b"."created_at" AS "bid_created_at"
   FROM ((("public"."jobs" "j"
     LEFT JOIN "public"."job_views" "jv" ON (("j"."id" = "jv"."job_id")))
     LEFT JOIN "public"."saved_jobs" "sj" ON ((("j"."id" = "sj"."job_id") AND ("jv"."viewer_id" = "sj"."user_id"))))
     LEFT JOIN "public"."bids" "b" ON ((("j"."id" = "b"."job_id") AND ("jv"."viewer_id" = "b"."contractor_id"))));


ALTER VIEW "public"."contractor_job_interactions" OWNER TO "postgres";


COMMENT ON VIEW "public"."contractor_job_interactions" IS 'Comprehensive view of contractor interactions with jobs (views, saves, bids)';



