CREATE TABLE IF NOT EXISTS "public"."contractor_profile_boosts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "contractor_id" "uuid" NOT NULL,
    "base_trust_score" numeric(3,2) DEFAULT 0.50,
    "dbs_check_boost" integer DEFAULT 0,
    "admin_verified_boost" integer DEFAULT 0,
    "phone_verified_boost" integer DEFAULT 0,
    "email_verified_boost" integer DEFAULT 0,
    "personality_assessment_boost" integer DEFAULT 0,
    "portfolio_completeness_boost" integer DEFAULT 0,
    "certifications_boost" integer DEFAULT 0,
    "insurance_verified_boost" integer DEFAULT 0,
    "total_boost_percentage" integer GENERATED ALWAYS AS (((((((("dbs_check_boost" + "admin_verified_boost") + "phone_verified_boost") + "email_verified_boost") + "personality_assessment_boost") + "portfolio_completeness_boost") + "certifications_boost") + "insurance_verified_boost")) STORED,
    "ranking_score" integer GENERATED ALWAYS AS (LEAST((100)::numeric, "round"(((((((((("base_trust_score" * (50)::numeric) + ("dbs_check_boost")::numeric) + ("admin_verified_boost")::numeric) + ("phone_verified_boost")::numeric) + ("email_verified_boost")::numeric) + ("personality_assessment_boost")::numeric) + ("portfolio_completeness_boost")::numeric) + ("certifications_boost")::numeric) + ("insurance_verified_boost")::numeric)))) STORED,
    "tier" character varying(20) GENERATED ALWAYS AS (
CASE
    WHEN ("round"(((((((((("base_trust_score" * (50)::numeric) + ("dbs_check_boost")::numeric) + ("admin_verified_boost")::numeric) + ("phone_verified_boost")::numeric) + ("email_verified_boost")::numeric) + ("personality_assessment_boost")::numeric) + ("portfolio_completeness_boost")::numeric) + ("certifications_boost")::numeric) + ("insurance_verified_boost")::numeric)) >= (80)::numeric) THEN 'elite'::"text"
    WHEN ("round"(((((((((("base_trust_score" * (50)::numeric) + ("dbs_check_boost")::numeric) + ("admin_verified_boost")::numeric) + ("phone_verified_boost")::numeric) + ("email_verified_boost")::numeric) + ("personality_assessment_boost")::numeric) + ("portfolio_completeness_boost")::numeric) + ("certifications_boost")::numeric) + ("insurance_verified_boost")::numeric)) >= (60)::numeric) THEN 'premium'::"text"
    WHEN ("round"(((((((((("base_trust_score" * (50)::numeric) + ("dbs_check_boost")::numeric) + ("admin_verified_boost")::numeric) + ("phone_verified_boost")::numeric) + ("email_verified_boost")::numeric) + ("personality_assessment_boost")::numeric) + ("portfolio_completeness_boost")::numeric) + ("certifications_boost")::numeric) + ("insurance_verified_boost")::numeric)) >= (40)::numeric) THEN 'verified'::"text"
    ELSE 'standard'::"text"
END) STORED,
    "last_calculated_at" timestamp with time zone DEFAULT "now"(),
    "calculation_details" "jsonb",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    CONSTRAINT "contractor_profile_boosts_admin_verified_boost_check" CHECK ((("admin_verified_boost" >= 0) AND ("admin_verified_boost" <= 15))),
    CONSTRAINT "contractor_profile_boosts_base_trust_score_check" CHECK ((("base_trust_score" >= (0)::numeric) AND ("base_trust_score" <= (1)::numeric))),
    CONSTRAINT "contractor_profile_boosts_certifications_boost_check" CHECK ((("certifications_boost" >= 0) AND ("certifications_boost" <= 10))),
    CONSTRAINT "contractor_profile_boosts_dbs_check_boost_check" CHECK ((("dbs_check_boost" >= 0) AND ("dbs_check_boost" <= 25))),
    CONSTRAINT "contractor_profile_boosts_email_verified_boost_check" CHECK ((("email_verified_boost" >= 0) AND ("email_verified_boost" <= 5))),
    CONSTRAINT "contractor_profile_boosts_insurance_verified_boost_check" CHECK ((("insurance_verified_boost" >= 0) AND ("insurance_verified_boost" <= 10))),
    CONSTRAINT "contractor_profile_boosts_personality_assessment_boost_check" CHECK ((("personality_assessment_boost" >= 0) AND ("personality_assessment_boost" <= 15))),
    CONSTRAINT "contractor_profile_boosts_phone_verified_boost_check" CHECK ((("phone_verified_boost" >= 0) AND ("phone_verified_boost" <= 5))),
    CONSTRAINT "contractor_profile_boosts_portfolio_completeness_boost_check" CHECK ((("portfolio_completeness_boost" >= 0) AND ("portfolio_completeness_boost" <= 10)))
);


