CREATE OR REPLACE VIEW "public"."contractor_schedule_overview" WITH ("security_invoker"='on') AS
 SELECT "contractor_id",
    "appointment_date",
    "count"(*) AS "total_appointments",
    "sum"(
        CASE
            WHEN (("status")::"text" = 'completed'::"text") THEN 1
            ELSE 0
        END) AS "completed",
    "sum"(
        CASE
            WHEN (("status")::"text" = 'cancelled'::"text") THEN 1
            ELSE 0
        END) AS "cancelled",
    "sum"("duration_minutes") AS "total_minutes"
   FROM "public"."appointments" "a"
  WHERE (("status")::"text" <> ALL ((ARRAY['cancelled'::character varying, 'no_show'::character varying])::"text"[]))
  GROUP BY "contractor_id", "appointment_date";


