COMMENT ON COLUMN "public"."profiles"."tokens_revoked_at" IS 'When set, every access JWT issued before this timestamp is invalid. Bumped on logout, password reset, and admin-driven revocation. Compared against JWT iat (in milliseconds) inside verifyToken().';



COMMENT ON COLUMN "public"."profiles"."totp_secret" IS 'AES-256-GCM encrypted JSON blob (see lib/mfa encryptField). Server-role access only — no client grants, ever.';



COMMENT ON COLUMN "public"."profiles"."background_check_result" IS 'Structured provider result (criminal records, employment, licenses). Server-role only — never grant to clients.';



COMMENT ON COLUMN "public"."profiles"."date_of_birth_encrypted" IS 'AES-256-GCM EncryptedField envelope of the user''s date of birth. Special-category-adjacent PII: never log, never expose to authenticated clients (service-role read + decrypt only).';



CREATE MATERIALIZED VIEW "public"."dashboard_stats" AS
 SELECT 'active_jobs'::"text" AS "metric",
    "count"(*) AS "value",
    CURRENT_DATE AS "date"
   FROM "public"."jobs"
  WHERE ("jobs"."status" = ANY (ARRAY['posted'::"text", 'assigned'::"text", 'in_progress'::"text"]))
UNION ALL
 SELECT 'completed_jobs'::"text" AS "metric",
    "count"(*) AS "value",
    CURRENT_DATE AS "date"
   FROM "public"."jobs"
  WHERE (("jobs"."status" = 'completed'::"text") AND ("jobs"."created_at" >= (CURRENT_DATE - '30 days'::interval)))
UNION ALL
 SELECT 'active_contractors'::"text" AS "metric",
    "count"(*) AS "value",
    CURRENT_DATE AS "date"
   FROM "public"."profiles"
  WHERE (("profiles"."role" = 'contractor'::"text") AND ("profiles"."is_available" = true))
UNION ALL
 SELECT 'total_revenue'::"text" AS "metric",
    COALESCE("sum"("escrow_transactions"."amount"), (0)::numeric) AS "value",
    CURRENT_DATE AS "date"
   FROM "public"."escrow_transactions"
  WHERE (("escrow_transactions"."status" = 'completed'::"text") AND ("escrow_transactions"."created_at" >= (CURRENT_DATE - '30 days'::interval)))
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."dashboard_stats" OWNER TO "postgres";


