CREATE OR REPLACE VIEW "public"."database_index_usage" WITH ("security_invoker"='on') AS
 SELECT "schemaname",
    "relname" AS "tablename",
    "indexrelname" AS "indexname",
    "idx_scan" AS "index_scans",
    "idx_tup_read" AS "tuples_read",
    "idx_tup_fetch" AS "tuples_fetched",
        CASE
            WHEN ("idx_scan" = 0) THEN 'UNUSED'::"text"
            WHEN ("idx_scan" < 100) THEN 'RARELY USED'::"text"
            WHEN ("idx_scan" < 1000) THEN 'OCCASIONALLY USED'::"text"
            ELSE 'FREQUENTLY USED'::"text"
        END AS "usage_category"
   FROM "pg_stat_user_indexes"
  WHERE ("schemaname" = 'public'::"name")
  ORDER BY "idx_scan" DESC;


ALTER VIEW "public"."database_index_usage" OWNER TO "postgres";


COMMENT ON VIEW "public"."database_index_usage" IS 'Index usage statistics to identify unused or underutilized indexes';



CREATE OR REPLACE VIEW "public"."database_slow_queries" WITH ("security_invoker"='on') AS
 SELECT "substring"("query", 1, 100) AS "query_preview",
    "calls",
    "round"(("mean_exec_time")::numeric, 2) AS "avg_time_ms",
    "round"(("max_exec_time")::numeric, 2) AS "max_time_ms",
    "round"(("total_exec_time")::numeric, 2) AS "total_time_ms",
    "round"(((((100.0)::double precision * "total_exec_time") / "sum"("total_exec_time") OVER ()))::numeric, 2) AS "percent_total_time"
   FROM "extensions"."pg_stat_statements"
  WHERE ("mean_exec_time" > (100)::double precision)
  ORDER BY "mean_exec_time" DESC
 LIMIT 20;


ALTER VIEW "public"."database_slow_queries" OWNER TO "postgres";


COMMENT ON VIEW "public"."database_slow_queries" IS 'Top 20 slowest queries for performance monitoring';



CREATE OR REPLACE VIEW "public"."database_table_stats" WITH ("security_invoker"='on') AS
 SELECT "schemaname",
    "tablename",
    "pg_size_pretty"("pg_total_relation_size"((((("schemaname")::"text" || '.'::"text") || ("tablename")::"text"))::"regclass")) AS "total_size",
    "pg_size_pretty"("pg_relation_size"((((("schemaname")::"text" || '.'::"text") || ("tablename")::"text"))::"regclass")) AS "table_size",
    "pg_size_pretty"(("pg_total_relation_size"((((("schemaname")::"text" || '.'::"text") || ("tablename")::"text"))::"regclass") - "pg_relation_size"((((("schemaname")::"text" || '.'::"text") || ("tablename")::"text"))::"regclass"))) AS "indexes_size",
    "round"((((("pg_total_relation_size"((((("schemaname")::"text" || '.'::"text") || ("tablename")::"text"))::"regclass") - "pg_relation_size"((((("schemaname")::"text" || '.'::"text") || ("tablename")::"text"))::"regclass")))::numeric * (100)::numeric) / NULLIF(("pg_total_relation_size"((((("schemaname")::"text" || '.'::"text") || ("tablename")::"text"))::"regclass"))::numeric, (0)::numeric)), 2) AS "index_ratio_percent"
   FROM "pg_tables"
  WHERE ("schemaname" = 'public'::"name")
  ORDER BY ("pg_total_relation_size"((((("schemaname")::"text" || '.'::"text") || ("tablename")::"text"))::"regclass")) DESC;


ALTER VIEW "public"."database_table_stats" OWNER TO "postgres";


COMMENT ON VIEW "public"."database_table_stats" IS 'Table size and index statistics for storage monitoring';



