CREATE OR REPLACE VIEW "public"."failed_login_attempts" WITH ("security_invoker"='on') AS
 SELECT "ip_address",
    "user_agent",
    "count"(*) AS "attempt_count",
    "min"("created_at") AS "first_attempt",
    "max"("created_at") AS "last_attempt"
   FROM "public"."security_events"
  WHERE (("event_type" = 'auth_failure'::"text") AND ("created_at" >= ("now"() - '24:00:00'::interval)))
  GROUP BY "ip_address", "user_agent"
 HAVING ("count"(*) >= 3)
