CREATE OR REPLACE VIEW "public"."feature_flag_stats" WITH ("security_invoker"='on') AS
 SELECT "f"."name",
    "f"."enabled",
    "f"."rollout_percentage",
    "count"(DISTINCT
        CASE
            WHEN "l"."is_new_controller" THEN "l"."user_id"
            ELSE NULL::"uuid"
        END) AS "users_with_new",
    "count"(DISTINCT
        CASE
            WHEN (NOT "l"."is_new_controller") THEN "l"."user_id"
            ELSE NULL::"uuid"
        END) AS "users_with_old",
    "count"(
        CASE
            WHEN "l"."is_new_controller" THEN 1
            ELSE NULL::integer
        END) AS "new_controller_calls",
    "count"(
        CASE
            WHEN (NOT "l"."is_new_controller") THEN 1
            ELSE NULL::integer
        END) AS "old_controller_calls",
    "max"("l"."logged_at") AS "last_used_at"
   FROM ("public"."feature_flags" "f"
     LEFT JOIN "public"."controller_usage_logs" "l" ON ((("f"."name")::"text" = "concat"('new-', "l"."module", '-controller'))))
  WHERE ("l"."logged_at" > ("now"() - '24:00:00'::interval))
  GROUP BY "f"."name", "f"."enabled", "f"."rollout_percentage";


