CREATE OR REPLACE VIEW "public"."maintenance_daily_stats" WITH ("security_invoker"='on') AS
 SELECT "date"("created_at") AS "date",
    "count"(*) AS "total_assessments",
    "count"(DISTINCT "user_id") AS "unique_users",
    "count"(DISTINCT "job_id") AS "unique_jobs",
    "avg"("confidence") AS "avg_confidence",
    "count"(
        CASE
            WHEN ("contractor_found_helpful" = true) THEN 1
            ELSE NULL::integer
        END) AS "helpful_count",
    "count"(
        CASE
            WHEN ("contractor_found_helpful" IS NOT NULL) THEN 1
            ELSE NULL::integer
        END) AS "feedback_count",
    "round"(("avg"(
        CASE
            WHEN ("contractor_found_helpful" = true) THEN 1
            ELSE 0
        END) * (100)::numeric), 2) AS "helpful_percentage",
    "array_agg"(DISTINCT "issue_type") FILTER (WHERE ("issue_type" IS NOT NULL)) AS "issues_detected",
    "array_agg"(DISTINCT "contractor_type") FILTER (WHERE ("contractor_type" IS NOT NULL)) AS "contractors_needed"
   FROM "public"."maintenance_assessments"
  GROUP BY ("date"("created_at"))
  ORDER BY ("date"("created_at")) DESC;


