CREATE OR REPLACE VIEW "public"."model_ab_test_metrics" WITH ("security_invoker"='on') AS
 SELECT "t"."test_id",
    "t"."status",
    "t"."started_at",
    "count"(DISTINCT
        CASE
            WHEN ("a"."assigned_model" = 'control'::"text") THEN "a"."session_id"
            ELSE NULL::"text"
        END) AS "control_sessions",
    "count"(DISTINCT
        CASE
            WHEN ("a"."assigned_model" = 'treatment'::"text") THEN "a"."session_id"
            ELSE NULL::"text"
        END) AS "treatment_sessions",
    "avg"(
        CASE
            WHEN ("i"."model_variant" = 'control'::"text") THEN "i"."latency_ms"
            ELSE NULL::numeric
        END) AS "control_avg_latency",
    "avg"(
        CASE
            WHEN (("i"."model_variant" = 'control'::"text") AND "i"."success") THEN 1.0
            ELSE 0.0
        END) AS "control_success_rate",
    "avg"(
        CASE
            WHEN ("i"."model_variant" = 'control'::"text") THEN "i"."avg_confidence"
            ELSE NULL::numeric
        END) AS "control_avg_confidence",
    "avg"(
        CASE
            WHEN ("i"."model_variant" = 'treatment'::"text") THEN "i"."latency_ms"
            ELSE NULL::numeric
        END) AS "treatment_avg_latency",
    "avg"(
        CASE
            WHEN (("i"."model_variant" = 'treatment'::"text") AND "i"."success") THEN 1.0
            ELSE 0.0
        END) AS "treatment_success_rate",
    "avg"(
        CASE
            WHEN ("i"."model_variant" = 'treatment'::"text") THEN "i"."avg_confidence"
            ELSE NULL::numeric
        END) AS "treatment_avg_confidence",
    "count"(
        CASE
            WHEN ("i"."model_variant" = 'control'::"text") THEN 1
            ELSE NULL::integer
        END) AS "control_inferences",
    "count"(
        CASE
            WHEN ("i"."model_variant" = 'treatment'::"text") THEN 1
            ELSE NULL::integer
        END) AS "treatment_inferences"
   FROM (("public"."model_ab_tests" "t"
     LEFT JOIN "public"."model_assignments" "a" ON (("t"."test_id" = "a"."test_id")))
     LEFT JOIN "public"."model_inference_logs" "i" ON ((("t"."test_id" = "i"."test_id") AND ("a"."session_id" = "i"."session_id"))))
  GROUP BY "t"."test_id", "t"."status", "t"."started_at";


ALTER VIEW "public"."model_ab_test_metrics" OWNER TO "postgres";


COMMENT ON VIEW "public"."model_ab_test_metrics" IS 'Aggregated metrics view for quick A/B test analysis';



