CREATE MATERIALIZED VIEW "public"."mv_job_statistics" AS
 SELECT "date_trunc"('day'::"text", "created_at") AS "date",
    "status",
    "category",
    "count"(*) AS "job_count",
    "avg"("budget") AS "avg_budget",
    "sum"("budget") AS "total_budget",
    "count"(DISTINCT "homeowner_id") AS "unique_homeowners",
    "count"(DISTINCT "contractor_id") AS "unique_contractors"
   FROM "public"."jobs"
  WHERE ("created_at" >= (CURRENT_DATE - '90 days'::interval))
  GROUP BY ("date_trunc"('day'::"text", "created_at")), "status", "category"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_job_statistics" OWNER TO "postgres";


COMMENT ON MATERIALIZED VIEW "public"."mv_job_statistics" IS 'Job statistics aggregated by day, status, and category';



CREATE MATERIALIZED VIEW "public"."mv_stratum_routing_performance" AS
 SELECT "conformal_stratum",
    "property_age_category",
    "route_selected",
    "count"(*) AS "total_decisions",
    "avg"("internal_confidence") AS "avg_confidence",
    "avg"("conformal_interval_size") AS "avg_interval_size",
    (("count"(
        CASE
            WHEN ("route_selected" = 'internal'::"text") THEN 1
            ELSE NULL::integer
        END))::double precision / (NULLIF("count"(*), 0))::double precision) AS "internal_rate",
    (("count"(
        CASE
            WHEN ("route_selected" = 'hybrid'::"text") THEN 1
            ELSE NULL::integer
        END))::double precision / (NULLIF("count"(*), 0))::double precision) AS "hybrid_rate",
    (("count"(
        CASE
            WHEN ("route_selected" = 'gpt4_vision'::"text") THEN 1
            ELSE NULL::integer
        END))::double precision / (NULLIF("count"(*), 0))::double precision) AS "gpt4_rate"
   FROM "public"."hybrid_routing_decisions"
  WHERE ("conformal_calibration_used" = true)
  GROUP BY "conformal_stratum", "property_age_category", "route_selected"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_stratum_routing_performance" OWNER TO "postgres";


