COMMENT ON COLUMN "public"."reviews"."would_recommend" IS 'Reviewer''s thumbs-up/thumbs-down answer to "Would you recommend this contractor?". NULL = not answered (legacy reviews predating 2026-05-09).';



CREATE MATERIALIZED VIEW "public"."mv_user_activity" AS
 SELECT "u"."id" AS "user_id",
    "u"."role",
    "u"."is_available",
    "count"(DISTINCT "j"."id") AS "total_jobs",
    "count"(DISTINCT
        CASE
            WHEN ("j"."status" = 'completed'::"text") THEN "j"."id"
            ELSE NULL::"uuid"
        END) AS "completed_jobs",
    "count"(DISTINCT "b"."id") AS "total_bids",
    "count"(DISTINCT
        CASE
            WHEN ("b"."status" = 'accepted'::"text") THEN "b"."id"
            ELSE NULL::"uuid"
        END) AS "accepted_bids",
    "avg"("r"."rating") AS "avg_rating",
    "count"(DISTINCT "r"."id") AS "total_reviews",
    "max"("j"."created_at") AS "last_job_activity",
    "max"("b"."created_at") AS "last_bid_activity"
   FROM ((("public"."profiles" "u"
     LEFT JOIN "public"."jobs" "j" ON (("u"."id" = "j"."homeowner_id")))
     LEFT JOIN "public"."bids" "b" ON (("u"."id" = "b"."contractor_id")))
     LEFT JOIN "public"."reviews" "r" ON (("u"."id" = "r"."reviewee_id")))
  WHERE ("u"."created_at" >= (CURRENT_DATE - '90 days'::interval))
  GROUP BY "u"."id", "u"."role", "u"."is_available"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_user_activity" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_user_performance_analytics" AS
 SELECT "u"."id",
    (("u"."first_name" || ' '::"text") || "u"."last_name") AS "full_name",
    "u"."rating",
    "u"."total_jobs_completed",
    "count"(
        CASE
            WHEN (("j"."status" = 'completed'::"text") AND ("j"."completed_at" >= ("now"() - '30 days'::interval))) THEN 1
            ELSE NULL::integer
        END) AS "jobs_last_30_days",
    "avg"(
        CASE
            WHEN (("j"."status" = 'completed'::"text") AND ("j"."completed_at" >= ("now"() - '30 days'::interval))) THEN "r"."rating"
            ELSE NULL::integer
        END) AS "rating_last_30_days",
    COALESCE("sum"(
        CASE
            WHEN (("et"."status" = 'completed'::"text") AND ("et"."created_at" >= ("now"() - '30 days'::interval))) THEN "et"."amount"
            ELSE NULL::numeric
        END), (0)::numeric) AS "revenue_last_30_days"
   FROM ((("public"."profiles" "u"
     LEFT JOIN "public"."jobs" "j" ON (("u"."id" = "j"."contractor_id")))
     LEFT JOIN "public"."reviews" "r" ON (("j"."id" = "r"."job_id")))
     LEFT JOIN "public"."escrow_transactions" "et" ON (("u"."id" = "et"."payee_id")))
  WHERE (("u"."role" = 'contractor'::"text") AND ("u"."is_available" = true))
  GROUP BY "u"."id", "u"."first_name", "u"."last_name", "u"."rating", "u"."total_jobs_completed"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_user_performance_analytics" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_validated_assessments" AS
 SELECT "ba"."id" AS "assessment_id",
    "ba"."user_id",
    "ba"."damage_type",
    "ba"."severity" AS "predicted_severity",
    "ba"."confidence" AS "predicted_confidence",
    "ba"."assessment_data",
    "ba"."created_at",
    "bao"."actual_damage_type" AS "true_damage_type",
    "bao"."actual_severity" AS "true_severity",
    "bao"."outcome_type" AS "validation_source",
    "bao"."accuracy_metrics",
    (("ba"."assessment_data" ->> 'property_type'::"text"))::character varying AS "property_type",
    (("ba"."assessment_data" ->> 'construction_year'::"text"))::integer AS "construction_year",
    "public"."classify_property_age"((("ba"."assessment_data" ->> 'construction_year'::"text"))::integer) AS "property_age_category",
    "hrd"."route_selected",
    "hrd"."internal_confidence",
    "hrd"."agreement_score"
   FROM (("public"."building_assessments" "ba"
     JOIN "public"."building_assessment_outcomes" "bao" ON (("ba"."id" = "bao"."assessment_id")))
     LEFT JOIN "public"."hybrid_routing_decisions" "hrd" ON (("ba"."id" = "hrd"."assessment_id")))
  WHERE (("bao"."learning_successful" = true) AND ("bao"."actual_severity" IS NOT NULL) AND (("ba"."validation_status")::"text" = 'validated'::"text"))
  ORDER BY "ba"."created_at" DESC
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_validated_assessments" OWNER TO "postgres";


COMMENT ON MATERIALIZED VIEW "public"."mv_validated_assessments" IS 'Consolidated view of assessments with ground truth for calibration';



