CREATE TABLE IF NOT EXISTS "public"."notification_engagement" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "notification_id" "uuid" NOT NULL,
    "notification_type" character varying(50) NOT NULL,
