    "clicked" boolean DEFAULT false,
    "dismissed" boolean DEFAULT false,
    "opened_at" timestamp with time zone,
    "clicked_at" timestamp with time zone,
    "dismissed_at" timestamp with time zone,
    "sent_at" timestamp with time zone NOT NULL,
    "engagement_delay_seconds" integer,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "device_type" character varying(20),
    "channel" character varying(30),
    "time_of_day_sent" integer,
    "day_of_week_sent" integer,
    "action_completed" boolean DEFAULT false,
    "action_completed_at" timestamp with time zone,
    "batch_id" "uuid",
    CONSTRAINT "notification_engagement_channel_check" CHECK ((("channel")::"text" = ANY ((ARRAY['in_app'::character varying, 'email'::character varying, 'sms'::character varying, 'push'::character varying, 'browser'::character varying])::"text"[]))),
    CONSTRAINT "notification_engagement_day_of_week_sent_check" CHECK ((("day_of_week_sent" >= 0) AND ("day_of_week_sent" <= 6))),
    CONSTRAINT "notification_engagement_device_type_check" CHECK ((("device_type")::"text" = ANY ((ARRAY['mobile'::character varying, 'tablet'::character varying, 'desktop'::character varying, 'push'::character varying])::"text"[]))),
    CONSTRAINT "notification_engagement_time_of_day_sent_check" CHECK ((("time_of_day_sent" >= 0) AND ("time_of_day_sent" <= 23)))
);


ALTER TABLE "public"."notification_engagement" OWNER TO "postgres";


COMMENT ON COLUMN "public"."notification_engagement"."device_type" IS 'Device type where notification was received';



COMMENT ON COLUMN "public"."notification_engagement"."channel" IS 'Notification channel: in_app, email, sms, push, browser';



COMMENT ON COLUMN "public"."notification_engagement"."time_of_day_sent" IS 'Hour of day when notification was sent (0-23 UTC)';



COMMENT ON COLUMN "public"."notification_engagement"."day_of_week_sent" IS 'Day of week when notification was sent (0=Sunday, 6=Saturday)';



COMMENT ON COLUMN "public"."notification_engagement"."action_completed" IS 'Whether the user completed the intended action from the notification';



CREATE MATERIALIZED VIEW "public"."notification_engagement_analytics" AS
 SELECT "notification_type",
    "channel",
    "time_of_day_sent",
    "day_of_week_sent",
    "device_type",
    "count"(*) AS "total_sent",
    "count"(DISTINCT "user_id") AS "unique_users",
    ((("sum"(
        CASE
            WHEN "opened" THEN 1
            ELSE 0
        END))::double precision / ("count"(*))::double precision) * (100)::double precision) AS "open_rate",
    ((("sum"(
        CASE
            WHEN "clicked" THEN 1
            ELSE 0
        END))::double precision / ("count"(*))::double precision) * (100)::double precision) AS "click_rate",
    ((("sum"(
        CASE
            WHEN "dismissed" THEN 1
            ELSE 0
        END))::double precision / ("count"(*))::double precision) * (100)::double precision) AS "dismiss_rate",
    ((("sum"(
        CASE
            WHEN "action_completed" THEN 1
            ELSE 0
        END))::double precision / ("count"(*))::double precision) * (100)::double precision) AS "action_completion_rate",
    "avg"("engagement_delay_seconds") AS "avg_engagement_delay_seconds",
    "percentile_cont"((0.5)::double precision) WITHIN GROUP (ORDER BY (("engagement_delay_seconds")::double precision)) AS "median_engagement_delay_seconds",
    "min"("engagement_delay_seconds") AS "min_engagement_delay_seconds",
    "max"("engagement_delay_seconds") AS "max_engagement_delay_seconds",
    "min"("sent_at") AS "period_start",
    "max"("sent_at") AS "period_end",
    "count"(*) FILTER (WHERE ("sent_at" >= ("now"() - '7 days'::interval))) AS "last_7_days_count",
    "count"(*) FILTER (WHERE ("sent_at" >= ("now"() - '30 days'::interval))) AS "last_30_days_count"
   FROM "public"."notification_engagement"
  WHERE ("sent_at" >= ("now"() - '90 days'::interval))
  GROUP BY "notification_type", "channel", "time_of_day_sent", "day_of_week_sent", "device_type"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."notification_engagement_analytics" OWNER TO "postgres";


COMMENT ON MATERIALIZED VIEW "public"."notification_engagement_analytics" IS 'Aggregated engagement metrics by type, channel, time, and device';



