    "currency" character varying(3) DEFAULT 'gbp'::character varying,
    "payment_method" character varying(50),
    "stripe_payment_intent_id" character varying(255),
    "stripe_charge_id" character varying(255),
    "transaction_id" "text",
    "status" character varying(50) DEFAULT 'pending'::character varying,
    "description" "text",
    "platform_fee" numeric(10,2) DEFAULT 0,
    "processing_fee" numeric(10,2) DEFAULT 0,
    "net_amount" numeric(10,2),
    "payment_date" timestamp with time zone DEFAULT "now"(),
    "processed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb",
    CONSTRAINT "payments_amount_check" CHECK (("amount" > (0)::numeric)),
    CONSTRAINT "payments_amount_positive" CHECK (("amount" > (0)::numeric)),
    CONSTRAINT "payments_payment_method_check" CHECK ((("payment_method")::"text" = ANY ((ARRAY['credit_card'::character varying, 'debit_card'::character varying, 'bank_transfer'::character varying, 'paypal'::character varying, 'stripe'::character varying, 'cash'::character varying, 'check'::character varying])::"text"[]))),
    CONSTRAINT "payments_platform_fee_check" CHECK (("platform_fee" >= (0)::numeric)),
    CONSTRAINT "payments_processing_fee_check" CHECK (("processing_fee" >= (0)::numeric)),
    CONSTRAINT "payments_status_check" CHECK ((("status")::"text" = ANY ((ARRAY['pending'::character varying, 'processing'::character varying, 'completed'::character varying, 'failed'::character varying, 'refunded'::character varying, 'cancelled'::character varying])::"text"[])))
);


ALTER TABLE "public"."payments" OWNER TO "postgres";


COMMENT ON TABLE "public"."payments" IS 'Payment transactions between homeowners (payers) and contractors (payees)';



COMMENT ON COLUMN "public"."payments"."payer_id" IS 'User who pays (typically homeowner) - used for spending queries';



COMMENT ON COLUMN "public"."payments"."payee_id" IS 'User who receives payment (typically contractor) - used for earnings queries';



