CREATE OR REPLACE VIEW "public"."rls_coverage_check" WITH ("security_invoker"='on') AS
 SELECT "tablename",
    "rowsecurity",
        CASE
            WHEN "rowsecurity" THEN 'Protected'::"text"
            ELSE 'UNPROTECTED'::"text"
        END AS "status",
    ( SELECT "count"(*) AS "count"
           FROM "pg_policies" "p"
          WHERE (("p"."schemaname" = 'public'::"name") AND ("p"."tablename" = "t"."tablename"))) AS "policy_count"
   FROM "pg_tables" "t"
  WHERE (("schemaname" = 'public'::"name") AND ("tablename" !~~ 'pg_%'::"text"))
  ORDER BY "rowsecurity" DESC, "tablename";


ALTER VIEW "public"."rls_coverage_check" OWNER TO "postgres";


