    "used_fallback" boolean DEFAULT false,
    "search_method" character varying(20) DEFAULT 'semantic'::character varying,
    CONSTRAINT "search_analytics_device_type_check" CHECK ((("device_type")::"text" = ANY ((ARRAY['mobile'::character varying, 'tablet'::character varying, 'desktop'::character varying])::"text"[]))),
    CONSTRAINT "search_analytics_search_method_check" CHECK ((("search_method")::"text" = ANY ((ARRAY['semantic'::character varying, 'full-text'::character varying])::"text"[]))),
    CONSTRAINT "search_analytics_search_type_check" CHECK ((("search_type")::"text" = ANY ((ARRAY['general'::character varying, 'jobs'::character varying, 'contractors'::character varying, 'semantic'::character varying, 'filters'::character varying])::"text"[])))
);


