CREATE TABLE IF NOT EXISTS "public"."search_suggestions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "suggestion_text" "text" NOT NULL,
    "suggestion_type" character varying(50) DEFAULT 'query'::character varying,
    "usage_count" integer DEFAULT 0,
    "click_count" integer DEFAULT 0,
    "acceptance_rate" numeric(5,2) GENERATED ALWAYS AS (
CASE
    WHEN ("usage_count" > 0) THEN ((("click_count")::numeric / ("usage_count")::numeric) * (100)::numeric)
    ELSE (0)::numeric
END) STORED,
    "category" "text",
    "location" "text",
    "is_active" boolean DEFAULT true,
    "is_auto_generated" boolean DEFAULT false,
    "last_used_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    CONSTRAINT "search_suggestions_suggestion_type_check" CHECK ((("suggestion_type")::"text" = ANY ((ARRAY['query'::character varying, 'category'::character varying, 'location'::character varying, 'contractor'::character varying, 'service'::character varying])::"text"[])))
);


