COMMENT ON COLUMN "public"."search_suggestions"."is_auto_generated" IS 'Whether suggestion was auto-generated from search analytics vs manually curated';



CREATE OR REPLACE VIEW "public"."security_dashboard" WITH ("security_invoker"='on') AS
 SELECT "date_trunc"('hour'::"text", "created_at") AS "hour",
    "event_type",
    "severity",
    "count"(*) AS "event_count",
    "count"(DISTINCT "user_id") AS "unique_users",
    "count"(DISTINCT "ip_address") AS "unique_ips"
   FROM "public"."security_events"
  WHERE ("created_at" >= ("now"() - '24:00:00'::interval))
  GROUP BY ("date_trunc"('hour'::"text", "created_at")), "event_type", "severity"
  ORDER BY ("date_trunc"('hour'::"text", "created_at")) DESC, ("count"(*)) DESC;


