CREATE OR REPLACE VIEW "public"."suspicious_ips" WITH ("security_invoker"='on') AS
 SELECT "ip_address",
    "count"(*) AS "total_events",
    "count"(DISTINCT "event_type") AS "event_types",
    "count"(DISTINCT "user_id") AS "unique_users",
    "max"("created_at") AS "last_activity"
   FROM "public"."security_events"
  WHERE (("created_at" >= ("now"() - '7 days'::interval)) AND ("severity" = ANY (ARRAY['high'::"text", 'critical'::"text"])))
  GROUP BY "ip_address"
 HAVING ("count"(*) >= 10)
  ORDER BY ("count"(*)) DESC;


