    "acknowledged" boolean DEFAULT false,
    "acknowledged_by" "uuid",
    "acknowledged_at" timestamp with time zone,
    "resolved" boolean DEFAULT false,
    "resolved_by" "uuid",
    "resolved_at" timestamp with time zone,
    "resolution_notes" "text",
    "created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "system_alerts_severity_check" CHECK (("severity" = ANY (ARRAY['info'::"text", 'warning'::"text", 'critical'::"text"]))),
    CONSTRAINT "valid_acknowledgment" CHECK ((("acknowledged" = false) OR (("acknowledged" = true) AND ("acknowledged_by" IS NOT NULL) AND ("acknowledged_at" IS NOT NULL)))),
    CONSTRAINT "valid_resolution" CHECK ((("resolved" = false) OR (("resolved" = true) AND ("resolved_by" IS NOT NULL) AND ("resolved_at" IS NOT NULL))))
