CREATE OR REPLACE VIEW "public"."table_sizes" WITH ("security_invoker"='on') AS
 SELECT 'public'::"text" AS "schemaname",
    "table_name" AS "tablename",
    "pg_size_pretty"("pg_total_relation_size"((('public.'::"text" || ("table_name")::"text"))::"regclass")) AS "size",
    "pg_total_relation_size"((('public.'::"text" || ("table_name")::"text"))::"regclass") AS "size_bytes"
   FROM "information_schema"."tables"
  WHERE ((("table_schema")::"name" = 'public'::"name") AND (("table_type")::"text" = 'BASE TABLE'::"text"))
  ORDER BY ("pg_total_relation_size"((('public.'::"text" || ("table_name")::"text"))::"regclass")) DESC;


