CREATE OR REPLACE VIEW "public"."training_data_status" WITH ("security_invoker"='on') AS
 SELECT 'corrections'::"text" AS "data_source",
    "count"(*) AS "total_samples",
    "count"(
        CASE
            WHEN (("maintenance_corrections"."status")::"text" = 'approved'::"text") THEN 1
            ELSE NULL::integer
        END) AS "approved_samples",
    "count"(
        CASE
            WHEN (("maintenance_corrections"."used_in_training" = false) AND (("maintenance_corrections"."status")::"text" = 'approved'::"text")) THEN 1
            ELSE NULL::integer
        END) AS "ready_for_training",
    "max"("maintenance_corrections"."created_at") AS "latest_sample"
   FROM "public"."maintenance_corrections"
UNION ALL
 SELECT 'training_labels'::"text" AS "data_source",
    "count"(*) AS "total_samples",
    "count"(
        CASE
            WHEN ("maintenance_training_labels"."human_verified" = true) THEN 1
            ELSE NULL::integer
        END) AS "approved_samples",
    "count"(
        CASE
            WHEN (("maintenance_training_labels"."used_in_training" = false) AND ("maintenance_training_labels"."human_verified" = true)) THEN 1
            ELSE NULL::integer
        END) AS "ready_for_training",
    "max"("maintenance_training_labels"."created_at") AS "latest_sample"
   FROM "public"."maintenance_training_labels";


ALTER VIEW "public"."training_data_status" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."trending_searches" AS
 SELECT "search_query",
    "search_type",
    "category_filter",
    "location_filter",
    "count"(*) AS "search_count",
    "count"(DISTINCT "user_id") AS "unique_users",
    "avg"("results_count") AS "avg_results",
    (("sum"(
        CASE
            WHEN "zero_results" THEN 1
            ELSE 0
        END))::double precision / ("count"(*))::double precision) AS "zero_results_rate",
    (("sum"(
        CASE
            WHEN (("clicked_results" IS NOT NULL) AND ("array_length"("clicked_results", 1) > 0)) THEN 1
            ELSE 0
        END))::double precision / ("count"(*))::double precision) AS "click_through_rate",
    "max"("timestamp") AS "last_searched_at"
   FROM "public"."search_analytics"
  WHERE ("timestamp" >= ("now"() - '7 days'::interval))
  GROUP BY "search_query", "search_type", "category_filter", "location_filter"
 HAVING ("count"(*) >= 3)
  ORDER BY ("count"(*)) DESC, ("max"("timestamp")) DESC
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."trending_searches" OWNER TO "postgres";


COMMENT ON MATERIALIZED VIEW "public"."trending_searches" IS 'Aggregated trending searches from the last 7 days, refreshed periodically';



