CREATE OR REPLACE VIEW "public"."v_calibration_summary" WITH ("security_invoker"='on') AS
 SELECT "cs"."id",
    "cs"."set_name",
    "cs"."set_type",
    "cs"."stratum",
    "cs"."sample_count",
    "cs"."mean_confidence",
    "cs"."std_confidence",
    "cs"."is_active",
    "cs"."created_at",
    "count"(DISTINCT "ct"."confidence_level") AS "threshold_levels",
    "max"("pm"."empirical_coverage") AS "latest_coverage",
    "max"("pm"."avg_interval_size") AS "latest_avg_interval_size"
   FROM (("public"."conformal_calibration_sets" "cs"
     LEFT JOIN "public"."conformal_thresholds" "ct" ON (("cs"."id" = "ct"."calibration_set_id")))
     LEFT JOIN "public"."conformal_performance_metrics" "pm" ON (("cs"."id" = "pm"."calibration_set_id")))
  GROUP BY "cs"."id", "cs"."set_name", "cs"."set_type", "cs"."stratum", "cs"."sample_count", "cs"."mean_confidence", "cs"."std_confidence", "cs"."is_active", "cs"."created_at";


ALTER VIEW "public"."v_calibration_summary" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_calibration_summary" IS 'Summary view of all calibration sets with performance metrics';



CREATE OR REPLACE VIEW "public"."v_conformal_routing_analytics" WITH ("security_invoker"='on') AS
 SELECT "date_trunc"('day'::"text", "created_at") AS "date",
    "route_selected",
    "conformal_calibration_used",
    "conformal_interval_size",
    "conformal_stratum",
    "property_age_category",
    "count"(*) AS "decision_count",
    "avg"("internal_confidence") AS "avg_confidence",
    "avg"("inference_time_ms") AS "avg_inference_time",
    "avg"("agreement_score") AS "avg_agreement_score",
    "count"(
        CASE
            WHEN ("conformal_interval_size" = 1) THEN 1
            ELSE NULL::integer
        END) AS "certain_predictions",
    "count"(
        CASE
            WHEN ("conformal_interval_size" = 2) THEN 1
            ELSE NULL::integer
        END) AS "moderate_uncertainty",
    "count"(
        CASE
            WHEN ("conformal_interval_size" >= 3) THEN 1
            ELSE NULL::integer
        END) AS "high_uncertainty"
   FROM "public"."hybrid_routing_decisions"
  GROUP BY ("date_trunc"('day'::"text", "created_at")), "route_selected", "conformal_calibration_used", "conformal_interval_size", "conformal_stratum", "property_age_category";


ALTER VIEW "public"."v_conformal_routing_analytics" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_contractor_stats" WITH ("security_invoker"='true') AS
 SELECT "u"."id",
    "u"."first_name",
    "u"."last_name",
    "count"(DISTINCT "j"."id") FILTER (WHERE ("j"."status" = 'completed'::"text")) AS "completed_jobs",
    "avg"("r"."rating") AS "avg_rating",
    "count"(DISTINCT "r"."id") AS "total_reviews"
   FROM (("public"."profiles" "u"
     LEFT JOIN "public"."jobs" "j" ON (("j"."contractor_id" = "u"."id")))
     LEFT JOIN "public"."reviews" "r" ON (("r"."job_id" = "j"."id")))
  WHERE ("u"."role" = 'contractor'::"text")
  GROUP BY "u"."id", "u"."first_name", "u"."last_name";


ALTER VIEW "public"."v_contractor_stats" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_fnr_edge_cases" WITH ("security_invoker"='on') AS
 SELECT "stratum",
    "fnr",
    "fnr_upper_bound",
    "total_automated",
    "confidence_level",
        CASE
            WHEN ("total_automated" < 10) THEN 'insufficient_sample_size'::"text"
            WHEN (("fnr_upper_bound" >= 0.05) AND ("total_automated" < 30)) THEN 'high_fnr_low_confidence'::"text"
            WHEN ("fnr" > 0.10) THEN 'very_high_fnr'::"text"
            WHEN ("fnr_upper_bound" >= 0.10) THEN 'very_high_fnr_upper_bound'::"text"
            ELSE NULL::"text"
        END AS "edge_case_type",
    "last_escalation_at"
   FROM "public"."ab_critic_fnr_tracking"
  WHERE (("total_automated" < 10) OR (("fnr_upper_bound" >= 0.05) AND ("total_automated" < 30)) OR ("fnr" > 0.10) OR ("fnr_upper_bound" >= 0.10))
  ORDER BY
        CASE
            WHEN ("fnr_upper_bound" >= 0.10) THEN 1
            WHEN ("total_automated" < 10) THEN 2
            WHEN ("fnr" > 0.10) THEN 3
            ELSE 4
        END, "fnr_upper_bound" DESC;


ALTER VIEW "public"."v_fnr_edge_cases" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_fnr_edge_cases" IS 'Edge cases requiring human attention (insufficient data, high FNR, etc.)';



CREATE OR REPLACE VIEW "public"."v_fnr_monitoring_summary" WITH ("security_invoker"='on') AS
 SELECT
        CASE
            WHEN ("total_automated" >= 100) THEN 'high_confidence'::"text"
            WHEN ("total_automated" >= 30) THEN 'medium_confidence'::"text"
            WHEN ("total_automated" >= 10) THEN 'low_confidence'::"text"
            ELSE 'insufficient_data'::"text"
        END AS "confidence_category",
    "count"(*) AS "stratum_count",
    "avg"("fnr") AS "avg_fnr",
    "avg"("fnr_upper_bound") AS "avg_fnr_upper_bound",
    "max"("fnr_upper_bound") AS "max_fnr_upper_bound",
    "sum"(
        CASE
            WHEN ("fnr_upper_bound" >= 0.05) THEN 1
            ELSE 0
        END) AS "strata_exceeding_threshold",
    "avg"("total_automated") AS "avg_sample_size",
    "sum"("escalation_count") AS "total_escalations"
   FROM "public"."ab_critic_fnr_tracking"
  GROUP BY
        CASE
            WHEN ("total_automated" >= 100) THEN 'high_confidence'::"text"
            WHEN ("total_automated" >= 30) THEN 'medium_confidence'::"text"
            WHEN ("total_automated" >= 10) THEN 'low_confidence'::"text"
            ELSE 'insufficient_data'::"text"
        END;


ALTER VIEW "public"."v_fnr_monitoring_summary" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_fnr_monitoring_summary" IS 'Summary of FNR statistics grouped by confidence level';



CREATE OR REPLACE VIEW "public"."v_fnr_recent_escalations" WITH ("security_invoker"='on') AS
 SELECT "stratum",
    "fnr",
    "fnr_upper_bound",
    "total_automated",
    "escalation_count",
    "last_escalation_at",
    (("fnr_upper_bound" - 0.05) * (100)::numeric) AS "excess_fnr_percentage"
   FROM "public"."ab_critic_fnr_tracking"
  WHERE (("last_escalation_at" IS NOT NULL) AND ("last_escalation_at" > ("now"() - '7 days'::interval)))
  ORDER BY "last_escalation_at" DESC
 LIMIT 100;


ALTER VIEW "public"."v_fnr_recent_escalations" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_fnr_recent_escalations" IS 'Recent escalations due to FNR violations (last 7 days)';



