CREATE TABLE IF NOT EXISTS "public"."yolo_models" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "model_name" character varying(100) NOT NULL,
    "model_version" character varying(20) NOT NULL,
    "model_data" "bytea",
    "file_size" bigint NOT NULL,
    "description" "text",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "storage_path" "text" NOT NULL,
    "storage_bucket" "text" DEFAULT 'yolo-models'::"text",
    "storage_url" "text",
    "storage_migration_status" "text",
    "storage_migrated_at" timestamp with time zone,
    "checksum" "text",
    "model_type" character varying(20) DEFAULT 'onnx'::character varying,
    "is_active" boolean DEFAULT false,
    "status" character varying(20) DEFAULT 'deployed'::character varying,
    "performance_metrics" "jsonb",
    "training_date" timestamp with time zone,
    "training_samples_count" integer,
    "deployed_at" timestamp with time zone,
    "deprecated_at" timestamp with time zone,
    "version" "text" NOT NULL,
    "filename" "text" NOT NULL,
    "metrics" "jsonb" DEFAULT '{}'::"jsonb",
    "training_config" "jsonb" DEFAULT '{}'::"jsonb",
    "uploaded_by" "uuid",
    "domain_id" "text" DEFAULT 'residential'::"text",
    "deployment_target" "text" DEFAULT 'cloud'::"text",
    "quantization_type" "text" DEFAULT 'fp32'::"text",
    "latency_ms" double precision,
    "model_size_bytes" bigint,
    "student_of" "text",
    CONSTRAINT "valid_file_size" CHECK ((("file_size" > 0) AND ("file_size" <= 104857600))),
    CONSTRAINT "yolo_models_model_type_check" CHECK ((("model_type")::"text" = ANY ((ARRAY['onnx'::character varying, 'tflite'::character varying, 'pytorch'::character varying, 'tensorflow'::character varying, 'coreml'::character varying])::"text"[]))),
    CONSTRAINT "yolo_models_status_check" CHECK ((("status")::"text" = ANY ((ARRAY['pending'::character varying, 'deployed'::character varying, 'deprecated'::character varying, 'failed'::character varying])::"text"[]))),
    CONSTRAINT "yolo_models_storage_migration_status_check" CHECK (("storage_migration_status" = ANY (ARRAY['pending'::"text", 'in_progress'::"text", 'completed'::"text", 'failed'::"text"])))
);


ALTER TABLE "public"."yolo_models" OWNER TO "postgres";


COMMENT ON TABLE "public"."yolo_models" IS 'Tracks all YOLO model versions uploaded to Supabase storage with their metrics and configuration';



COMMENT ON COLUMN "public"."yolo_models"."model_data" IS 'ONNX model file stored as binary data. Large files (>10MB) will impact database performance.';



COMMENT ON COLUMN "public"."yolo_models"."file_size" IS 'Model file size in bytes';



COMMENT ON COLUMN "public"."yolo_models"."description" IS 'Human-readable description of what makes this model version different';



COMMENT ON COLUMN "public"."yolo_models"."storage_path" IS 'Path to model file in Supabase Storage bucket (e.g., models/yolov11/v1.0/model.onnx)';



COMMENT ON COLUMN "public"."yolo_models"."storage_bucket" IS 'Storage bucket name where model is stored (default: yolo-models)';



COMMENT ON COLUMN "public"."yolo_models"."storage_url" IS 'Public or signed URL for accessing the model from storage';



COMMENT ON COLUMN "public"."yolo_models"."storage_migration_status" IS 'Track migration status from BYTEA to Storage (pending/in_progress/completed/failed)';



COMMENT ON COLUMN "public"."yolo_models"."checksum" IS 'SHA256 hash of model file for integrity verification';



COMMENT ON COLUMN "public"."yolo_models"."model_type" IS 'Type of model format (onnx, tflite, pytorch, tensorflow, coreml)';



COMMENT ON COLUMN "public"."yolo_models"."is_active" IS 'Indicates if this is the currently active model version for inference';



COMMENT ON COLUMN "public"."yolo_models"."status" IS 'Deployment status of the model (pending, deployed, deprecated, failed)';



COMMENT ON COLUMN "public"."yolo_models"."performance_metrics" IS 'JSON object containing model performance metrics (mAP, precision, recall, F1, etc.)';



COMMENT ON COLUMN "public"."yolo_models"."training_samples_count" IS 'Number of training samples used to train this model version';



COMMENT ON COLUMN "public"."yolo_models"."version" IS 'Semantic version of the model (e.g., v1.0.0, v2.1.0)';



COMMENT ON COLUMN "public"."yolo_models"."filename" IS 'Filename in Supabase storage';



COMMENT ON COLUMN "public"."yolo_models"."metrics" IS 'JSON object with model performance metrics (mAP50, precision, recall, etc.)';



COMMENT ON COLUMN "public"."yolo_models"."training_config" IS 'JSON object with training configuration details';



CREATE OR REPLACE VIEW "public"."yolo_models_comparison" WITH ("security_invoker"='on') AS
 SELECT COALESCE("version", ("model_version")::"text") AS "version",
    COALESCE("filename", ("model_name")::"text") AS "filename",
    "file_size",
    (("metrics" ->> 'mAP50'::"text"))::numeric AS "map50",
    (("metrics" ->> 'mAP50_95'::"text"))::numeric AS "map50_95",
    (("metrics" ->> 'precision'::"text"))::numeric AS "precision",
    (("metrics" ->> 'recall'::"text"))::numeric AS "recall",
    "is_active",
    "created_at",
    "description"
   FROM "public"."yolo_models"
  ORDER BY "created_at" DESC;


ALTER VIEW "public"."yolo_models_comparison" OWNER TO "postgres";


COMMENT ON VIEW "public"."yolo_models_comparison" IS 'Simplified view for comparing model versions and their performance metrics';



