    "config_jsonb" "jsonb" DEFAULT '{}'::"jsonb",
    "created_at" timestamp with time zone DEFAULT "now"(),
    CONSTRAINT "yolo_retraining_jobs_status_check" CHECK ((("status")::"text" = ANY ((ARRAY['pending'::character varying, 'running'::character varying, 'completed'::character varying, 'failed'::character varying])::"text"[])))
);


ALTER TABLE "public"."yolo_retraining_jobs" OWNER TO "postgres";


COMMENT ON TABLE "public"."yolo_retraining_jobs" IS 'Tracks YOLO model retraining jobs for continuous learning. Each job represents a training run that merges base dataset with user corrections.';



COMMENT ON COLUMN "public"."yolo_retraining_jobs"."model_version" IS 'Version identifier for the trained model (e.g., continuous-learning-v20250301_120000).';



COMMENT ON COLUMN "public"."yolo_retraining_jobs"."metrics_jsonb" IS 'Model performance metrics after training: mAP50, mAP50-95, precision, recall.';



CREATE OR REPLACE VIEW "public"."yolo_savings_analytics" WITH ("security_invoker"='on') AS
 SELECT "date_trunc"('day'::"text", "created_at") AS "date",
    "count"(*) AS "total_assessments",
    "count"(*) FILTER (WHERE ("yolo_skipped" = true)) AS "yolo_skipped",
    "round"(((("count"(*) FILTER (WHERE ("yolo_skipped" = true)))::numeric / (NULLIF("count"(*), 0))::numeric) * (100)::numeric), 2) AS "skip_rate_percentage",
    ("count"(*) FILTER (WHERE ("yolo_skipped" = true)) * 2000) AS "estimated_time_saved_ms",
    "round"("avg"((("presence_detection" ->> 'averagePresenceScore'::"text"))::numeric) FILTER (WHERE ("presence_detection" IS NOT NULL)), 3) AS "avg_presence_score",
    "array_agg"(DISTINCT ("presence_detection" ->> 'damageTypes'::"text")) FILTER (WHERE (("presence_detection" ->> 'damageDetected'::"text") = 'true'::"text")) AS "damage_types_detected"
   FROM "public"."hybrid_routing_decisions"
  WHERE ("created_at" >= (CURRENT_DATE - '30 days'::interval))
  GROUP BY ("date_trunc"('day'::"text", "created_at"))
  ORDER BY ("date_trunc"('day'::"text", "created_at")) DESC;


ALTER VIEW "public"."yolo_savings_analytics" OWNER TO "postgres";


