  WHERE (("profiles"."id" = ( SELECT "auth"."uid"() AS "uid")) AND ("profiles"."role" = 'contractor'::"text"))))) OR (EXISTS ( SELECT 1
   FROM "public"."jobs"
  WHERE (("jobs"."id" = "saved_jobs"."job_id") AND ("jobs"."homeowner_id" = ( SELECT "auth"."uid"() AS "uid"))))))));



CREATE POLICY "select_consolidated" ON "public"."system_alerts" FOR SELECT USING (((EXISTS ( SELECT 1
   FROM "public"."profiles" "u"
  WHERE (("u"."id" = ( SELECT "auth"."uid"() AS "uid")) AND ("u"."role" = 'admin'::"text")))) OR
CASE
    WHEN (( SELECT "auth"."role"() AS "role") = 'authenticated'::"text") THEN ("severity" = ANY (ARRAY['info'::"text", 'warning'::"text"]))
    ELSE false
END));



