   FROM "public"."profiles"
  WHERE (("profiles"."id" = ( SELECT "auth"."uid"() AS "uid")) AND ("profiles"."role" = 'admin'::"text")))) OR ("contractor_id" = ( SELECT "auth"."uid"() AS "uid")) OR (( SELECT "auth"."uid"() AS "uid") = "contractor_id")))) WITH CHECK ((("contractor_id" = ( SELECT "auth"."uid"() AS "uid")) OR (( SELECT "auth"."role"() AS "role") = 'service_role'::"text") OR (("contractor_id" = ( SELECT "auth"."uid"() AS "uid")) OR (( SELECT "auth"."uid"() AS "uid") = "contractor_id"))));



CREATE POLICY "update_consolidated" ON "public"."job_guarantees" FOR UPDATE USING (((EXISTS ( SELECT 1
   FROM "public"."jobs" "j"
  WHERE (("j"."id" = "job_guarantees"."job_id") AND (("j"."homeowner_id" = ( SELECT "auth"."uid"() AS "uid")) OR ("j"."contractor_id" = ( SELECT "auth"."uid"() AS "uid"))) AND (("job_guarantees"."status")::"text" = ANY (ARRAY[('pending'::character varying)::"text", ('investigating'::character varying)::"text"]))))) OR (EXISTS ( SELECT 1
   FROM "public"."profiles"
  WHERE (("profiles"."id" = ( SELECT "auth"."uid"() AS "uid")) AND ("profiles"."role" = 'admin'::"text")))) OR ((EXISTS ( SELECT 1
   FROM "public"."jobs" "j"
  WHERE (("j"."id" = "job_guarantees"."job_id") AND (("j"."homeowner_id" = ( SELECT "auth"."uid"() AS "uid")) OR (EXISTS ( SELECT 1
           FROM "public"."bids" "b"
          WHERE (("b"."job_id" = "j"."id") AND ("b"."contractor_id" = ( SELECT "auth"."uid"() AS "uid"))))))))) OR (( SELECT "auth"."role"() AS "role") = 'service_role'::"text")))) WITH CHECK (((EXISTS ( SELECT 1
   FROM "public"."jobs" "j"
  WHERE (("j"."id" = "job_guarantees"."job_id") AND (("j"."homeowner_id" = ( SELECT "auth"."uid"() AS "uid")) OR ("j"."contractor_id" = ( SELECT "auth"."uid"() AS "uid")))))) OR (EXISTS ( SELECT 1
   FROM "public"."profiles"
  WHERE (("profiles"."id" = ( SELECT "auth"."uid"() AS "uid")) AND ("profiles"."role" = 'admin'::"text")))) OR (EXISTS ( SELECT 1
   FROM "public"."jobs" "j"
  WHERE (("j"."id" = "job_guarantees"."job_id") AND (("j"."homeowner_id" = ( SELECT "auth"."uid"() AS "uid")) OR (EXISTS ( SELECT 1
           FROM "public"."bids" "b"
          WHERE (("b"."job_id" = "j"."id") AND ("b"."contractor_id" = ( SELECT "auth"."uid"() AS "uid")))))))))));



