  WITH CHECK (((bucket_id = 'contractor-documents'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)));

CREATE POLICY "Job participants can upload job photos" ON "storage"."objects"
  FOR INSERT
  TO "authenticated"
  WITH CHECK (((bucket_id = 'Job-storage'::text) AND (EXISTS ( SELECT 1
   FROM public.jobs
  WHERE (((jobs.id)::text = (storage.foldername(objects.name))[1]) AND ((jobs.homeowner_id = auth.uid()) OR (jobs.contractor_id = auth.uid())))))));

CREATE POLICY "Job participants can view job attachments" ON "storage"."objects"
  FOR SELECT
  TO "authenticated"
  USING (((bucket_id = 'job-attachments'::text) AND (EXISTS ( SELECT 1
   FROM public.jobs
  WHERE (((jobs.id)::text = (storage.foldername(objects.name))[1]) AND ((jobs.homeowner_id = auth.uid()) OR (jobs.contractor_id = auth.uid())))))));

CREATE POLICY "Job participants can view job photos" ON "storage"."objects"
  FOR SELECT
  TO "authenticated"
  USING (((bucket_id = 'Job-storage'::text) AND ((EXISTS ( SELECT 1
   FROM public.jobs
  WHERE (((jobs.id)::text = (storage.foldername(objects.name))[1]) AND ((jobs.homeowner_id = auth.uid()) OR (jobs.contractor_id = auth.uid()))))) OR
    (((storage.foldername(name))[1] = 'job-photos'::text) AND (array_length(storage.foldername(name), 1) >= 2) AND (EXISTS ( SELECT 1
   FROM public.jobs
  WHERE (((jobs.id)::text = (storage.foldername(objects.name))[2]) AND ((jobs.homeowner_id = auth.uid()) OR (jobs.contractor_id = auth.uid())))))))));

