CREATE POLICY "assessment_photos_insert_own" ON "storage"."objects"
  FOR INSERT
  TO "authenticated"
  WITH
    CHECK
    (((bucket_id = 'assessment-photos'::text) AND ((((storage.foldername(name))[1] = 'quick-ai'::text) AND ((storage.foldername(name))[2] = (( SELECT auth.uid() AS uid))::text)) OR
    (((storage.foldername(name))[1] = 'assessments'::text) AND (EXISTS ( SELECT 1
   FROM public.building_assessments ba
  WHERE (((ba.id)::text = (storage.foldername(objects.name))[2]) AND (ba.user_id = ( SELECT auth.uid() AS uid)))))))));

CREATE POLICY "assessment_photos_update_own" ON "storage"."objects"
  FOR UPDATE
  TO "authenticated"
  USING
    (((bucket_id = 'assessment-photos'::text) AND ((((storage.foldername(name))[1] = 'quick-ai'::text) AND ((storage.foldername(name))[2] = (( SELECT auth.uid() AS uid))::text)) OR
    (((storage.foldername(name))[1] = 'assessments'::text) AND (EXISTS ( SELECT 1
   FROM public.building_assessments ba
  WHERE (((ba.id)::text = (storage.foldername(objects.name))[2]) AND (ba.user_id = ( SELECT auth.uid() AS uid)))))))))
  WITH
    CHECK
    (((bucket_id = 'assessment-photos'::text) AND ((((storage.foldername(name))[1] = 'quick-ai'::text) AND ((storage.foldername(name))[2] = (( SELECT auth.uid() AS uid))::text)) OR
    (((storage.foldername(name))[1] = 'assessments'::text) AND (EXISTS ( SELECT 1
   FROM public.building_assessments ba
  WHERE (((ba.id)::text = (storage.foldername(objects.name))[2]) AND (ba.user_id = ( SELECT auth.uid() AS uid)))))))));


